static const RBorrowOriginSet *r_semantic_borrow_origin_set(const RFrontendContext *context,
                                                            uint32_t set_id) {
    if ((set_id == UINT32_C(0)) || ((size_t)set_id > context->borrow_origin_set_count)) {
        return NULL;
    }
    return &context->borrow_origin_sets[(size_t)set_id - 1U];
}

static bool r_semantic_append_borrow_origins(RFrontendContext *context,
                                             RSymbolVector *origins,
                                             RSymbolId origin,
                                             uint32_t set_id,
                                             bool multiple,
                                             bool *unknown) {
    const RBorrowOriginSet *set;
    size_t index;

    if ((origins == NULL) || (unknown == NULL)) {
        context->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    if (origin != R_SYMBOL_ID_INVALID) {
        if (!r_grow_array(context,
                          (void **)&origins->items,
                          &origins->capacity,
                          sizeof(*origins->items),
                          origins->count + 1U)) {
            return false;
        }
        origins->items[origins->count++] = origin;
    }
    if (set_id != UINT32_C(0)) {
        set = r_semantic_borrow_origin_set(context, set_id);
        if ((set == NULL) || (set->first > context->borrow_origin_set_item_count) ||
            ((size_t)set->count > context->borrow_origin_set_item_count - set->first)) {
            context->resource_status = R_FRONTEND_INTERNAL_ERROR;
            return false;
        }
        if (!r_grow_array(context,
                          (void **)&origins->items,
                          &origins->capacity,
                          sizeof(*origins->items),
                          origins->count + (size_t)set->count)) {
            return false;
        }
        for (index = 0U; index < (size_t)set->count; ++index) {
            origins->items[origins->count++] = context->borrow_origin_set_items[set->first + index];
        }
    } else if (multiple) {
        *unknown = true;
    }
    return true;
}

static bool r_semantic_intern_borrow_origin_set(RFrontendContext *context,
                                                RSymbolVector *origins,
                                                uint32_t *set_id) {
    size_t index;
    size_t unique_count;
    size_t set_index;
    RBorrowOriginSet *set;

    if ((origins == NULL) || (set_id == NULL)) {
        context->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    for (index = 1U; index < origins->count; ++index) {
        const RSymbolId value = origins->items[index];
        size_t insertion = index;
        while ((insertion != 0U) && (origins->items[insertion - 1U] > value)) {
            origins->items[insertion] = origins->items[insertion - 1U];
            --insertion;
        }
        origins->items[insertion] = value;
    }
    unique_count = 0U;
    for (index = 0U; index < origins->count; ++index) {
        if ((origins->items[index] == R_SYMBOL_ID_INVALID) ||
            ((unique_count != 0U) &&
             (origins->items[unique_count - 1U] == origins->items[index]))) {
            continue;
        }
        origins->items[unique_count++] = origins->items[index];
    }
    origins->count = unique_count;
    if (unique_count < 2U) {
        *set_id = UINT32_C(0);
        return true;
    }
    if (unique_count > UINT32_MAX) {
        context->resource_status = R_FRONTEND_LIMIT_EXCEEDED;
        return false;
    }
    for (set_index = 0U; set_index < context->borrow_origin_set_count; ++set_index) {
        const RBorrowOriginSet *candidate = &context->borrow_origin_sets[set_index];
        if (((size_t)candidate->count == unique_count) &&
            (memcmp(&context->borrow_origin_set_items[candidate->first],
                    origins->items,
                    unique_count * sizeof(*origins->items)) == 0)) {
            if (set_index == UINT32_MAX) {
                context->resource_status = R_FRONTEND_LIMIT_EXCEEDED;
                return false;
            }
            *set_id = (uint32_t)set_index + UINT32_C(1);
            return true;
        }
    }
    if ((context->borrow_origin_set_count >= UINT32_MAX) ||
        (unique_count > SIZE_MAX - context->borrow_origin_set_item_count) ||
        !r_grow_array(context,
                      (void **)&context->borrow_origin_set_items,
                      &context->borrow_origin_set_item_capacity,
                      sizeof(*context->borrow_origin_set_items),
                      context->borrow_origin_set_item_count + unique_count) ||
        !r_grow_array(context,
                      (void **)&context->borrow_origin_sets,
                      &context->borrow_origin_set_capacity,
                      sizeof(*context->borrow_origin_sets),
                      context->borrow_origin_set_count + 1U)) {
        return false;
    }
    (void)memcpy(&context->borrow_origin_set_items[context->borrow_origin_set_item_count],
                 origins->items,
                 unique_count * sizeof(*origins->items));
    set = &context->borrow_origin_sets[context->borrow_origin_set_count];
    set->first = context->borrow_origin_set_item_count;
    set->count = (uint32_t)unique_count;
    context->borrow_origin_set_item_count += unique_count;
    ++context->borrow_origin_set_count;
    *set_id = (uint32_t)context->borrow_origin_set_count;
    return true;
}

static bool r_semantic_merge_borrow_origins(RFrontendContext *context,
                                            RSymbolId left_origin,
                                            uint32_t left_set,
                                            bool left_multiple,
                                            RSymbolId right_origin,
                                            uint32_t right_set,
                                            bool right_multiple,
                                            RSymbolId *result_origin,
                                            uint32_t *result_set,
                                            bool *result_multiple) {
    RSymbolVector origins = {0};
    bool unknown = false;
    bool result = false;

    if ((result_origin == NULL) || (result_set == NULL) || (result_multiple == NULL) ||
        !r_semantic_append_borrow_origins(
            context, &origins, left_origin, left_set, left_multiple, &unknown) ||
        !r_semantic_append_borrow_origins(
            context, &origins, right_origin, right_set, right_multiple, &unknown)) {
        goto cleanup;
    }
    if (unknown) {
        *result_origin = R_SYMBOL_ID_INVALID;
        *result_set = UINT32_C(0);
        *result_multiple = true;
        result = true;
        goto cleanup;
    }
    if (!r_semantic_intern_borrow_origin_set(context, &origins, result_set)) {
        goto cleanup;
    }
    *result_origin = origins.count == 1U ? origins.items[0] : R_SYMBOL_ID_INVALID;
    *result_multiple = origins.count > 1U;
    result = true;

cleanup:
    r_context_free(context, origins.items);
    return result;
}

static bool r_semantic_remap_borrow_origins(RFrontendContext *context,
                                            const RSymbolId *mapping,
                                            size_t mapping_count,
                                            RSymbolId *origin,
                                            uint32_t *set_id,
                                            bool *multiple) {
    RSymbolVector origins = {0};
    bool unknown = false;
    bool result = false;
    size_t index;

    if ((origin == NULL) || (set_id == NULL) || (multiple == NULL) ||
        ((mapping == NULL) && (mapping_count != 0U)) ||
        !r_semantic_append_borrow_origins(
            context, &origins, *origin, *set_id, *multiple, &unknown)) {
        goto cleanup;
    }
    if (unknown) {
        *origin = R_SYMBOL_ID_INVALID;
        *set_id = UINT32_C(0);
        *multiple = true;
        result = true;
        goto cleanup;
    }
    for (index = 0U; index < origins.count; ++index) {
        const RSymbolId value = origins.items[index];
        if ((value != R_SYMBOL_ID_INVALID) && ((size_t)value <= mapping_count) &&
            (mapping[(size_t)value - 1U] != R_SYMBOL_ID_INVALID)) {
            origins.items[index] = mapping[(size_t)value - 1U];
        }
    }
    if (!r_semantic_intern_borrow_origin_set(context, &origins, set_id)) {
        goto cleanup;
    }
    *origin = origins.count == 1U ? origins.items[0] : R_SYMBOL_ID_INVALID;
    *multiple = origins.count > 1U;
    result = true;

cleanup:
    r_context_free(context, origins.items);
    return result;
}

static bool r_semantic_replace_borrow_origin(RFrontendContext *context,
                                             RSymbolId source,
                                             RSymbolId destination,
                                             RSymbolId *origin,
                                             uint32_t *set_id,
                                             bool *multiple) {
    RSymbolVector origins = {0};
    bool unknown = false;
    bool result = false;
    size_t index;

    if ((source == R_SYMBOL_ID_INVALID) || (destination == R_SYMBOL_ID_INVALID) ||
        (origin == NULL) || (set_id == NULL) || (multiple == NULL) ||
        !r_semantic_append_borrow_origins(
            context, &origins, *origin, *set_id, *multiple, &unknown)) {
        goto cleanup;
    }
    if (unknown) {
        *origin = R_SYMBOL_ID_INVALID;
        *set_id = UINT32_C(0);
        *multiple = true;
        result = true;
        goto cleanup;
    }
    for (index = 0U; index < origins.count; ++index) {
        if (origins.items[index] == source) {
            origins.items[index] = destination;
        }
    }
    if (!r_semantic_intern_borrow_origin_set(context, &origins, set_id)) {
        goto cleanup;
    }
    *origin = origins.count == 1U ? origins.items[0] : R_SYMBOL_ID_INVALID;
    *multiple = origins.count > 1U;
    result = true;

cleanup:
    r_context_free(context, origins.items);
    return result;
}

static bool r_semantic_borrow_origin_contains(const RFrontendContext *context,
                                              RSymbolId origin,
                                              uint32_t set_id,
                                              bool multiple,
                                              RSymbolId candidate) {
    const RBorrowOriginSet *set;
    size_t index;

    if (candidate == R_SYMBOL_ID_INVALID) {
        return false;
    }
    if (origin == candidate) {
        return true;
    }
    set = r_semantic_borrow_origin_set(context, set_id);
    if (set != NULL) {
        for (index = 0U; index < (size_t)set->count; ++index) {
            if (context->borrow_origin_set_items[set->first + index] == candidate) {
                return true;
            }
        }
        return false;
    }
    return multiple;
}

static bool r_semantic_borrow_origins_intersect(const RFrontendContext *context,
                                                RSymbolId left_origin,
                                                uint32_t left_set,
                                                bool left_multiple,
                                                RSymbolId right_origin,
                                                uint32_t right_set,
                                                bool right_multiple) {
    const RBorrowOriginSet *left;
    const RBorrowOriginSet *right;
    size_t left_index;
    size_t right_index;

    if ((left_origin != R_SYMBOL_ID_INVALID) &&
        r_semantic_borrow_origin_contains(
            context, right_origin, right_set, right_multiple, left_origin)) {
        return true;
    }
    if ((right_origin != R_SYMBOL_ID_INVALID) &&
        r_semantic_borrow_origin_contains(
            context, left_origin, left_set, left_multiple, right_origin)) {
        return true;
    }
    left = r_semantic_borrow_origin_set(context, left_set);
    right = r_semantic_borrow_origin_set(context, right_set);
    if ((left != NULL) && (right != NULL)) {
        left_index = 0U;
        right_index = 0U;
        while ((left_index < (size_t)left->count) && (right_index < (size_t)right->count)) {
            const RSymbolId left_value = context->borrow_origin_set_items[left->first + left_index];
            const RSymbolId right_value =
                context->borrow_origin_set_items[right->first + right_index];
            if (left_value == right_value) {
                return true;
            }
            if (left_value < right_value) {
                ++left_index;
            } else {
                ++right_index;
            }
        }
    }
    if ((left_multiple && (left_set == UINT32_C(0))) ||
        (right_multiple && (right_set == UINT32_C(0)))) {
        const bool left_nonempty =
            (left_origin != R_SYMBOL_ID_INVALID) || (left != NULL) || left_multiple;
        const bool right_nonempty =
            (right_origin != R_SYMBOL_ID_INVALID) || (right != NULL) || right_multiple;

        return left_nonempty && right_nonempty;
    }
    return false;
}

typedef struct RSemanticObjectSnapshot {
    RSemanticObjectState object_state;
    uint32_t scope_loans;
    RSymbolId borrow_origin;
    uint64_t borrow_referent;
    uint64_t borrow_path;
    uint32_t borrow_origin_set;
    uint32_t projected_borrow_state;
    bool borrow_origin_multiple;
    bool proven_non_null;
} RSemanticObjectSnapshot;

/*
 * borrow_referent normally identifies a library-managed element. This reserved value marks a
 * borrow that directly designates automatic storage. A control-flow or aggregate merge must
 * preserve the marker whenever any possible value designates automatic storage.
 */
#define R_BORROW_REFERENT_AUTOMATIC_STORAGE UINT64_MAX
/* A list lookup returns a stable node, but its identity may alias any other node in that list. */
#define R_BORROW_REFERENT_UNKNOWN_LIST_NODE (UINT64_MAX - UINT64_C(1))

static uint64_t r_semantic_merge_borrow_referents(uint64_t left, uint64_t right) {
    if (left == right) {
        return left;
    }
    if ((left == R_BORROW_REFERENT_AUTOMATIC_STORAGE) ||
        (right == R_BORROW_REFERENT_AUTOMATIC_STORAGE)) {
        return R_BORROW_REFERENT_AUTOMATIC_STORAGE;
    }
    return UINT64_C(0);
}

/* R-BORROW-0011: the longest field path both borrow paths are restricted to. */
static uint64_t r_semantic_merge_borrow_paths(uint64_t left, uint64_t right) {
    uint64_t common = UINT64_C(0);
    uint32_t shift;

    for (shift = 0U; shift < 64U; shift += 8U) {
        const uint64_t level = (left >> shift) & UINT64_C(0xFF);
        if ((level == UINT64_C(0)) || (level != ((right >> shift) & UINT64_C(0xFF)))) {
            break;
        }
        common |= level << shift;
    }
    return common;
}

/* Two field paths below one origin overlap unless they differ at a common level. */
static bool r_semantic_borrow_paths_overlap(uint64_t left, uint64_t right) {
    uint32_t shift;

    for (shift = 0U; shift < 64U; shift += 8U) {
        const uint64_t left_level = (left >> shift) & UINT64_C(0xFF);
        const uint64_t right_level = (right >> shift) & UINT64_C(0xFF);
        if ((left_level == UINT64_C(0)) || (right_level == UINT64_C(0))) {
            return true;
        }
        if (left_level != right_level) {
            return false;
        }
    }
    return true;
}

static RSemanticObjectSnapshot r_semantic_object_snapshot(const RSemanticSymbol *symbol) {
    RSemanticObjectSnapshot snapshot;

    snapshot.object_state = symbol->object_state;
    snapshot.scope_loans = symbol->scope_loans;
    snapshot.borrow_origin = symbol->borrow_origin;
    snapshot.borrow_referent = symbol->borrow_referent;
    snapshot.borrow_path = symbol->borrow_path;
    snapshot.borrow_origin_set = symbol->borrow_origin_set;
    snapshot.projected_borrow_state = symbol->projected_borrow_state;
    snapshot.borrow_origin_multiple = symbol->borrow_origin_multiple;
    snapshot.proven_non_null = symbol->proven_non_null;
    return snapshot;
}

/* R-STMT-0018: a task a select may have left unconsumed merges with a consumed one into a task
 * that is still pending; group.cancel_all() or the group exit resolves it. */
static bool r_semantic_select_pending_merge(RSemanticObjectState left, RSemanticObjectState right) {
    return ((left == R_SEMANTIC_OBJECT_STATE_SELECT_PENDING) &&
            (right == R_SEMANTIC_OBJECT_STATE_MOVED)) ||
           ((left == R_SEMANTIC_OBJECT_STATE_MOVED) &&
            (right == R_SEMANTIC_OBJECT_STATE_SELECT_PENDING));
}

static bool r_semantic_object_snapshot_equal(const RSemanticObjectSnapshot *left,
                                             const RSemanticObjectSnapshot *right) {
    return (left->object_state == right->object_state) &&
           (left->scope_loans == right->scope_loans) &&
           (left->borrow_origin == right->borrow_origin) &&
           (left->borrow_referent == right->borrow_referent) &&
           (left->borrow_path == right->borrow_path) &&
           (left->borrow_origin_set == right->borrow_origin_set) &&
           (left->projected_borrow_state == right->projected_borrow_state) &&
           (left->borrow_origin_multiple == right->borrow_origin_multiple) &&
           (left->proven_non_null == right->proven_non_null);
}

typedef struct RObjectStateSnapshot {
    RSemanticObjectSnapshot *items;
    size_t count;
    RSymbolId payload_borrow_origin;
    uint64_t payload_borrow_referent;
    uint32_t payload_borrow_origin_set;
    uint32_t payload_projected_borrow_state;
    bool payload_borrow_origin_multiple;
    bool payload_borrow_origin_recorded;
    bool captured;
} RObjectStateSnapshot;

typedef struct RObjectStateSnapshotVector {
    RObjectStateSnapshot *items;
    size_t count;
    size_t capacity;
} RObjectStateSnapshotVector;

typedef struct RDetachedObjectStateSnapshots {
    RObjectStateSnapshot *items;
    size_t count;
} RDetachedObjectStateSnapshots;

typedef struct RLoopBorrowCheck {
    RSymbolId origin_symbol;
    RSymbolId excluded_symbol;
    uint64_t borrow_referent;
    uint64_t target_path;
    RTypeId storage_value_type;
    RTypeId storage_root_type;
    RSourceSpan span;
    const char *rule_id;
    const char *message;
    bool exclusive_only;
    bool match_borrow_referent;
} RLoopBorrowCheck;

typedef struct RLoopBorrowCheckVector {
    RLoopBorrowCheck *items;
    size_t count;
    size_t capacity;
} RLoopBorrowCheckVector;

/* R-BORROW-0007: a use of a borrow-bearing symbol inside a loop. After the loop body it is
   checked again against the state a back edge carries into the next iteration. */
/* What a use inside a loop passes on to a value computed from it: the symbol's own value, what
   the symbol designates (a read through a borrow or slice), or nothing. */
typedef enum RLoopReadKind {
    R_LOOP_READ_VALUE = 0,
    R_LOOP_READ_THROUGH,
    R_LOOP_READ_USE
} RLoopReadKind;

typedef struct RLoopRead {
    RSymbolId symbol;
    RLoopReadKind kind;
    RSourceSpan span;
    /* The locals of loop bodies alive at the use, as a range of `loop_live_locals`. */
    size_t live_first;
    size_t live_count;
    bool reported;
} RLoopRead;

typedef struct RLoopReadVector {
    RLoopRead *items;
    size_t count;
    size_t capacity;
} RLoopReadVector;

/* R-BORROW-0018, R-BORROW-0019: origins a statement inside a loop stores into a symbol, directly
   or through the storage a borrow or slice local designates. The sources are the uses of
   borrow-bearing symbols in the same statement, as a range of `loop_reads`. */
typedef struct RLoopFlow {
    RSymbolId target;
    /* A borrow value, such as a call result, whose designated storage the store reaches. */
    RHirNodeId target_node;
    bool through_view;
    RSymbolId origin;
    uint32_t origin_set;
    bool origin_multiple;
    size_t source_first;
    size_t source_count;
    RSourceSpan span;
    bool reported;
} RLoopFlow;

typedef struct RLoopFlowVector {
    RLoopFlow *items;
    size_t count;
    size_t capacity;
} RLoopFlowVector;

typedef struct RAssignmentDestinationCapability {
    const struct RAssignmentDestinationCapability *previous;
    RHirNodeId place;
    RSymbolId borrow_origin;
    uint32_t borrow_origin_set;
    bool borrow_origin_multiple;
    bool allows_same_place_write;
    const char *rule_id;
} RAssignmentDestinationCapability;

enum {
    R_BODY_BREAK_TARGET_LOOP = 0U,
    R_BODY_BREAK_TARGET_SWITCH = 1U
};

/* R-STMT-0004 (L37.2): the label of an enclosing loop, the depth of the loop in
   active_break_target_kinds, its index in active_loop_scope_bases and whether a labeled
   `break` from an inner loop leaves it. */
typedef struct RLoopLabel {
    uint32_t name;
    size_t break_depth;
    size_t loop_index;
    bool broken;
    /* R-STMT-0024 (L46): the label names a switch, lowered as a hidden loop around it whose
       selector `continue name (value);` assigns. */
    bool dispatch;
    RSymbolId selector;
} RLoopLabel;

typedef struct RBodyContext {
    /* R-STMT-0024 (L46): the selector a dispatching switch reads in place of its operand, and
       whether the switch last lowered may complete at its end. */
    const struct RExpressionResult *dispatch_operand;
    bool switch_reaches_end;
    bool checking_usize_constant;
    /* M32-5 (R-STMT-0018): the members listed by the select whose clause is being lowered; a
       branch inside the clause may consume one of them and another leave it select-pending. */
    const RSymbolId *select_members;
    size_t select_member_count;
    /* The number of HIR nodes before this function body was lowered; zero when unknown. */
    size_t first_hir_node;
    /* R-EXPR-0032 (L22.1): a required constant evaluated during translation. The checked errors
       of its calls do not leave the program: an evaluation that throws is a translation error. */
    bool translation_effects;
    RFrontendContext *frontend;
    RSourceId source;
    RSymbolId function_symbol;
    RTypeId return_type;
    RTypeId throws_type;
    RTypeVector active_catch_types;
    RSizeVector active_catch_scope_bases;
    /* The index of the first clause of the try statement each active clause belongs to. */
    RSizeVector active_catch_groups;
    RObjectStateSnapshotVector active_catch_states;
    RSizeVector active_loop_scope_bases;
    RObjectStateSnapshotVector active_loop_continue_states;
    RObjectStateSnapshotVector active_loop_break_states;
    RAstRefVector active_loop_blocks;
    RSizeVector active_switch_scope_bases;
    RSizeVector active_switch_finally_depths;
    RObjectStateSnapshotVector active_switch_break_states;
    RSizeVector active_break_target_kinds;
    /* R-STMT-0023 (L44): while a translation-time loop repeats its block, the break targets and
       loops that began before it; a jump to one of them would leave the loop. */
    bool in_constexpr_loop;
    size_t constexpr_loop_break_floor;
    size_t constexpr_loop_loop_floor;
    RSizeVector active_finally_scope_bases;
    RSizeVector active_finally_catch_depths;
    RSizeVector active_finally_required_scope_bases;
    RObjectStateSnapshotVector active_finally_states;
    RLoopBorrowCheckVector loop_borrow_checks;
    RLoopReadVector loop_reads;
    RSymbolVector loop_live_locals;
    RLoopFlowVector loop_flows;
    /* The symbol count when each active loop began: later symbols are locals of its body. */
    RSizeVector active_loop_symbol_bases;
    size_t loop_statement_read_base;
    /* The loop reads a method call made while forming its receiver, from this index on. */
    size_t pending_receiver_read_first;
    bool pending_receiver_reads;
    /* R-BORROW-0019: parameters whose designated storage a view stored into the storage of
       another parameter borrows for the rest of the call; exclusive ones exclude reads too. */
    RSymbolVector frozen_parameters;
    RSymbolVector frozen_exclusive_parameters;
    /* A local no scope ever holds; a back edge names it for the locals of the loop body. */
    RSymbolId previous_iteration_origin;
    RSymbolVector active_symbols;
    /* R-INIT-0004 (L33): while a field initializer is lowered where it is used, names resolve
       in the module of its aggregate: the active symbols below the floor and the captures of
       an enclosing lambda are not visible. */
    size_t symbol_floor;
    bool module_context;
    /* The initialization that uses a field initializer: diagnostics of the use point at it. */
    RSourceSpan use_site;
    bool use_site_set;
    uint32_t format_temporary_count;
    bool poisoned;
    bool unsupported_seen;
    bool module_bindings_incomplete;
    bool defer_binary_operand_literal_default;
    bool is_async;
    RSymbolId startup_parameter;
    RSymbolId pending_async_start_result;
    RAstRef awaited_call;
    RTypeId awaited_result_type;
    bool staging_async_move_argument;
    /* R-BORROW-0024, R-MEM-0015: the staged Move belongs to a scoped start, whose region keeps
       Send views alive, so the staged value may hold them. */
    bool staging_scoped_move;
    uint32_t unsafe_depth;
    /* R-OBJ-0009: while the object operand of a core atomic operation is lowered, its root
       mutable static is exempt; the exemption stands only if the operand projects fields and
       fixed-array elements of that static to its atomic object. */
    bool atomic_object_pending;
    RSymbolId atomic_object_symbol;
    RSourceSpan atomic_object_span;
    uint32_t loop_depth;
    uint32_t finally_depth;
    uint32_t finally_loop_depth;
    RSymbolId current_task_scope;
    /* R-STMT-0019: hidden local holding the deadline the innermost deadline block restores. */
    RSymbolId current_deadline_saved;
    /* R-STMT-0020: hidden local holding the budget the innermost budget block restores. */
    RSymbolId current_budget_saved;
    /* R-STMT-0022 (L37.3): the statements of the block whose statement `splice_statement` is
       being lowered; a destructuring declaration appends its locals there. */
    RHirVector *statement_splice;
    RAstNodeId splice_statement;
    /* R-STMT-0004 (L37.2): the labels of the enclosing loops, innermost last, and per depth of
       active_break_target_kinds the labels whose jumps left the construct at that depth. */
    RLoopLabel *loop_labels;
    size_t loop_label_count;
    size_t loop_label_capacity;
    uint32_t current_thread_scope_region;
    uint32_t next_thread_scope_region;
    /* Hidden group symbol of the innermost thread_scope; its loans suspend parent access. */
    RSymbolId current_thread_scope_group;
    RTypeId current_catch_type;
    RSymbolId current_catch_symbol;
    RAstRef current_catch_block;
    RAstRef current_finally_clause;
    RAstRef current_finally_statement;
    const RSemanticObjectSnapshot *current_finally_reaching_states;
    size_t current_finally_reaching_state_count;
    bool current_catch_consumed_rethrow_diagnosed;
    bool current_loop_has_break;
    bool suppress_enclosing_loop_transfers;
    size_t suppressed_loop_transfer_depth;
    bool suppress_control_transfer_state_recording;
    bool replaying_loop_borrow_checks;
    bool allow_call_bounded_byte_view;
    const RAssignmentDestinationCapability *active_assignment_destination;
    /* R-FUNC-0016: inside a lambda body, the environment parameter and its aggregate. */
    RSymbolId closure_env_symbol;
    uint32_t closure_aggregate;
    /* R-FUNC-0018: the argument being lowered is a spread onto a variadic parameter. */
    bool lowering_spread_argument;
    /* R-FUNC-0013: the applied generic owner of `Owner(args)::name(...)`, consumed by the call. */
    RTypeId associated_owner_type;
    /* R-BORROW-0024: flows the startup parameter check has computed, while it runs. */
    struct RStartupFlowMemoTable *startup_flow_memo;
    /* A standard method reuses its already evaluated receiver as a call argument. */
    /* M24-5 (R-FUNC-0004): an overload argument that had to be lowered to learn its type; the
       next lowering of that expression returns this result instead of lowering it again. */
    RAstRef prelowered_expression;
    const struct RExpressionResult *prelowered_result;
    /* L39 (R-ERR-0005): the panic exits of a synchronous body under the unwind strategy. A node
       that can panic receives the block of drops of every live object; the last block and the
       objects it drops are kept so that the next node with the same objects shares it. Building
       a block suspends the exits, as do the drops inside it. */
    bool panic_exits;
    uint32_t panic_exit_suspend;
    RHirNodeId last_panic_cleanup;
    RSymbolVector last_panic_symbols;
    RSymbolVector last_panic_defers;
    /* L39 (R-ERR-0008): a drop at the end of a block or a `drop` statement whose value may run R
       code when destroyed gets a panic exit too; at the end of a block that exit drops only the
       objects below active index panic_drop_bound - 1, the ones the block has not dropped yet. */
    bool panic_drops;
    size_t panic_drop_bound;
} RBodyContext;

typedef struct RExpressionResult {
    RHirNodeId node;
    RTypeId type;
    RSymbolId symbol;
    RSymbolId borrow_origin;
    uint64_t borrow_referent;
    uint32_t borrow_origin_set;
    uint32_t projected_borrow_state;
    bool borrow_origin_multiple;
    bool is_place;
    bool is_integer_literal_form;
    bool is_unsuffixed_integer_literal;
    bool valid;
} RExpressionResult;

