/*
 * Library profile gates (Core R-CONF-G005, Library R-SLIB-PROFILE-0001). Profiles are cumulative,
 * so a facility is available exactly when the selected profile is at least the profile that
 * introduces it. An unavailable facility is diagnosed here instead of being linked to a stub.
 * std.json is treated as part of the hosted profile because it depends on std.string; the
 * specification does not assign it to a profile clause.
 */
#define R_SEMANTIC_PROFILE_CODE "R-DIAG-PROFILE-001"
#define R_SEMANTIC_PROFILE_RULE "R-CONF-G005"

typedef struct RStandardModuleProfile {
    const char *module;
    RFrontendProfile required;
    const char *message;
} RStandardModuleProfile;

static const RStandardModuleProfile r_standard_module_profiles[] = {
    {"alloc", R_FRONTEND_PROFILE_ALLOCATION, "std.alloc requires at least the allocation profile"},
    {"arc", R_FRONTEND_PROFILE_ALLOCATION, "std.arc requires at least the allocation profile"},
    {"rc", R_FRONTEND_PROFILE_ALLOCATION, "std.rc requires at least the allocation profile"},
    {"array", R_FRONTEND_PROFILE_ALLOCATION, "std.array requires at least the allocation profile"},
    {"list", R_FRONTEND_PROFILE_ALLOCATION, "std.list requires at least the allocation profile"},
    {"dict", R_FRONTEND_PROFILE_ALLOCATION, "std.dict requires at least the allocation profile"},
    {"error", R_FRONTEND_PROFILE_HOSTED, "std.error requires at least the hosted profile"},
    {"bytes", R_FRONTEND_PROFILE_HOSTED, "std.bytes requires at least the hosted profile"},
    {"hash", R_FRONTEND_PROFILE_HOSTED, "std.hash requires at least the hosted profile"},
    {"utf8", R_FRONTEND_PROFILE_HOSTED, "std.utf8 requires at least the hosted profile"},
    {"bits", R_FRONTEND_PROFILE_HOSTED, "std.bits requires at least the hosted profile"},
    {"string", R_FRONTEND_PROFILE_HOSTED, "std.string requires at least the hosted profile"},
    {"convert", R_FRONTEND_PROFILE_HOSTED, "std.convert requires at least the hosted profile"},
    {"format", R_FRONTEND_PROFILE_HOSTED, "std.format requires at least the hosted profile"},
    {"json", R_FRONTEND_PROFILE_HOSTED, "std.json requires at least the hosted profile"},
    {"math", R_FRONTEND_PROFILE_HOSTED, "std.math requires at least the hosted profile"},
    {"time", R_FRONTEND_PROFILE_HOSTED, "std.time requires at least the hosted profile"},
    {"env", R_FRONTEND_PROFILE_HOSTED, "std.env requires at least the hosted profile"},
    {"c", R_FRONTEND_PROFILE_HOSTED, "std.c requires at least the hosted profile"},
    {"secret", R_FRONTEND_PROFILE_HOSTED, "std.secret requires at least the hosted profile"},
    {"random", R_FRONTEND_PROFILE_HOSTED, "std.random requires at least the hosted profile"},
    {"test", R_FRONTEND_PROFILE_HOSTED, "std.test requires at least the hosted profile"},
    {"process", R_FRONTEND_PROFILE_HOSTED, "std.process requires at least the hosted profile"},
    {"thread",
     R_FRONTEND_PROFILE_HOSTED_THREAD,
     "std.thread requires at least the hosted-thread profile"},
    {"sync",
     R_FRONTEND_PROFILE_HOSTED_THREAD,
     "std.sync requires at least the hosted-thread profile"},
    {"async",
     R_FRONTEND_PROFILE_HOSTED_NATIVE_ASYNC,
     "std.async requires the hosted-native-async profile"},
    {"io",
     R_FRONTEND_PROFILE_HOSTED_NATIVE_ASYNC,
     "std.io requires the hosted-native-async profile"},
    {"fs",
     R_FRONTEND_PROFILE_HOSTED_NATIVE_ASYNC,
     "std.fs requires the hosted-native-async profile"},
    {"net",
     R_FRONTEND_PROFILE_HOSTED_NATIVE_ASYNC,
     "std.net requires the hosted-native-async profile"},
    {"signal",
     R_FRONTEND_PROFILE_HOSTED_NATIVE_ASYNC,
     "std.signal requires the hosted-native-async profile"},
};

static bool r_semantic_profile_at_least(const RFrontendContext *context,
                                        RFrontendProfile required) {
    return context->profile >= required;
}

/* R-OBJ-0012: the translation option or the module attribute denies panicking allocation. */
static bool r_semantic_denies_panic_alloc(const RFrontendContext *context, RSourceId source_id) {
    const RSource *source = r_get_source_const(context, source_id);

    return context->deny_panic_alloc || ((source != NULL) && source->deny_panic_alloc);
}

static bool r_semantic_bytes_equal_text(const char *bytes, size_t length, const char *text) {
    const size_t text_length = strlen(text);

    return (length == text_length) && (memcmp(bytes, text, text_length) == 0);
}

/*
 * Reports whether one standard item is available in the selected profile. module excludes the
 * std. prefix and is empty for core; item is the operation or type name. An unknown module is
 * left to ordinary name resolution. On rejection, message names the introducing profile.
 */
static bool r_semantic_standard_item_permitted(const RFrontendContext *context,
                                               const char *module,
                                               size_t module_length,
                                               const char *item,
                                               size_t item_length,
                                               const char **message) {
    size_t index;

    if (module_length == 0U) {
        return true;
    }
    if (r_semantic_bytes_equal_text(module, module_length, "time") &&
        (r_semantic_bytes_equal_text(item, item_length, "sleep_for") ||
         r_semantic_bytes_equal_text(item, item_length, "sleep_until"))) {
        *message = "std.time sleep operations require the hosted-native-async profile";
        return r_semantic_profile_at_least(context, R_FRONTEND_PROFILE_HOSTED_NATIVE_ASYNC);
    }
    if (r_semantic_bytes_equal_text(module, module_length, "sync") &&
        r_semantic_bytes_equal_text(item, item_length, "receive")) {
        *message = "std.sync::receive requires the hosted-native-async profile";
        return r_semantic_profile_at_least(context, R_FRONTEND_PROFILE_HOSTED_NATIVE_ASYNC);
    }
    if (r_semantic_bytes_equal_text(module, module_length, "sync") &&
        (r_semantic_bytes_equal_text(item, item_length, "reserve") ||
         r_semantic_bytes_equal_text(item, item_length, "try_reserve") ||
         r_semantic_bytes_equal_text(item, item_length, "send_permit") ||
         r_semantic_bytes_equal_text(item, item_length, "permit") ||
         r_semantic_bytes_equal_text(item, item_length, "reserve_result") ||
         r_semantic_bytes_equal_text(item, item_length, "try_reserve_result"))) {
        /* R-LIB-0016 (L30): reservations belong to the asynchronous runtime. */
        *message = "std.sync reservations require the hosted-native-async profile";
        return r_semantic_profile_at_least(context, R_FRONTEND_PROFILE_HOSTED_NATIVE_ASYNC);
    }
    if (r_semantic_bytes_equal_text(module, module_length, "process") &&
        !r_semantic_bytes_equal_text(item, item_length, "exit") &&
        !r_semantic_bytes_equal_text(item, item_length, "abort")) {
        *message = "std.process child-process operations require the hosted-native-async profile";
        return r_semantic_profile_at_least(context, R_FRONTEND_PROFILE_HOSTED_NATIVE_ASYNC);
    }
    for (index = 0U;
         index < sizeof(r_standard_module_profiles) / sizeof(r_standard_module_profiles[0]);
         ++index) {
        const RStandardModuleProfile *entry = &r_standard_module_profiles[index];

        if (r_semantic_bytes_equal_text(module, module_length, entry->module)) {
            *message = entry->message;
            return r_semantic_profile_at_least(context, entry->required);
        }
    }
    return true;
}

/* R-MOD-0002: a standard module the compiler itself provides, as opposed to a standard module
 * written in R that the library map supplies. */
static bool r_semantic_standard_module_provided(const char *module_name) {
    size_t index;

    if (strncmp(module_name, "std.", 4U) != 0) {
        return false;
    }
    for (index = 0U;
         index < sizeof(r_standard_module_profiles) / sizeof(r_standard_module_profiles[0]);
         ++index) {
        if (strcmp(module_name + 4U, r_standard_module_profiles[index].module) == 0) {
            return true;
        }
    }
    return false;
}

/* Splits one canonical std.module::item or core::item spelling. */
static bool r_semantic_standard_spelling_permitted(const RFrontendContext *context,
                                                   const char *name,
                                                   size_t length,
                                                   const char **message) {
    size_t separator = 0U;

    while (((separator + 1U) < length) &&
           !((name[separator] == ':') && (name[separator + 1U] == ':'))) {
        separator += 1U;
    }
    if ((separator + 1U) >= length) {
        return true;
    }
    if ((separator >= 4U) && (memcmp(name, "std.", 4U) == 0)) {
        return r_semantic_standard_item_permitted(context,
                                                  name + 4U,
                                                  separator - 4U,
                                                  name + separator + 2U,
                                                  length - separator - 2U,
                                                  message);
    }
    return true;
}

static bool r_semantic_intern_text(const RFrontendContext *context,
                                   uint32_t intern_id,
                                   const char **bytes,
                                   size_t *length) {
    const RInternEntry *entry;

    if ((intern_id == UINT32_C(0)) || ((size_t)intern_id > context->intern_count)) {
        return false;
    }
    entry = &context->intern_entries[(size_t)intern_id - 1U];
    *bytes = entry->bytes;
    *length = entry->length;
    return true;
}

/* Returns true when the facility is available; otherwise records the profile diagnostic. */
static bool r_semantic_check_profile(RFrontendContext *context,
                                     RFrontendProfile required,
                                     const char *message,
                                     RSourceSpan span) {
    if (r_semantic_profile_at_least(context, required)) {
        return true;
    }
    (void)r_semantic_add_diagnostic(
        context, R_SEMANTIC_PROFILE_CODE, R_SEMANTIC_PROFILE_RULE, message, span);
    return false;
}

static bool
r_semantic_unsupported(RFrontendContext *context, RSourceSpan span, const char *message) {
    return r_semantic_add_diagnostic(context, "R-DIAG-SLICE-001", "R-DIAG-0001", message, span);
}

/*
 * A branch that Annex A and the earlier validation passes make unreachable. It is never a source
 * diagnostic: reaching it means the front end broke one of its own invariants.
 */
static bool r_semantic_invariant(RFrontendContext *context) {
    context->resource_status = R_FRONTEND_INTERNAL_ERROR;
    return false;
}

/* A type reference spelled as a plain or module-qualified name only (no type former). */
static bool r_semantic_type_ast_is_plain_name(const RFrontendContext *context, RAstRef type_ref) {
    RAstTokenView token;
    RAstNodeView view;
    uint32_t child_index;
    uint32_t identifiers = UINT32_C(0);

    if (r_ast_ref_token(context, type_ref, &token)) {
        return token.kind == R_TOKEN_IDENTIFIER;
    }
    if (!r_ast_ref_view(context, type_ref, &view)) {
        return false;
    }
    for (child_index = 0U; child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView child_token;

        if (!r_ast_ref_child(context, type_ref, child_index, &child) ||
            !r_ast_ref_token(context, child, &child_token) ||
            (child_token.kind != R_TOKEN_IDENTIFIER)) {
            return false;
        }
        identifiers += UINT32_C(1);
    }
    return identifiers != UINT32_C(0);
}

/*
 * Reports a failed type reference: a name that resolves to nothing is R-NAME-0003; a spelling the
 * type former already diagnosed adds nothing; anything else is the given slice notice.
 */
static bool r_semantic_type_mentions_error_set_parameter(const RFrontendContext *context,
                                                         RTypeId type_id,
                                                         uint32_t depth) {
    const RSemanticType *type = r_semantic_type(context, type_id);
    if (type == NULL || depth > context->options.limits.max_nesting)
        return false;
    if (type->kind == R_SEMANTIC_TYPE_PARAMETER)
        return (r_generic_parameter_constraints(context, type_id) & R_GENERIC_ERRORS) != 0U;
    return (type->base != R_TYPE_ID_INVALID &&
            r_semantic_type_mentions_error_set_parameter(context, type->base, depth + 1U)) ||
           (type->second != R_TYPE_ID_INVALID &&
            r_semantic_type_mentions_error_set_parameter(context, type->second, depth + 1U));
}

/* R-TYPE-0007: `void` names no value except as a return type or the pointee of `raw void*` and
 * `raw const void*`, so a type that fails with any other `void` in it is a constraint violation. */
static bool
r_semantic_type_ast_misuses_void(const RFrontendContext *context, RAstRef ref, uint32_t depth) {
    RAstNodeView view;
    RTokenKind previous = R_TOKEN_INVALID;
    RTokenKind before_previous = R_TOKEN_INVALID;
    if (depth > r_frontend_tree_depth_limit(context) || !r_ast_ref_view(context, ref, &view))
        return false;
    for (uint32_t index = 0U; index < view.child_count; ++index) {
        RAstRef child;
        RAstTokenView token;
        RAstNodeView child_view;
        if (!r_ast_ref_child(context, ref, index, &child))
            return false;
        if (r_ast_ref_token(context, child, &token)) {
            if (token.kind == R_TOKEN_KW_VOID && previous != R_TOKEN_KW_RAW &&
                !(previous == R_TOKEN_KW_CONST && before_previous == R_TOKEN_KW_RAW))
                return true;
            before_previous = previous;
            previous = token.kind;
        } else if (r_ast_ref_view(context, child, &child_view) &&
                   child_view.kind == R_SYNTAX_TYPE &&
                   r_semantic_type_ast_misuses_void(context, child, depth + 1U)) {
            return true;
        }
    }
    return false;
}

static bool r_semantic_report_type_failure(RFrontendContext *context,
                                           RAstRef type_ref,
                                           RSourceSpan span,
                                           size_t diagnostics_before,
                                           const char *slice_message) {
    if (context->resource_status != R_FRONTEND_OK) {
        return false;
    }
    if (context->diagnostic_count != diagnostics_before) {
        return true;
    }
    if (r_semantic_type_ast_is_plain_name(context, type_ref)) {
        return r_semantic_add_diagnostic(
            context, "R-DIAG-NAME-001", "R-NAME-0003", "unresolved type name", span);
    }
    if (r_semantic_type_ast_misuses_void(context, type_ref, 0U)) {
        return r_semantic_add_diagnostic(context,
                                         "R-DIAG-TYPE-001",
                                         "R-TYPE-0007",
                                         "void is not a value type here; only raw void* and raw "
                                         "const void* point to it",
                                         span);
    }
    return r_semantic_unsupported(context, span, slice_message);
}

