/* M32-5: inside a select clause, a listed member that one branch consumes and another leaves
   running is select-pending after the branches, as after the select itself (R-STMT-0018). */
static bool r_body_select_member_pending(const RBodyContext *body,
                                         RSymbolId symbol,
                                         RSemanticObjectState left,
                                         RSemanticObjectState right) {
    bool listed = false;
    for (size_t index = 0U; index < body->select_member_count; ++index) {
        if (body->select_members[index] == symbol) {
            listed = true;
        }
    }
    if (!listed) {
        return false;
    }
    const bool left_open = left == R_SEMANTIC_OBJECT_STATE_INITIALIZED ||
                           left == R_SEMANTIC_OBJECT_STATE_SELECT_PENDING;
    const bool right_open = right == R_SEMANTIC_OBJECT_STATE_INITIALIZED ||
                            right == R_SEMANTIC_OBJECT_STATE_SELECT_PENDING;
    return (left_open && right == R_SEMANTIC_OBJECT_STATE_MOVED) ||
           (right_open && left == R_SEMANTIC_OBJECT_STATE_MOVED) || (left_open && right_open);
}

