/* M32-7: the slot of the identity of a derived type in the index of semantic types. */
static size_t r_semantic_type_key_hash(
    RSemanticTypeKind kind, RTypeId base, RTypeId second, uint64_t length, uint32_t flags) {
    const uint64_t parts[4] = {(uint64_t)base, (uint64_t)second, length, (uint64_t)flags};
    uint64_t hash = UINT64_C(0x9E3779B97F4A7C15) ^ (uint64_t)kind;

    for (size_t part = 0U; part < 4U; ++part) {
        hash ^= parts[part] + UINT64_C(0x9E3779B97F4A7C15) + (hash << 6U) + (hash >> 2U);
    }
    hash ^= hash >> 33U;
    hash *= UINT64_C(0xFF51AFD7ED558CCD);
    hash ^= hash >> 33U;
    return (size_t)hash;
}

static bool r_semantic_type_key_equal(const RSemanticType *type,
                                      RSemanticTypeKind kind,
                                      RTypeId base,
                                      RTypeId second,
                                      uint64_t length,
                                      uint32_t flags) {
    return (type->kind == kind) && (type->base == base) && (type->second == second) &&
           (type->length == length) && (type->flags == flags);
}

/* Empties the index; the next interning indexes every type again. The remapping of aggregates
   (generics.inc) changes the base of nominal types after they were indexed. */
static void r_semantic_type_index_reset(RFrontendContext *context) {
    if (context->semantic_type_index != NULL) {
        (void)memset(context->semantic_type_index,
                     0,
                     context->semantic_type_index_capacity * sizeof(*context->semantic_type_index));
    }
    context->semantic_type_indexed = 0U;
}

/* Indexes the types added since the last interning, keeping the first type of an identity as
   the linear search did, and grows the index before it is half full. */
static bool r_semantic_type_index_update(RFrontendContext *context) {
    if (context->semantic_type_count >= context->semantic_type_index_capacity / 2U) {
        size_t capacity = context->semantic_type_index_capacity == 0U
                              ? 1024U
                              : context->semantic_type_index_capacity;
        uint32_t *table;

        while (capacity / 2U <= context->semantic_type_count) {
            if (capacity > SIZE_MAX / 2U / sizeof(*table)) {
                context->resource_status = R_FRONTEND_LIMIT_EXCEEDED;
                return false;
            }
            capacity *= 2U;
        }
        table = r_context_allocate(context, capacity * sizeof(*table));
        if (table == NULL) {
            return false;
        }
        (void)memset(table, 0, capacity * sizeof(*table));
        r_context_free(context, context->semantic_type_index);
        context->semantic_type_index = table;
        context->semantic_type_index_capacity = capacity;
        context->semantic_type_indexed = 0U;
    }
    while (context->semantic_type_indexed < context->semantic_type_count) {
        const RSemanticType *type = &context->semantic_types[context->semantic_type_indexed];
        const size_t mask = context->semantic_type_index_capacity - 1U;
        size_t slot = r_semantic_type_key_hash(
                          type->kind, type->base, type->second, type->length, type->flags) &
                      mask;
        bool present = false;

        while (context->semantic_type_index[slot] != 0U) {
            if (r_semantic_type_key_equal(
                    &context->semantic_types[context->semantic_type_index[slot] - 1U],
                    type->kind,
                    type->base,
                    type->second,
                    type->length,
                    type->flags)) {
                present = true;
                break;
            }
            slot = (slot + 1U) & mask;
        }
        context->semantic_type_indexed += 1U;
        if (!present) {
            context->semantic_type_index[slot] = (uint32_t)context->semantic_type_indexed;
        }
    }
    return true;
}

static bool r_semantic_intern_derived_type(RFrontendContext *context,
                                           RSemanticTypeKind kind,
                                           RTypeId base,
                                           RTypeId second,
                                           uint64_t length,
                                           uint32_t flags,
                                           RTypeId *type_id) {
    RSemanticType *type;

    if ((context == NULL) || (type_id == NULL) || (kind == R_SEMANTIC_TYPE_INVALID)) {
        return false;
    }
    /* M32-7: an index replaces the scan of every type, which made interning quadratic. */
    if (!r_semantic_type_index_update(context)) {
        return false;
    }
    {
        const size_t mask = context->semantic_type_index_capacity - 1U;
        size_t slot = r_semantic_type_key_hash(kind, base, second, length, flags) & mask;

        while (context->semantic_type_index[slot] != 0U) {
            const uint32_t found = context->semantic_type_index[slot];

            if (r_semantic_type_key_equal(
                    &context->semantic_types[found - 1U], kind, base, second, length, flags)) {
                *type_id = (RTypeId)found;
                return true;
            }
            slot = (slot + 1U) & mask;
        }
    }
    if (context->semantic_type_count >= UINT32_MAX) {
        context->resource_status = R_FRONTEND_LIMIT_EXCEEDED;
        return false;
    }
    if (!r_grow_array(context,
                      (void **)&context->semantic_types,
                      &context->semantic_type_capacity,
                      sizeof(*context->semantic_types),
                      context->semantic_type_count + 1U)) {
        return false;
    }
    type = &context->semantic_types[context->semantic_type_count];
    (void)memset(type, 0, sizeof(*type));
    type->kind = kind;
    type->base = base;
    type->second = second;
    type->length = length;
    type->flags = flags;
    context->semantic_type_count += 1U;
    *type_id = (RTypeId)context->semantic_type_count;
    return true;
}

static bool r_semantic_intern_effect_carrier(RFrontendContext *context,
                                             RTypeId success_type,
                                             RTypeId effect_set,
                                             RTypeId *carrier_type) {
    if ((success_type == R_TYPE_ID_INVALID) || (effect_set == R_TYPE_ID_INVALID)) {
        return false;
    }
    /* R-FUNC-0003: a never function completes only by throwing, so its carrier holds no value. */
    if ((r_semantic_value_kind(context, success_type) == R_SEMANTIC_TYPE_NEVER) &&
        !r_semantic_type_from_token(context, R_TOKEN_KW_VOID, &success_type)) {
        return false;
    }
    return r_semantic_intern_derived_type(context,
                                          R_SEMANTIC_TYPE_EFFECT_CARRIER,
                                          success_type,
                                          effect_set,
                                          UINT64_C(0),
                                          R_SEMANTIC_TYPE_FLAG_NONE,
                                          carrier_type);
}

static bool
r_semantic_single_effect_set(RFrontendContext *context, RTypeId error_type, RTypeId *effect_set) {
    RTypeId effect_items[1] = {error_type};
    RTypeVector effects = {effect_items, UINT32_C(1), UINT32_C(1)};
    bool duplicate = false;

    return (error_type != R_TYPE_ID_INVALID) && (effect_set != NULL) &&
           r_semantic_intern_effect_set(context, &effects, effect_set, &duplicate) && !duplicate;
}

bool r_semantic_effect_carrier_type(RFrontendContext *context,
                                    RTypeId success_type,
                                    RTypeId effect_set,
                                    RTypeId *carrier_type) {
    return r_semantic_intern_effect_carrier(context, success_type, effect_set, carrier_type);
}

static RSemanticTypeKind r_semantic_base_kind(RTokenKind token_kind) {
    switch (token_kind) {
    case R_TOKEN_KW_BOOL:
        return R_SEMANTIC_TYPE_BOOL;
    case R_TOKEN_KW_I8:
        return R_SEMANTIC_TYPE_I8;
    case R_TOKEN_KW_I16:
        return R_SEMANTIC_TYPE_I16;
    case R_TOKEN_KW_I32:
        return R_SEMANTIC_TYPE_I32;
    case R_TOKEN_KW_I64:
        return R_SEMANTIC_TYPE_I64;
    case R_TOKEN_KW_ISIZE:
        return R_SEMANTIC_TYPE_ISIZE;
    case R_TOKEN_KW_U8:
        return R_SEMANTIC_TYPE_U8;
    case R_TOKEN_KW_U16:
        return R_SEMANTIC_TYPE_U16;
    case R_TOKEN_KW_U32:
        return R_SEMANTIC_TYPE_U32;
    case R_TOKEN_KW_U64:
        return R_SEMANTIC_TYPE_U64;
    case R_TOKEN_KW_USIZE:
        return R_SEMANTIC_TYPE_USIZE;
    case R_TOKEN_KW_F32:
        return R_SEMANTIC_TYPE_F32;
    case R_TOKEN_KW_F64:
        return R_SEMANTIC_TYPE_F64;
    case R_TOKEN_KW_CHAR:
        return R_SEMANTIC_TYPE_CHAR;
    case R_TOKEN_KW_STR:
        return R_SEMANTIC_TYPE_STR;
    case R_TOKEN_KW_VOID:
        return R_SEMANTIC_TYPE_VOID;
    case R_TOKEN_KW_NEVER:
        return R_SEMANTIC_TYPE_NEVER;
    case R_TOKEN_KW_NULL_T:
        return R_SEMANTIC_TYPE_NULL_T;
    default:
        return R_SEMANTIC_TYPE_INVALID;
    }
}

static RTokenKind r_semantic_atomic_base_token(RTokenKind token_kind) {
    switch (token_kind) {
    case R_TOKEN_KW_AI8:
        return R_TOKEN_KW_I8;
    case R_TOKEN_KW_AI16:
        return R_TOKEN_KW_I16;
    case R_TOKEN_KW_AI32:
        return R_TOKEN_KW_I32;
    case R_TOKEN_KW_AI64:
        return R_TOKEN_KW_I64;
    case R_TOKEN_KW_AISIZE:
        return R_TOKEN_KW_ISIZE;
    case R_TOKEN_KW_AU8:
        return R_TOKEN_KW_U8;
    case R_TOKEN_KW_AU16:
        return R_TOKEN_KW_U16;
    case R_TOKEN_KW_AU32:
        return R_TOKEN_KW_U32;
    case R_TOKEN_KW_AU64:
        return R_TOKEN_KW_U64;
    case R_TOKEN_KW_AUSIZE:
        return R_TOKEN_KW_USIZE;
    default:
        return R_TOKEN_INVALID;
    }
}

bool r_semantic_type_from_token(RFrontendContext *context,
                                RTokenKind token_kind,
                                RTypeId *type_id) {
    RSemanticTypeKind kind;
    RTokenKind base_token;
    RTypeId base;

    if ((context == NULL) || (type_id == NULL)) {
        return false;
    }
    *type_id = R_TYPE_ID_INVALID;
    kind = r_semantic_base_kind(token_kind);
    if (kind != R_SEMANTIC_TYPE_INVALID) {
        return r_semantic_intern_type(context, kind, R_TYPE_ID_INVALID, type_id);
    }
    if (r_token_is_c_abi_type(token_kind)) {
        return r_semantic_intern_derived_type(context,
                                              R_SEMANTIC_TYPE_C_ABI_NUMERIC,
                                              R_TYPE_ID_INVALID,
                                              R_TYPE_ID_INVALID,
                                              (uint64_t)token_kind,
                                              R_SEMANTIC_TYPE_FLAG_NONE,
                                              type_id);
    }
    base_token = r_semantic_atomic_base_token(token_kind);
    if (base_token == R_TOKEN_INVALID) {
        return false;
    }
    if (!r_semantic_type_from_token(context, base_token, &base)) {
        return false;
    }
    return r_semantic_intern_type(context, R_SEMANTIC_TYPE_ATOMIC, base, type_id);
}

static bool r_semantic_bytes_type(RFrontendContext *context, RTypeId *type_id) {
    RTypeId byte_type;

    if (!r_semantic_type_from_token(context, R_TOKEN_KW_U8, &byte_type)) {
        return false;
    }
    return r_semantic_intern_type(context, R_SEMANTIC_TYPE_ARRAY, byte_type, type_id);
}

const RSemanticType *r_semantic_type(const RFrontendContext *context, RTypeId type_id) {
    if ((context == NULL) || (type_id == R_TYPE_ID_INVALID) ||
        ((size_t)type_id > context->semantic_type_count)) {
        return NULL;
    }
    return &context->semantic_types[(size_t)type_id - 1U];
}

uint32_t r_semantic_effect_count(const RFrontendContext *context, RTypeId effect_set) {
    uint32_t count = UINT32_C(0);

    while (effect_set != R_TYPE_ID_INVALID) {
        const RSemanticType *set = r_semantic_type(context, effect_set);

        if ((set == NULL) || (set->kind != R_SEMANTIC_TYPE_EFFECT_SET) || (count == UINT32_MAX)) {
            return UINT32_C(0);
        }
        if (set->base == R_TYPE_ID_INVALID)
            break;
        count += UINT32_C(1);
        effect_set = set->second;
    }
    return count;
}

RTypeId r_semantic_effect_at(const RFrontendContext *context, RTypeId effect_set, uint32_t index) {
    uint32_t current = UINT32_C(0);

    while (effect_set != R_TYPE_ID_INVALID) {
        const RSemanticType *set = r_semantic_type(context, effect_set);

        if ((set == NULL) || (set->kind != R_SEMANTIC_TYPE_EFFECT_SET)) {
            return R_TYPE_ID_INVALID;
        }
        if (current == index) {
            return set->base;
        }
        current += UINT32_C(1);
        effect_set = set->second;
    }
    return R_TYPE_ID_INVALID;
}

bool r_semantic_effect_contains(const RFrontendContext *context,
                                RTypeId effect_set,
                                RTypeId error_type) {
    while (effect_set != R_TYPE_ID_INVALID) {
        const RSemanticType *set = r_semantic_type(context, effect_set);

        if ((set == NULL) || (set->kind != R_SEMANTIC_TYPE_EFFECT_SET)) {
            return false;
        }
        if (set->base == error_type) {
            return true;
        }
        effect_set = set->second;
    }
    return false;
}

