static bool r_body_lower_call_bounded_value(RBodyContext *body,
                                            RAstRef expression,
                                            RTypeId contextual_type,
                                            RExpressionResult *result) {
    const bool previous = body->allow_call_bounded_byte_view;
    bool success;

    body->allow_call_bounded_byte_view = true;
    success = r_body_lower_value(body, expression, contextual_type, result);
    body->allow_call_bounded_byte_view = previous;
    return success;
}

