static void r_body_expression_invalid(RExpressionResult *result) {
    (void)memset(result, 0, sizeof(*result));
    result->node = R_HIR_NODE_ID_INVALID;
    result->type = R_TYPE_ID_INVALID;
    result->symbol = R_SYMBOL_ID_INVALID;
    result->borrow_origin = R_SYMBOL_ID_INVALID;
}

static bool r_body_borrow_origin_is_expired(const RBodyContext *body,
                                            RSymbolId origin,
                                            uint32_t origin_set,
                                            bool origin_multiple,
                                            bool *expired) {
    const RBorrowOriginSet *set;
    size_t origin_index;
    size_t active_index;

    if (expired == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    (void)origin_multiple;
    *expired = false;
    if ((origin == R_SYMBOL_ID_INVALID) && (origin_set == UINT32_C(0))) {
        return true;
    }
    for (origin_index = 0U;; ++origin_index) {
        RSymbolId candidate;
        const RSemanticSymbol *symbol;
        bool active = false;

        if (origin_index == 0U) {
            candidate = origin;
            if (candidate == R_SYMBOL_ID_INVALID) {
                continue;
            }
        } else {
            set = r_semantic_borrow_origin_set(body->frontend, origin_set);
            if ((set == NULL) || (origin_index > (size_t)set->count)) {
                break;
            }
            candidate = body->frontend->borrow_origin_set_items[set->first + origin_index - 1U];
        }
        symbol = r_body_symbol(body, candidate);
        if (symbol == NULL) {
            body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
            return false;
        }
        if (((symbol->kind != R_SEMANTIC_SYMBOL_LOCAL) &&
             (symbol->kind != R_SEMANTIC_SYMBOL_PARAMETER)) ||
            (symbol->parent != body->function_symbol) ||
            (symbol->content_parameter != R_SYMBOL_ID_INVALID)) {
            /* What a parameter holds lives in the caller's regions (R-BORROW-0018). */
            continue;
        }
        for (active_index = 0U; active_index < body->active_symbols.count; ++active_index) {
            if (body->active_symbols.items[active_index] == candidate) {
                active = true;
                break;
            }
        }
        if (active && (symbol->kind == R_SEMANTIC_SYMBOL_PARAMETER) &&
            (symbol->object_state == R_SEMANTIC_OBJECT_STATE_MOVED) &&
            ((r_semantic_value_kind(body->frontend, symbol->type) == R_SEMANTIC_TYPE_BORROW) ||
             (r_semantic_value_kind(body->frontend, symbol->type) == R_SEMANTIC_TYPE_SLICE) ||
             (r_semantic_value_kind(body->frontend, symbol->type) == R_SEMANTIC_TYPE_STR) ||
             r_semantic_type_contains_borrow(body->frontend, symbol->type) ||
             r_semantic_type_contains_slice(body->frontend, symbol->type))) {
            /* R-BORROW-0007: a borrow parameter stands for storage outside the function; moving
               the borrow out of the parameter does not end that storage. */
            continue;
        }
        if (!active || (symbol->object_state != R_SEMANTIC_OBJECT_STATE_INITIALIZED)) {
            *expired = true;
            return true;
        }
    }
    return true;
}

static bool r_body_value_is_known_non_null(RBodyContext *body, const RExpressionResult *value) {
    const RSemanticType *target =
        r_semantic_type(body->frontend, r_semantic_value_type(body->frontend, value->type));
    const RHirNode *node = r_body_hir_node(body, value->node);

    if (!value->valid || (target == NULL) ||
        ((target->kind != R_SEMANTIC_TYPE_BORROW) && (target->kind != R_SEMANTIC_TYPE_OWN)) ||
        ((target->flags & R_SEMANTIC_TYPE_FLAG_NULLABLE) == 0U)) {
        return false;
    }
    if (value->symbol != R_SYMBOL_ID_INVALID) {
        const RSemanticSymbol *source = r_body_symbol(body, value->symbol);

        if ((source != NULL) && source->proven_non_null) {
            return true;
        }
    }
    if ((node != NULL) && (node->kind == R_HIR_CAST) && (node->operation == R_TOKEN_INVALID) &&
        (node->child_count == UINT32_C(1))) {
        RHirNodeId source_id;
        const RHirNode *source;
        const RSemanticType *source_type;

        if (!r_body_hir_child(body, node, UINT32_C(0), &source_id)) {
            return false;
        }
        source = r_body_hir_node(body, source_id);
        source_type = source == NULL
                          ? NULL
                          : r_semantic_type(body->frontend,
                                            r_semantic_value_type(body->frontend, source->type));
        return (source_type != NULL) && (source_type->kind == target->kind) &&
               (source_type->base == target->base) &&
               ((source_type->flags & R_SEMANTIC_TYPE_FLAG_NULLABLE) == 0U);
    }
    return false;
}

/* R-EXPR-0001: a place designated through a borrow that is itself a temporary value, such as
   `*owner.slot(1)`; it has no named root, and the borrow's formation checked its access. */
static bool r_body_place_is_temporary_indirection(const RBodyContext *body, RHirNodeId place_id) {
    RHirNodeId current = place_id;

    for (uint32_t depth = 0U; depth <= body->frontend->options.limits.max_nesting; ++depth) {
        const RHirNode *node = r_body_hir_node(body, current);
        RHirNodeId child_id;

        if ((node == NULL) || !r_body_hir_child(body, node, 0U, &child_id)) {
            return false;
        }
        if (r_body_hir_is_owner_dereference(body, node)) {
            current = child_id;
            continue;
        }
        if (node->kind == R_HIR_DEREF_PLACE) {
            const RHirNode *pointer = r_body_hir_node(body, child_id);
            const RSemanticSymbol *root = r_body_symbol(body, node->symbol);

            /* A pointer value formed from a named place, as in `*&local`, keeps that root. */
            return (pointer != NULL) && !pointer->is_place &&
                   ((root == NULL) || ((root->kind != R_SEMANTIC_SYMBOL_LOCAL) &&
                                       (root->kind != R_SEMANTIC_SYMBOL_PARAMETER) &&
                                       (root->kind != R_SEMANTIC_SYMBOL_MODULE_OBJECT)));
        }
        if ((node->kind != R_HIR_FIELD_PLACE) && (node->kind != R_HIR_INDEX_PLACE)) {
            return false;
        }
        current = child_id;
    }
    return false;
}

/* The borrow value through whose dereference a temporary indirection is reached. */
static RHirNodeId r_body_place_temporary_pointer(const RBodyContext *body, RHirNodeId place_id) {
    RHirNodeId current = place_id;

    for (uint32_t depth = 0U; depth <= body->frontend->options.limits.max_nesting; ++depth) {
        const RHirNode *node = r_body_hir_node(body, current);
        RHirNodeId child_id;

        if ((node == NULL) || !r_body_hir_child(body, node, 0U, &child_id)) {
            return R_HIR_NODE_ID_INVALID;
        }
        if (r_body_hir_is_owner_dereference(body, node)) {
            current = child_id;
            continue;
        }
        if (node->kind == R_HIR_DEREF_PLACE) {
            return child_id;
        }
        if ((node->kind != R_HIR_FIELD_PLACE) && (node->kind != R_HIR_INDEX_PLACE)) {
            return R_HIR_NODE_ID_INVALID;
        }
        current = child_id;
    }
    return R_HIR_NODE_ID_INVALID;
}

/* The borrow parameter through whose dereference a place is reached, or zero. */
static RSymbolId r_body_place_parameter_indirection(const RBodyContext *body, RHirNodeId place_id) {
    RHirNodeId current = place_id;

    for (uint32_t depth = 0U; depth <= body->frontend->options.limits.max_nesting; ++depth) {
        const RHirNode *node = r_body_hir_node(body, current);
        RHirNodeId child_id;

        if ((node == NULL) || !r_body_hir_child(body, node, 0U, &child_id)) {
            return R_SYMBOL_ID_INVALID;
        }
        if (r_body_hir_is_owner_dereference(body, node)) {
            current = child_id;
            continue;
        }
        if (node->kind == R_HIR_DEREF_PLACE) {
            const RHirNode *pointer = r_body_hir_node(body, child_id);
            const RSemanticSymbol *parameter = (pointer != NULL) && (pointer->kind == R_HIR_PLACE)
                                                   ? r_body_symbol(body, pointer->symbol)
                                                   : NULL;

            return (parameter != NULL) && (parameter->kind == R_SEMANTIC_SYMBOL_PARAMETER)
                       ? pointer->symbol
                       : R_SYMBOL_ID_INVALID;
        }
        if (node->kind == R_HIR_INDEX_PLACE) {
            /* An element of a slice parameter lies in caller storage. */
            const RHirNode *base = r_body_hir_node(body, child_id);
            const RSemanticSymbol *parameter = (base != NULL) && (base->kind == R_HIR_PLACE)
                                                   ? r_body_symbol(body, base->symbol)
                                                   : NULL;

            if ((parameter != NULL) && (parameter->kind == R_SEMANTIC_SYMBOL_PARAMETER) &&
                (r_semantic_value_kind(body->frontend, parameter->type) == R_SEMANTIC_TYPE_SLICE)) {
                return base->symbol;
            }
        }
        if ((node->kind != R_HIR_FIELD_PLACE) && (node->kind != R_HIR_INDEX_PLACE)) {
            return R_SYMBOL_ID_INVALID;
        }
        current = child_id;
    }
    return R_SYMBOL_ID_INVALID;
}

/* The borrow or slice local through whose dereference or index a place is reached, or zero. */
static RSymbolId r_body_place_local_view_indirection(const RBodyContext *body,
                                                     RHirNodeId place_id) {
    RHirNodeId current = place_id;

    for (uint32_t depth = 0U; depth <= body->frontend->options.limits.max_nesting; ++depth) {
        const RHirNode *node = r_body_hir_node(body, current);
        RHirNodeId child_id;
        const RHirNode *child;
        const RSemanticSymbol *view;

        if ((node == NULL) || !r_body_hir_child(body, node, 0U, &child_id) ||
            ((child = r_body_hir_node(body, child_id)) == NULL)) {
            return R_SYMBOL_ID_INVALID;
        }
        if (r_body_hir_is_owner_dereference(body, node)) {
            current = child_id;
            continue;
        }
        if (((node->kind == R_HIR_DEREF_PLACE) || (node->kind == R_HIR_INDEX_PLACE)) &&
            (child->kind == R_HIR_PLACE) && ((view = r_body_symbol(body, child->symbol)) != NULL) &&
            (view->kind == R_SEMANTIC_SYMBOL_LOCAL) &&
            (r_semantic_value_kind(body->frontend, view->type) ==
             (node->kind == R_HIR_DEREF_PLACE ? R_SEMANTIC_TYPE_BORROW : R_SEMANTIC_TYPE_SLICE))) {
            return child->symbol;
        }
        if ((node->kind != R_HIR_FIELD_PLACE) && (node->kind != R_HIR_INDEX_PLACE)) {
            return R_SYMBOL_ID_INVALID;
        }
        current = child_id;
    }
    return R_SYMBOL_ID_INVALID;
}

static bool r_body_call_result_borrows_parameter(const RSemanticSymbol *function,
                                                 uint32_t parameter);

/* The storage a borrow or slice local designates: a parameter stands for caller storage, and a
   local whose designation is not known leaves `known` false. */
static bool r_body_view_symbol_targets(RBodyContext *body,
                                       RSymbolId symbol_id,
                                       RSymbolVector *targets,
                                       bool *known) {
    const RSemanticSymbol *symbol = r_body_symbol(body, symbol_id);
    bool unknown = false;

    if (symbol == NULL) {
        *known = false;
        return true;
    }
    if (symbol->kind == R_SEMANTIC_SYMBOL_PARAMETER) {
        return r_symbol_vector_push(body->frontend, targets, symbol_id);
    }
    if ((symbol->kind != R_SEMANTIC_SYMBOL_LOCAL) || !symbol->view_target_known) {
        *known = false;
        return true;
    }
    if (!r_semantic_append_borrow_origins(body->frontend,
                                          targets,
                                          symbol->view_target,
                                          symbol->view_target_set,
                                          symbol->view_target_multiple,
                                          &unknown)) {
        return false;
    }
    *known = *known && !unknown;
    return true;
}

static RSymbolId r_body_payload_binding_view(const RBodyContext *body, RHirNodeId node_id);

/* The storage root of a place that a borrow or slice designates; indexing or slicing a slice
   local reaches what that local designates. */
static bool r_body_view_place_targets(
    RBodyContext *body, RHirNodeId place_id, bool elements, RSymbolVector *targets, bool *known) {
    RHirNodeId current = place_id;

    for (uint32_t depth = 0U; depth <= body->frontend->options.limits.max_nesting; ++depth) {
        const RHirNode *node = r_body_hir_node(body, current);
        RHirNodeId child_id;
        const RHirNode *child;
        const RSemanticSymbol *symbol;

        if (node == NULL) {
            break;
        }
        if (node->kind == R_HIR_PLACE) {
            symbol = r_body_symbol(body, node->symbol);
            if ((symbol == NULL) || ((symbol->kind != R_SEMANTIC_SYMBOL_LOCAL) &&
                                     (symbol->kind != R_SEMANTIC_SYMBOL_PARAMETER) &&
                                     (symbol->kind != R_SEMANTIC_SYMBOL_MODULE_OBJECT))) {
                break;
            }
            if (elements &&
                (r_semantic_value_kind(body->frontend, symbol->type) == R_SEMANTIC_TYPE_SLICE)) {
                return r_body_view_symbol_targets(body, node->symbol, targets, known);
            }
            return r_symbol_vector_push(body->frontend, targets, node->symbol);
        }
        if (!r_body_hir_child(body, node, 0U, &child_id) ||
            ((child = r_body_hir_node(body, child_id)) == NULL)) {
            break;
        }
        if (r_body_hir_is_owner_dereference(body, node)) {
            current = child_id;
            continue;
        }
        if (node->kind == R_HIR_DEREF_PLACE) {
            const RSemanticSymbol *binding =
                r_body_symbol(body, r_body_payload_binding_view(body, child_id));

            if (binding != NULL) {
                bool unknown = false;

                if (!r_semantic_append_borrow_origins(body->frontend,
                                                      targets,
                                                      binding->payload_view_target,
                                                      binding->payload_view_target_set,
                                                      binding->payload_view_target_multiple,
                                                      &unknown)) {
                    return false;
                }
                *known = *known && !unknown;
                return true;
            }
            if (child->kind != R_HIR_PLACE) {
                break;
            }
            return r_body_view_symbol_targets(body, child->symbol, targets, known);
        }
        if (node->kind == R_HIR_INDEX_PLACE) {
            elements = true;
        } else if (node->kind != R_HIR_FIELD_PLACE) {
            break;
        }
        current = child_id;
    }
    *known = false;
    return true;
}

/* R-BORROW-0018, R-BORROW-0019: the storage that a borrow or slice value designates: the root of
   the place it borrows or slices, what a borrow or slice local designates, or a parameter that
   stands for caller storage. `known` becomes false for a value formed any other way. */
static bool r_body_view_value_targets(RBodyContext *body,
                                      RHirNodeId node_id,
                                      RSymbolVector *targets,
                                      bool *known);

/* The referent a borrow or slice value designates; invalid for other values. */
static RTypeId r_body_view_referent_type(const RBodyContext *body, RTypeId type_id) {
    const RSemanticType *type =
        r_semantic_type(body->frontend, r_semantic_value_type(body->frontend, type_id));

    return ((type != NULL) &&
            ((type->kind == R_SEMANTIC_TYPE_BORROW) || (type->kind == R_SEMANTIC_TYPE_SLICE)))
               ? type->base
               : R_TYPE_ID_INVALID;
}

/* A symbol a store reaches: the hidden content symbol of a parameter stands for storage in the
   caller's regions and is checked as that parameter (R-BORROW-0019). */
static bool
r_body_push_view_target(RBodyContext *body, RSymbolId symbol_id, RSymbolVector *targets) {
    const RSemanticSymbol *symbol = r_body_symbol(body, symbol_id);

    return r_symbol_vector_push(
        body->frontend,
        targets,
        ((symbol != NULL) && (symbol->content_parameter != R_SYMBOL_ID_INVALID))
            ? symbol->content_parameter
            : symbol_id);
}

/* Whether storage of `holder` can contain an object of `referent` without passing through a
   view: a field, an element or an owned payload rather than what a borrow or slice designates. */
static bool r_semantic_type_holds_subobject(const RFrontendContext *context,
                                            RTypeId holder,
                                            RTypeId referent,
                                            uint32_t depth) {
    const RSemanticType *type = r_semantic_type(context, r_semantic_value_type(context, holder));

    if ((type == NULL) || (depth > context->options.limits.max_nesting)) {
        return true;
    }
    if (r_semantic_value_type(context, holder) == r_semantic_value_type(context, referent)) {
        return true;
    }
    switch (type->kind) {
    case R_SEMANTIC_TYPE_BORROW:
    case R_SEMANTIC_TYPE_SLICE:
    case R_SEMANTIC_TYPE_STR:
    case R_SEMANTIC_TYPE_RAW:
        return false;
    case R_SEMANTIC_TYPE_STRUCT:
    case R_SEMANTIC_TYPE_ENUM: {
        const RSemanticAggregate *aggregate = r_semantic_aggregate_for_type(context, holder);
        if (aggregate == NULL) {
            return true;
        }
        for (uint32_t index = 0U; index < aggregate->field_count; ++index) {
            if (r_semantic_type_holds_subobject(
                    context,
                    context->semantic_fields[aggregate->first_field + index].type,
                    referent,
                    depth + 1U)) {
                return true;
            }
        }
        return false;
    }
    case R_SEMANTIC_TYPE_DICT:
    case R_SEMANTIC_TYPE_RESULT:
        return r_semantic_type_holds_subobject(context, type->base, referent, depth + 1U) ||
               r_semantic_type_holds_subobject(context, type->second, referent, depth + 1U);
    case R_SEMANTIC_TYPE_FIXED_ARRAY:
    case R_SEMANTIC_TYPE_ARRAY:
    case R_SEMANTIC_TYPE_LIST:
    case R_SEMANTIC_TYPE_OPTION:
    case R_SEMANTIC_TYPE_OWN:
    case R_SEMANTIC_TYPE_ARC:
    case R_SEMANTIC_TYPE_RC:
    case R_SEMANTIC_TYPE_CONST:
    case R_SEMANTIC_TYPE_ATOMIC:
        return r_semantic_type_holds_subobject(context, type->base, referent, depth + 1U);
    default:
        /* Scalars hold nothing else; other kinds stay conservative. */
        return (type->kind == R_SEMANTIC_TYPE_STANDARD) ||
               (type->kind == R_SEMANTIC_TYPE_PARAMETER);
    }
}

/* R-BORROW-0018: a borrow a call derives from an argument whose referent holds exclusive views
   designates storage of that referent, when the referent can contain the result's referent, or
   storage an exclusive view held there designates, such as the element `(str)*` of
   `array<(str)*>` that `first_slot(&slots)` returns. The argument's own storage is not a target
   otherwise: the exclusive views it holds lend its whole origin set. A result the contract holds
   apart from the argument's storage (R-BORROW-0009) designates only what that storage holds. */
static bool r_body_view_value_held_targets(RBodyContext *body,
                                           RHirNodeId argument_id,
                                           RTypeId parameter_referent,
                                           RTypeId result_referent,
                                           bool held_only,
                                           RSymbolVector *targets,
                                           bool *known) {
    RSymbolVector designated = {0};
    RSymbolVector held = {0};
    bool designated_known = true;
    bool success = false;
    const bool argument_storage =
        !held_only &&
        ((result_referent == R_TYPE_ID_INVALID) ||
         r_semantic_type_holds_subobject(body->frontend, parameter_referent, result_referent, 0U));

    if (!r_body_view_value_targets(body, argument_id, &designated, &designated_known)) {
        goto cleanup;
    }
    if (!designated_known) {
        *known = false;
        success = true;
        goto cleanup;
    }
    for (size_t index = 0U; index < designated.count; ++index) {
        const RSemanticSymbol *storage = r_body_symbol(body, designated.items[index]);
        bool unknown = false;

        if ((storage == NULL) ||
            ((argument_storage || (storage->kind == R_SEMANTIC_SYMBOL_PARAMETER) ||
              (storage->content_parameter != R_SYMBOL_ID_INVALID)) &&
             !r_body_push_view_target(body, designated.items[index], targets))) {
            goto cleanup;
        }
        /* A parameter stands for the caller's regions, including what it holds. */
        if ((storage->kind != R_SEMANTIC_SYMBOL_LOCAL) &&
            (storage->kind != R_SEMANTIC_SYMBOL_MODULE_OBJECT)) {
            continue;
        }
        held.count = 0U;
        if (!r_semantic_append_borrow_origins(body->frontend,
                                              &held,
                                              storage->borrow_origin,
                                              storage->borrow_origin_set,
                                              storage->borrow_origin_multiple,
                                              &unknown)) {
            goto cleanup;
        }
        if (unknown) {
            *known = false;
            success = true;
            goto cleanup;
        }
        for (size_t held_index = 0U; held_index < held.count; ++held_index) {
            const RSemanticSymbol *view = r_body_symbol(body, held.items[held_index]);
            const RSemanticTypeKind kind = view == NULL
                                               ? R_SEMANTIC_TYPE_INVALID
                                               : r_semantic_value_kind(body->frontend, view->type);
            if ((view != NULL) && (view->kind == R_SEMANTIC_SYMBOL_LOCAL) &&
                ((kind == R_SEMANTIC_TYPE_BORROW) || (kind == R_SEMANTIC_TYPE_SLICE))) {
                /* A held borrow local reaches the storage it designates. */
                if (!view->view_target_known) {
                    *known = false;
                    success = true;
                    goto cleanup;
                }
                if (!r_semantic_append_borrow_origins(body->frontend,
                                                      targets,
                                                      view->view_target,
                                                      view->view_target_set,
                                                      view->view_target_multiple,
                                                      &unknown)) {
                    goto cleanup;
                }
                if (unknown) {
                    *known = false;
                    success = true;
                    goto cleanup;
                }
            } else if (!r_body_push_view_target(body, held.items[held_index], targets)) {
                goto cleanup;
            }
        }
    }
    success = true;

cleanup:
    r_context_free(body->frontend, designated.items);
    r_context_free(body->frontend, held.items);
    return success;
}

static bool r_body_view_value_targets(RBodyContext *body,
                                      RHirNodeId node_id,
                                      RSymbolVector *targets,
                                      bool *known) {
    RHirNodeId current = node_id;

    for (uint32_t depth = 0U; depth <= body->frontend->options.limits.max_nesting; ++depth) {
        const RHirNode *node = r_body_hir_node(body, current);
        RHirNodeId child_id;
        const RHirNode *child;

        const RSemanticSymbol *binding =
            r_body_symbol(body, r_body_payload_binding_view(body, current));

        if (binding != NULL) {
            /* `*entry`: the payload a switch binding borrows (R-BORROW-0018). */
            bool unknown = false;

            if (!r_semantic_append_borrow_origins(body->frontend,
                                                  targets,
                                                  binding->payload_view_target,
                                                  binding->payload_view_target_set,
                                                  binding->payload_view_target_multiple,
                                                  &unknown)) {
                return false;
            }
            *known = *known && !unknown;
            return true;
        }
        if ((node != NULL) && (node->kind == R_HIR_VALUE_SCOPE) &&
            (node->integer_value < (uint64_t)node->child_count) &&
            r_body_hir_child(body, node, (uint32_t)node->integer_value, &child_id)) {
            /* A value scope, such as a call through a function item, yields its result child. */
            current = child_id;
            continue;
        }
        if ((node == NULL) || !r_body_hir_child(body, node, 0U, &child_id) ||
            ((child = r_body_hir_node(body, child_id)) == NULL)) {
            break;
        }
        switch (node->kind) {
        case R_HIR_CAST:
            if (node->child_count != UINT32_C(1)) {
                *known = false;
                return true;
            }
            current = child_id;
            continue;
        case R_HIR_LOAD:
        case R_HIR_MOVE:
            if (child->kind != R_HIR_PLACE) {
                break;
            }
            return r_body_view_symbol_targets(body, child->symbol, targets, known);
        case R_HIR_BORROW:
            return r_body_view_place_targets(body, child_id, false, targets, known);
        case R_HIR_SLICE:
            if ((child->kind == R_HIR_PLACE) || (child->kind == R_HIR_FIELD_PLACE) ||
                (child->kind == R_HIR_INDEX_PLACE) || (child->kind == R_HIR_DEREF_PLACE)) {
                return r_body_view_place_targets(body, child_id, true, targets, known);
            }
            current = child_id;
            continue;
        case R_HIR_STANDARD_CALL:
            /* R-LIB-0019..R-LIB-0022: an element borrow designates its container. */
            switch (node->standard_operation) {
            case R_STANDARD_CALL_ARRAY_GET:
            case R_STANDARD_CALL_LIST_FRONT:
            case R_STANDARD_CALL_LIST_BACK:
            case R_STANDARD_CALL_LIST_GET:
            case R_STANDARD_CALL_DICT_GET:
            case R_STANDARD_CALL_ARRAY_GET_MUT:
            case R_STANDARD_CALL_LIST_PUSH_FRONT:
            case R_STANDARD_CALL_LIST_PUSH_BACK:
            case R_STANDARD_CALL_LIST_INSERT_BEFORE:
            case R_STANDARD_CALL_LIST_INSERT_AFTER:
            case R_STANDARD_CALL_LIST_FRONT_MUT:
            case R_STANDARD_CALL_LIST_BACK_MUT:
            case R_STANDARD_CALL_LIST_GET_MUT:
            case R_STANDARD_CALL_DICT_GET_MUT:
            case R_STANDARD_CALL_ARC_GET_MUT:
            case R_STANDARD_CALL_RC_GET_MUT:
                current = child_id;
                continue;
            default:
                break;
            }
            break;
        case R_HIR_CALL: {
            /* R-BORROW-0004: an exclusive result reborrows the arguments its contract names. */
            const RSemanticSymbol *function = r_body_symbol(body, node->symbol);

            if ((function == NULL) || (function->kind != R_SEMANTIC_SYMBOL_FUNCTION) ||
                (node->child_count != function->parameter_count) ||
                (function->return_borrow_parameter == UINT32_C(0))) {
                break;
            }
            for (uint32_t index = 0U; index < node->child_count; ++index) {
                const RTypeId parameter_type =
                    body->frontend
                        ->semantic_parameter_types[(size_t)function->first_parameter_type +
                                                   (size_t)index];
                const RSemanticType *parameter = r_semantic_type(
                    body->frontend, r_semantic_value_type(body->frontend, parameter_type));
                const bool exact = (function->return_borrow_parameter != UINT32_MAX) ||
                                   (function->return_borrow_parameters_low != UINT64_C(0)) ||
                                   (function->return_borrow_parameters_high != UINT64_C(0));
                RHirNodeId argument_id;

                if (exact && !r_body_call_result_borrows_parameter(function, index)) {
                    continue;
                }
                if ((parameter == NULL) || ((parameter->kind != R_SEMANTIC_TYPE_BORROW) &&
                                            (parameter->kind != R_SEMANTIC_TYPE_SLICE))) {
                    continue;
                }
                const bool held_only =
                    r_body_call_input_is_held(body,
                                              function,
                                              index,
                                              r_body_call_result_held_low(body, function),
                                              function->return_borrow_held_high);
                if (!r_body_hir_child(body, node, index, &argument_id) ||
                    !((held_only || r_semantic_type_contains_exclusive_view(
                                        body->frontend, parameter->base, NULL))
                          ? r_body_view_value_held_targets(
                                body,
                                argument_id,
                                parameter->base,
                                r_body_view_referent_type(body, node->type),
                                held_only,
                                targets,
                                known)
                          : r_body_view_value_targets(body, argument_id, targets, known))) {
                    *known = false;
                    return body->frontend->resource_status == R_FRONTEND_OK;
                }
                if (!*known) {
                    return true;
                }
            }
            return true;
        }
        default:
            break;
        }
        break;
    }
    *known = false;
    return true;
}

/* Records what a borrow or slice local designates after `value` is stored into it. The first
   value replaces the record; later values add to it, since either may reach a later use. */
static bool r_body_record_view_targets(RBodyContext *body,
                                       RSymbolId symbol_id,
                                       const RExpressionResult *value,
                                       bool replace) {
    const RSemanticSymbol *symbol = r_body_symbol(body, symbol_id);
    RSymbolVector targets = {0};
    bool known = value->valid;
    bool unknown = false;
    bool success = false;
    uint32_t set_id = UINT32_C(0);
    RSemanticTypeKind kind;

    if (symbol == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    kind = r_semantic_value_kind(body->frontend, symbol->type);
    if (kind == R_SEMANTIC_TYPE_OPTION) {
        /* `o<T*>` and `o<T[]>`: what the payload designates (R-BORROW-0018). */
        const RSemanticType *option =
            r_semantic_type(body->frontend, r_semantic_value_type(body->frontend, symbol->type));
        kind = option == NULL ? R_SEMANTIC_TYPE_INVALID
                              : r_semantic_value_kind(body->frontend, option->base);
    }
    if ((symbol->kind != R_SEMANTIC_SYMBOL_LOCAL) ||
        ((kind != R_SEMANTIC_TYPE_BORROW) && (kind != R_SEMANTIC_TYPE_SLICE)) ||
        (!replace && !symbol->view_target_known)) {
        return true;
    }
    if (!replace && !r_semantic_append_borrow_origins(body->frontend,
                                                      &targets,
                                                      symbol->view_target,
                                                      symbol->view_target_set,
                                                      symbol->view_target_multiple,
                                                      &unknown)) {
        goto cleanup;
    }
    known = known && !unknown;
    if (known && !r_body_view_value_targets(body, value->node, &targets, &known)) {
        goto cleanup;
    }
    if (known && !r_semantic_intern_borrow_origin_set(body->frontend, &targets, &set_id)) {
        goto cleanup;
    }
    {
        RSemanticSymbol *writable = r_body_symbol_mut(body, symbol_id);

        writable->view_target_known = known;
        writable->view_target =
            (known && (targets.count == 1U)) ? targets.items[0] : R_SYMBOL_ID_INVALID;
        writable->view_target_set = known ? set_id : UINT32_C(0);
        writable->view_target_multiple = known && (targets.count > 1U);
    }
    success = true;

cleanup:
    r_context_free(body->frontend, targets.items);
    return success;
}

/* R-BORROW-0018: a switch payload binding over a borrow or slice payload whose referent holds
   views records the storage the payload designates, such as the container that
   `std.list::get_mut` borrows. A binding that moves the payload is itself that view. */
static bool r_body_record_payload_view_targets(RBodyContext *body,
                                               RSymbolId binding_id,
                                               RTypeId payload_type,
                                               RHirNodeId payload_source,
                                               bool binding_moves) {
    const RSemanticType *payload =
        r_semantic_type(body->frontend, r_semantic_value_type(body->frontend, payload_type));
    RSymbolVector targets = {0};
    bool known = true;
    uint32_t set_id = UINT32_C(0);
    bool success = false;

    if ((payload_source == R_HIR_NODE_ID_INVALID) || (payload == NULL) ||
        ((payload->kind != R_SEMANTIC_TYPE_BORROW) && (payload->kind != R_SEMANTIC_TYPE_SLICE)) ||
        (r_dyn_contract(body->frontend, payload->base) != NULL) ||
        (!r_semantic_type_contains_borrow(body->frontend, payload->base) &&
         !r_semantic_type_contains_slice(body->frontend, payload->base))) {
        return true;
    }
    if (!r_body_view_value_targets(body, payload_source, &targets, &known)) {
        goto cleanup;
    }
    known = known && (targets.count != 0U);
    if (known && !r_semantic_intern_borrow_origin_set(body->frontend, &targets, &set_id)) {
        goto cleanup;
    }
    if (known) {
        RSemanticSymbol *binding = r_body_symbol_mut(body, binding_id);
        const RSymbolId single = targets.count == 1U ? targets.items[0] : R_SYMBOL_ID_INVALID;

        if (binding_moves) {
            binding->view_target_known = true;
            binding->view_target = single;
            binding->view_target_set = set_id;
            binding->view_target_multiple = targets.count > 1U;
        } else {
            binding->payload_view_target_known = true;
            binding->payload_view_target = single;
            binding->payload_view_target_set = set_id;
            binding->payload_view_target_multiple = targets.count > 1U;
        }
    }
    success = true;

cleanup:
    r_context_free(body->frontend, targets.items);
    return success;
}

/* The switch payload binding whose borrowed payload `node_id` reads (`*entry`), when the storage
   that payload designates is known; zero otherwise. */
static RSymbolId r_body_payload_binding_view(const RBodyContext *body, RHirNodeId node_id) {
    const RHirNode *node = r_body_hir_node(body, node_id);
    RHirNodeId child_id;
    const RHirNode *child;
    const RSemanticSymbol *binding;

    if ((node != NULL) && ((node->kind == R_HIR_LOAD) || (node->kind == R_HIR_MOVE)) &&
        r_body_hir_child(body, node, 0U, &child_id)) {
        node = r_body_hir_node(body, child_id);
    }
    if ((node == NULL) || (node->kind != R_HIR_DEREF_PLACE) ||
        !r_body_hir_child(body, node, 0U, &child_id) ||
        ((child = r_body_hir_node(body, child_id)) == NULL) || (child->kind != R_HIR_PLACE) ||
        ((binding = r_body_symbol(body, child->symbol)) == NULL) ||
        !binding->is_switch_payload_binding || !binding->payload_view_target_known) {
        return R_SYMBOL_ID_INVALID;
    }
    return child->symbol;
}

/* The read of a borrowed switch payload through which a place is reached one dereference below,
   such as `*entry` in `(*entry)->name`, or zero. */
static RHirNodeId r_body_place_payload_pointer(const RBodyContext *body, RHirNodeId place_id) {
    RHirNodeId current = place_id;

    for (uint32_t depth = 0U; depth <= body->frontend->options.limits.max_nesting; ++depth) {
        const RHirNode *node = r_body_hir_node(body, current);
        RHirNodeId child_id;

        if ((node == NULL) || !r_body_hir_child(body, node, 0U, &child_id)) {
            return R_HIR_NODE_ID_INVALID;
        }
        if (node->kind == R_HIR_DEREF_PLACE) {
            return r_body_payload_binding_view(body, child_id) != R_SYMBOL_ID_INVALID
                       ? child_id
                       : R_HIR_NODE_ID_INVALID;
        }
        if ((node->kind != R_HIR_FIELD_PLACE) && (node->kind != R_HIR_INDEX_PLACE)) {
            return R_HIR_NODE_ID_INVALID;
        }
        current = child_id;
    }
    return R_HIR_NODE_ID_INVALID;
}

/* The root symbol of a place reached through a dereference that is neither of a borrow parameter
   nor of a borrow local, such as `**item` or `holder.next->name`, or zero. */
static RSymbolId r_body_place_nested_indirection_root(const RBodyContext *body,
                                                      RHirNodeId place_id) {
    RHirNodeId current = place_id;
    bool through_dereference = false;

    for (uint32_t depth = 0U; depth <= body->frontend->options.limits.max_nesting; ++depth) {
        const RHirNode *node = r_body_hir_node(body, current);
        RHirNodeId child_id;

        if (node == NULL) {
            return R_SYMBOL_ID_INVALID;
        }
        if (node->kind == R_HIR_PLACE) {
            return through_dereference ? node->symbol : R_SYMBOL_ID_INVALID;
        }
        if (((node->kind != R_HIR_FIELD_PLACE) && (node->kind != R_HIR_INDEX_PLACE) &&
             (node->kind != R_HIR_DEREF_PLACE)) ||
            !r_body_hir_child(body, node, 0U, &child_id)) {
            return R_SYMBOL_ID_INVALID;
        }
        through_dereference = through_dereference || ((node->kind == R_HIR_DEREF_PLACE) &&
                                                      !r_body_hir_is_owner_dereference(body, node));
        current = child_id;
    }
    return R_SYMBOL_ID_INVALID;
}

static bool r_body_return_borrow_input(const RBodyContext *body,
                                       RSymbolId origin,
                                       uint32_t *parameter,
                                       bool *held);
static bool r_semantic_record_store_borrow_parameter(
    RFrontendContext *context, RSymbolId function, uint32_t target, uint32_t source, bool held);

/* Whether a store already froze `parameter`; a store widened across loop iterations, whose
   stored type is not known, keeps the kind the store in the body recorded. */
static bool r_body_parameter_frozen(const RBodyContext *body, RSymbolId parameter, RTypeId type) {
    for (size_t index = 0U; (type == R_TYPE_ID_INVALID) && (index < body->frozen_parameters.count);
         ++index) {
        if (body->frozen_parameters.items[index] == parameter) {
            return true;
        }
    }
    return false;
}

/* R-BORROW-0019: the storage a view parameter designates stays borrowed for the rest of the call
   once a view of it is stored into storage another parameter designates, which outlives the
   call. */
static bool r_body_freeze_parameter(RBodyContext *body, RSymbolId parameter, bool exclusive) {
    RSymbolVector *frozen =
        exclusive ? &body->frozen_exclusive_parameters : &body->frozen_parameters;

    for (size_t index = 0U; index < frozen->count; ++index) {
        if (frozen->items[index] == parameter) {
            return true;
        }
    }
    return r_symbol_vector_push(body->frontend, frozen, parameter) &&
           (!exclusive || r_body_freeze_parameter(body, parameter, false));
}

/* R-BORROW-0019: a borrow stored into storage that a parameter designates comes from that
   parameter, from static storage, or from another parameter, which the contract of the function
   then records (L15.2); a borrow of the storage the parameter itself designates, of automatic
   storage or of unknown storage is rejected. */
static bool r_body_check_store_through_parameter(RBodyContext *body,
                                                 RSymbolId parameter,
                                                 const RExpressionResult *value,
                                                 RSourceSpan span,
                                                 bool *rejected) {
    RSymbolVector origins = {0};
    bool unknown = false;
    bool foreign = false;
    uint32_t stored_count = UINT32_C(0);
    uint32_t stored_source[8];
    bool stored_held[8];
    RSymbolId stored_storage[8];

    *rejected = false;
    if (!r_semantic_append_borrow_origins(body->frontend,
                                          &origins,
                                          value->borrow_origin,
                                          value->borrow_origin_set,
                                          value->borrow_origin_multiple,
                                          &unknown)) {
        r_context_free(body->frontend, origins.items);
        return false;
    }
    const RSemanticSymbol *target = r_body_symbol(body, parameter);
    const RSemanticTypeKind target_kind = target == NULL
                                              ? R_SEMANTIC_TYPE_INVALID
                                              : r_semantic_value_kind(body->frontend, target->type);
    /* A view parameter stands for the storage it designates; its content symbol stands for
       what that storage holds. A view of the designated storage stored into it would make the
       caller's object refer to itself, which the caller does not track: moving or returning
       that object carries the view out of the storage it names (L14 S8). */
    const bool designates_storage =
        (target != NULL) && (target->parameter_content != R_SYMBOL_ID_INVALID) &&
        ((target_kind == R_SEMANTIC_TYPE_BORROW) || (target_kind == R_SEMANTIC_TYPE_SLICE));

    bool self_reference = false;

    for (size_t index = 0U; index < origins.count; ++index) {
        const RSemanticSymbol *origin = r_body_symbol(body, origins.items[index]);

        /* What the parameter itself holds derives from it (R-BORROW-0018). */
        if (designates_storage && (origins.items[index] == parameter)) {
            self_reference = true;
        } else if ((origins.items[index] != parameter) &&
                   ((origin == NULL) || ((origin->kind != R_SEMANTIC_SYMBOL_MODULE_OBJECT) &&
                                         (origin->content_parameter != parameter)))) {
            /* Another parameter: the storage a view parameter designates, or what a parameter
               holds. The borrow of a parameter variable itself is automatic storage. */
            const RSemanticSymbol *input =
                (origin != NULL) && (origin->content_parameter != R_SYMBOL_ID_INVALID)
                    ? r_body_symbol(body, origin->content_parameter)
                    : origin;
            const RSemanticTypeKind input_kind =
                input == NULL ? R_SEMANTIC_TYPE_INVALID
                              : r_semantic_value_kind(body->frontend, input->type);
            const bool storage = (origin != NULL) && (origin == input);
            uint32_t source = UINT32_C(0);
            bool held = false;

            if ((target != NULL) &&
                ((target_kind == R_SEMANTIC_TYPE_BORROW) ||
                 (target_kind == R_SEMANTIC_TYPE_SLICE)) &&
                (input != NULL) && (input->kind == R_SEMANTIC_SYMBOL_PARAMETER) &&
                (input->parent == body->function_symbol) && (input != target) &&
                (!storage || (input_kind == R_SEMANTIC_TYPE_BORROW) ||
                 (input_kind == R_SEMANTIC_TYPE_SLICE) || (input_kind == R_SEMANTIC_TYPE_STR)) &&
                (stored_count < UINT32_C(8)) &&
                r_body_return_borrow_input(body, origins.items[index], &source, &held) &&
                (source != UINT32_C(0))) {
                stored_source[stored_count] = source;
                stored_held[stored_count] = held;
                stored_storage[stored_count] = storage && (input_kind != R_SEMANTIC_TYPE_STR)
                                                   ? origins.items[index]
                                                   : R_SYMBOL_ID_INVALID;
                stored_count += UINT32_C(1);
            } else {
                foreign = true;
            }
        }
    }
    r_context_free(body->frontend, origins.items);
    if (!unknown && !foreign && !self_reference) {
        uint32_t target_position = UINT32_C(0);
        bool target_held = false;
        /* An exclusive view stored there keeps its source's storage exclusive; so does a value
           whose views are not known. */
        const bool exclusive =
            (value->type == R_TYPE_ID_INVALID) ||
            r_semantic_type_contains_exclusive_view(body->frontend, value->type, NULL) ||
            (r_generic_type_is_dependent(body->frontend, value->type, 0U) &&
             !r_generic_has_property(body->frontend, value->type, R_GENERIC_COPY, 0U));

        if ((stored_count != UINT32_C(0)) &&
            !r_body_return_borrow_input(body, parameter, &target_position, &target_held)) {
            return false;
        }
        for (uint32_t index = 0U; index < stored_count; ++index) {
            if ((target_position == UINT32_C(0)) ||
                !r_semantic_record_store_borrow_parameter(body->frontend,
                                                          body->function_symbol,
                                                          target_position,
                                                          stored_source[index],
                                                          stored_held[index]) ||
                ((stored_storage[index] != R_SYMBOL_ID_INVALID) &&
                 !r_body_parameter_frozen(body, stored_storage[index], value->type) &&
                 !r_body_freeze_parameter(body, stored_storage[index], exclusive))) {
                if (target_position == UINT32_C(0)) {
                    body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
                }
                return false;
            }
        }
        return true;
    }
    *rejected = true;
    if (self_reference && !unknown && !foreign) {
        return r_body_diagnostic(body,
                                 "R-DIAG-BORROW-002",
                                 "R-BORROW-0019",
                                 "a borrow of the storage a parameter designates shall not be "
                                 "stored into that storage",
                                 span);
    }
    /* R-TYPE-0035: a dependent value may hold views unless its constraints prove otherwise. */
    if (!r_semantic_type_contains_borrow(body->frontend, value->type) &&
        !r_semantic_type_contains_slice(body->frontend, value->type) &&
        r_generic_type_is_dependent(body->frontend, value->type, 0U)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-BORROW-002",
                                 "R-BORROW-0019",
                                 "a value stored through a parameter shall derive from that "
                                 "parameter unless its type is proven unborrowed",
                                 span);
    }
    return r_body_diagnostic(body,
                             "R-DIAG-BORROW-002",
                             "R-BORROW-0019",
                             "a borrow stored through a parameter shall derive from that parameter",
                             span);
}

/* R-BORROW-0018: the place behind a borrow local is the storage that local designates; what that
   storage holds is reached by reading it. */
static void r_body_deref_designated_origin(const RBodyContext *body,
                                           RTypeId referent_type,
                                           const RExpressionResult *pointer,
                                           RExpressionResult *place) {
    const RHirNode *node = r_body_hir_node(body, pointer->node);
    const RSemanticSymbol *view = r_body_symbol(body, pointer->symbol);
    const RSemanticSymbol *binding =
        r_body_symbol(body, r_body_payload_binding_view(body, pointer->node));

    if ((binding != NULL) && (r_semantic_type_contains_borrow(body->frontend, referent_type) ||
                              r_semantic_type_contains_slice(body->frontend, referent_type))) {
        place->borrow_origin = binding->payload_view_target;
        place->borrow_origin_set = binding->payload_view_target_set;
        place->borrow_origin_multiple = binding->payload_view_target_multiple;
        return;
    }
    if ((node != NULL) && (node->kind == R_HIR_PLACE) && (view != NULL) &&
        (view->kind == R_SEMANTIC_SYMBOL_LOCAL) && view->view_target_known &&
        ((view->view_target != R_SYMBOL_ID_INVALID) || (view->view_target_set != 0U)) &&
        (r_semantic_type_contains_borrow(body->frontend, referent_type) ||
         r_semantic_type_contains_slice(body->frontend, referent_type))) {
        place->borrow_origin = view->view_target;
        place->borrow_origin_set = view->view_target_set;
        place->borrow_origin_multiple = view->view_target_multiple;
    }
}

/* R-BORROW-0018, R-BORROW-0019: a borrow stored into the storage a borrow designates: storage in
   this body records the stored origins, and storage a parameter designates admits only that
   parameter's origins or static storage. */
static bool r_body_store_into_view_targets(RBodyContext *body,
                                           const RSymbolVector *targets,
                                           const RExpressionResult *value,
                                           RSourceSpan span,
                                           bool *rejected) {
    bool success = true;

    *rejected = false;
    for (size_t index = 0U; success && !*rejected && (index < targets->count); ++index) {
        RSemanticSymbol *target = r_body_symbol_mut(body, targets->items[index]);

        if ((target == NULL) || (!r_semantic_type_contains_borrow(body->frontend, target->type) &&
                                 !r_semantic_type_contains_slice(body->frontend, target->type))) {
            continue;
        }
        if (target->kind == R_SEMANTIC_SYMBOL_PARAMETER) {
            success = r_body_check_store_through_parameter(
                body, targets->items[index], value, span, rejected);
        } else if (((target->kind == R_SEMANTIC_SYMBOL_LOCAL) ||
                    (target->kind == R_SEMANTIC_SYMBOL_MODULE_OBJECT)) &&
                   ((r_semantic_value_kind(body->frontend, target->type) == R_SEMANTIC_TYPE_RC) ||
                    (r_semantic_value_kind(body->frontend, target->type) == R_SEMANTIC_TYPE_ARC))) {
            /* R-BORROW-0018 (L15.3): the handles of a shared owner share one region, fixed when
               the owner is created; a store through one handle may not widen it. */
            RSymbolId merged;
            uint32_t merged_set;
            bool merged_multiple;

            success = r_semantic_merge_borrow_origins(body->frontend,
                                                      target->borrow_origin,
                                                      target->borrow_origin_set,
                                                      target->borrow_origin_multiple,
                                                      value->borrow_origin,
                                                      value->borrow_origin_set,
                                                      value->borrow_origin_multiple,
                                                      &merged,
                                                      &merged_set,
                                                      &merged_multiple);
            if (success &&
                ((merged != target->borrow_origin) || (merged_set != target->borrow_origin_set) ||
                 (merged_multiple != target->borrow_origin_multiple))) {
                *rejected = true;
                success =
                    r_body_diagnostic(body,
                                      "R-DIAG-BORROW-002",
                                      "R-BORROW-0018",
                                      "a view stored into a shared owner's payload shall come "
                                      "from the region the owner was created with",
                                      span);
            }
        } else if ((target->kind == R_SEMANTIC_SYMBOL_LOCAL) ||
                   (target->kind == R_SEMANTIC_SYMBOL_MODULE_OBJECT)) {
            const RSymbolId origin = target->borrow_origin;
            const uint32_t origin_set = target->borrow_origin_set;
            const bool origin_multiple = target->borrow_origin_multiple;

            success = r_semantic_merge_borrow_origins(body->frontend,
                                                      target->borrow_origin,
                                                      target->borrow_origin_set,
                                                      target->borrow_origin_multiple,
                                                      value->borrow_origin,
                                                      value->borrow_origin_set,
                                                      value->borrow_origin_multiple,
                                                      &target->borrow_origin,
                                                      &target->borrow_origin_set,
                                                      &target->borrow_origin_multiple);
            if (success &&
                ((target->borrow_origin != origin) || (target->borrow_origin_set != origin_set) ||
                 (target->borrow_origin_multiple != origin_multiple))) {
                /* The component a store through a view reaches is not known here, so no
                   component keeps its former origins alone (R-BORROW-0025). */
                target->projected_borrow_state = UINT32_C(0);
                target->borrow_path = UINT64_C(0);
            }
        }
    }
    return success;
}

/* R-BORROW-0018: a borrow stored through a borrow or slice local reaches the storage that local
   designates. */
static bool r_body_store_through_local_view(RBodyContext *body,
                                            RSymbolId view_id,
                                            const RExpressionResult *value,
                                            RSourceSpan span,
                                            bool *rejected) {
    const RSemanticSymbol *view = r_body_symbol(body, view_id);
    RSymbolVector targets = {0};
    bool unknown = false;
    bool success;

    *rejected = false;
    if ((view == NULL) || ((value->borrow_origin == R_SYMBOL_ID_INVALID) &&
                           (value->borrow_origin_set == 0U) && !value->borrow_origin_multiple)) {
        return true;
    }
    /* R-BORROW-0019: the stored borrow reaches the storage the view designates, not the sources
       of what that storage holds. */
    if (!r_semantic_append_borrow_origins(
            body->frontend,
            &targets,
            view->view_target_known ? view->view_target : view->borrow_origin,
            view->view_target_known ? view->view_target_set : view->borrow_origin_set,
            view->view_target_known ? view->view_target_multiple : view->borrow_origin_multiple,
            &unknown)) {
        r_context_free(body->frontend, targets.items);
        return false;
    }
    if (unknown) {
        r_context_free(body->frontend, targets.items);
        *rejected = true;
        return r_body_diagnostic(
            body,
            "R-DIAG-BORROW-002",
            "R-BORROW-0019",
            "a borrow stored through a view of unknown storage may outlive its "
            "source",
            span);
    }
    success = r_body_store_into_view_targets(body, &targets, value, span, rejected);
    r_context_free(body->frontend, targets.items);
    return success;
}

/* A borrow stored through a borrow value that is not a local, such as the result of a call; its
   designated storage must be known. */
static bool r_body_store_through_view_value(RBodyContext *body,
                                            RHirNodeId pointer,
                                            const RExpressionResult *value,
                                            RSourceSpan span,
                                            bool *handled,
                                            bool *rejected) {
    RSymbolVector targets = {0};
    bool known = true;
    bool success = false;

    *handled = false;
    *rejected = false;
    if (!r_body_view_value_targets(body, pointer, &targets, &known)) {
        goto cleanup;
    }
    if (known) {
        *handled = true;
        if (!r_body_store_into_view_targets(body, &targets, value, span, rejected) ||
            (!*rejected && !r_body_record_loop_node_flow(body, pointer, value, span))) {
            goto cleanup;
        }
    }
    success = true;

cleanup:
    r_context_free(body->frontend, targets.items);
    return success;
}

/* R-BORROW-0002: an exclusive borrow value passed on, such as a borrow or slice local or a
   borrowed switch payload, is exclusive over the storage it designates; the borrows that storage
   holds stay shared. `handled` stays false when that storage is not known. */
static bool r_body_diagnose_designated_value_conflicts(RBodyContext *body,
                                                       RHirNodeId value_node,
                                                       RSymbolId excluded_symbol,
                                                       RTypeId referent_type,
                                                       RSourceSpan span,
                                                       const char *rule_id,
                                                       const char *message,
                                                       bool *handled,
                                                       bool *has_active_borrow) {
    const RHirNode *node = r_body_hir_node(body, value_node);
    RSymbolVector designated = {0};
    bool known = true;
    bool success = true;

    *handled = false;
    if ((node == NULL) ||
        ((node->kind != R_HIR_LOAD) && (node->kind != R_HIR_MOVE) && (node->kind != R_HIR_SLICE) &&
         (node->kind != R_HIR_DEREF_PLACE)) ||
        r_semantic_type_contains_exclusive_view(body->frontend, referent_type, NULL)) {
        return true;
    }
    if (!r_body_view_value_targets(body, value_node, &designated, &known)) {
        r_context_free(body->frontend, designated.items);
        return false;
    }
    if (known && (designated.count != 0U)) {
        *handled = true;
        for (size_t index = 0U; success && !*has_active_borrow && (index < designated.count);
             ++index) {
            success = r_body_diagnose_active_derived_borrow_at(body,
                                                               designated.items[index],
                                                               excluded_symbol,
                                                               UINT64_C(0),
                                                               span,
                                                               rule_id,
                                                               message,
                                                               has_active_borrow);
        }
    }
    r_context_free(body->frontend, designated.items);
    return success;
}

/* R-BORROW-0018: the storage a read at `value` lies in: the root of a direct place, what the view
   a place is reached through designates, or what a view symbol read through designates. The
   payload slot a non-moving switch binding borrows lies in its scrutinee, which is no storage an
   origin names. `restricted` stays false when that view is not known. */
static bool r_body_read_designation(RBodyContext *body,
                                    const RExpressionResult *value,
                                    RSymbolVector *targets,
                                    bool *restricted) {
    RHirNodeId current = value->node;
    const RHirNode *node = r_body_hir_node(body, current);
    bool known = true;

    *restricted = false;
    if ((node == NULL) ||
        ((node->kind != R_HIR_PLACE) && (node->kind != R_HIR_FIELD_PLACE) &&
         (node->kind != R_HIR_INDEX_PLACE) && (node->kind != R_HIR_DEREF_PLACE))) {
        const RSemanticSymbol *symbol = r_body_symbol(body, value->symbol);

        if ((symbol == NULL) ||
            ((symbol->kind != R_SEMANTIC_SYMBOL_PARAMETER) &&
             ((symbol->kind != R_SEMANTIC_SYMBOL_LOCAL) || !symbol->view_target_known))) {
            return true;
        }
        if (!r_body_view_symbol_targets(body, value->symbol, targets, &known)) {
            return false;
        }
        *restricted = known;
        return true;
    }
    for (uint32_t depth = 0U; depth <= r_frontend_tree_depth_limit(body->frontend); ++depth) {
        RHirNodeId child_id;
        const RHirNode *child;

        if (node == NULL) {
            return true;
        }
        if (node->kind == R_HIR_PLACE) {
            *restricted = true;
            return r_symbol_vector_push(body->frontend, targets, node->symbol);
        }
        if (!r_body_hir_child(body, node, 0U, &child_id) ||
            ((child = r_body_hir_node(body, child_id)) == NULL)) {
            return true;
        }
        if (r_body_hir_is_owner_dereference(body, node)) {
            current = child_id;
            node = child;
            continue;
        }
        if (node->kind == R_HIR_DEREF_PLACE) {
            const RSemanticSymbol *binding =
                child->kind == R_HIR_PLACE ? r_body_symbol(body, child->symbol) : NULL;

            if ((binding != NULL) && binding->is_switch_payload_binding &&
                binding->payload_view_target_known) {
                /* `*entry`: the payload itself, in its scrutinee. */
                *restricted = true;
                return true;
            }
            if (!((child->kind == R_HIR_PLACE)
                      ? r_body_view_symbol_targets(body, child->symbol, targets, &known)
                      : r_body_view_value_targets(body, child_id, targets, &known))) {
                return false;
            }
            *restricted = known;
            return true;
        }
        if ((node->kind == R_HIR_INDEX_PLACE) && (child->kind == R_HIR_PLACE) &&
            (r_semantic_value_kind(body->frontend, child->type) == R_SEMANTIC_TYPE_SLICE)) {
            /* An element of a slice lies in the storage the slice designates. */
            if (!r_body_view_symbol_targets(body, child->symbol, targets, &known)) {
                return false;
            }
            *restricted = known;
            return true;
        }
        if ((node->kind != R_HIR_FIELD_PLACE) && (node->kind != R_HIR_INDEX_PLACE)) {
            return true;
        }
        current = child_id;
        node = child;
    }
    return true;
}

/* R-BORROW-0018: a value that carries borrows, read through a borrow of storage holding borrows,
   carries what that storage holds rather than the storage itself; a parameter stands for the
   caller's regions and reads as its content region. Only the storage the read lies in reads as
   what it holds: a view read out of other storage, such as `*pp` for `pp = &v`, keeps what it
   designates, which R-BORROW-0009 keeps apart from what that storage holds. */
static bool r_body_read_view_value_origins(RBodyContext *body, RExpressionResult *value) {
    RSymbolVector origins = {0};
    RSymbolVector replaced = {0};
    RSymbolVector designation = {0};
    bool restricted = false;
    bool unknown = false;
    bool changed = false;
    bool renamed = false;
    bool kept = false;
    bool success = false;
    uint32_t set_id = UINT32_C(0);
    /* The value designates what the storage holds, not the storage itself. */
    uint64_t referent = UINT64_C(0);
    bool referent_seen = false;

    if (!r_semantic_append_borrow_origins(body->frontend,
                                          &origins,
                                          value->borrow_origin,
                                          value->borrow_origin_set,
                                          value->borrow_origin_multiple,
                                          &unknown)) {
        goto cleanup;
    }
    if (unknown) {
        success = true;
        goto cleanup;
    }
    /* A borrow or slice local whose designated storage is known reads from that storage, and the
       storage reads as what it holds below; its own origin also names that storage. */
    for (size_t index = 0U; index < origins.count; ++index) {
        const RSemanticSymbol *view = r_body_symbol(body, origins.items[index]);
        const RSemanticTypeKind view_kind = view == NULL
                                                ? R_SEMANTIC_TYPE_INVALID
                                                : r_semantic_value_kind(body->frontend, view->type);
        bool target_unknown = false;

        if ((view != NULL) && (view->kind == R_SEMANTIC_SYMBOL_LOCAL) &&
            ((view_kind == R_SEMANTIC_TYPE_BORROW) || (view_kind == R_SEMANTIC_TYPE_SLICE)) &&
            view->view_target_known &&
            ((view->view_target != R_SYMBOL_ID_INVALID) || (view->view_target_set != 0U))) {
            if (!r_semantic_append_borrow_origins(body->frontend,
                                                  &replaced,
                                                  view->view_target,
                                                  view->view_target_set,
                                                  view->view_target_multiple,
                                                  &target_unknown)) {
                goto cleanup;
            }
            if (target_unknown) {
                success = true;
                goto cleanup;
            }
            changed = true;
        } else if (!r_symbol_vector_push(body->frontend, &replaced, origins.items[index])) {
            goto cleanup;
        }
    }
    {
        const RSymbolVector expanded = replaced;
        replaced = origins;
        replaced.count = 0U;
        origins = expanded;
    }
    if (!r_body_read_designation(body, value, &designation, &restricted)) {
        goto cleanup;
    }
    for (size_t index = 0U; index < origins.count; ++index) {
        const RSemanticSymbol *storage = r_body_symbol(body, origins.items[index]);
        const RSemanticTypeKind kind = storage == NULL
                                           ? R_SEMANTIC_TYPE_INVALID
                                           : r_semantic_value_kind(body->frontend, storage->type);
        bool read_there = !restricted;

        for (size_t target = 0U; !read_there && (target < designation.count); ++target) {
            read_there = designation.items[target] == origins.items[index];
        }
        if (!read_there) {
            /* Storage the read does not lie in: the value designates it. */
            if (!r_symbol_vector_push(body->frontend, &replaced, origins.items[index])) {
                goto cleanup;
            }
            kept = kept || (storage == NULL) ||
                   ((storage->kind != R_SEMANTIC_SYMBOL_PARAMETER) &&
                    (storage->kind != R_SEMANTIC_SYMBOL_MODULE_OBJECT) &&
                    (storage->content_parameter == R_SYMBOL_ID_INVALID));
        } else if ((storage != NULL) &&
                   ((storage->kind == R_SEMANTIC_SYMBOL_LOCAL) ||
                    (storage->kind == R_SEMANTIC_SYMBOL_MODULE_OBJECT)) &&
                   (((kind != R_SEMANTIC_TYPE_BORROW) && (kind != R_SEMANTIC_TYPE_SLICE) &&
                     (kind != R_SEMANTIC_TYPE_STR)) ||
                    (storage->kind == R_SEMANTIC_SYMBOL_LOCAL)) &&
                   (r_semantic_type_contains_borrow(body->frontend, storage->type) ||
                    r_semantic_type_contains_slice(body->frontend, storage->type) ||
                    (kind == R_SEMANTIC_TYPE_STR))) {
            bool held_unknown = false;

            changed = true;
            referent = referent_seen
                           ? r_semantic_merge_borrow_referents(referent, storage->borrow_referent)
                           : storage->borrow_referent;
            referent_seen = true;
            if (!r_semantic_append_borrow_origins(body->frontend,
                                                  &replaced,
                                                  storage->borrow_origin == origins.items[index]
                                                      ? R_SYMBOL_ID_INVALID
                                                      : storage->borrow_origin,
                                                  storage->borrow_origin_set,
                                                  storage->borrow_origin_multiple,
                                                  &held_unknown)) {
                goto cleanup;
            }
            if (held_unknown) {
                success = true;
                goto cleanup;
            }
        } else if ((storage != NULL) && (storage->kind == R_SEMANTIC_SYMBOL_PARAMETER) &&
                   (storage->parameter_content != R_SYMBOL_ID_INVALID)) {
            /* The storage a parameter holds or designates reads as its content region. */
            if (!r_symbol_vector_push(body->frontend, &replaced, storage->parameter_content)) {
                goto cleanup;
            }
            renamed = true;
        } else if (!r_symbol_vector_push(body->frontend, &replaced, origins.items[index])) {
            goto cleanup;
        } else if ((storage == NULL) || ((storage->kind != R_SEMANTIC_SYMBOL_PARAMETER) &&
                                         (storage->kind != R_SEMANTIC_SYMBOL_MODULE_OBJECT) &&
                                         (storage->content_parameter == R_SYMBOL_ID_INVALID))) {
            /* A kept caller or program storage designates no automatic storage; any other kept
               origin retains what the read value designated. */
            kept = true;
        }
    }
    if (!changed && !renamed) {
        success = true;
        goto cleanup;
    }
    if (changed) {
        value->borrow_referent =
            kept ? r_semantic_merge_borrow_referents(referent, value->borrow_referent) : referent;
    }
    if (replaced.count == 0U) {
        value->borrow_origin = R_SYMBOL_ID_INVALID;
        value->borrow_origin_set = UINT32_C(0);
        value->borrow_origin_multiple = false;
        success = true;
        goto cleanup;
    }
    if (!r_semantic_intern_borrow_origin_set(body->frontend, &replaced, &set_id)) {
        goto cleanup;
    }
    value->borrow_origin = replaced.count == 1U ? replaced.items[0] : R_SYMBOL_ID_INVALID;
    value->borrow_origin_set = set_id;
    value->borrow_origin_multiple = replaced.count > 1U;
    success = true;

cleanup:
    r_context_free(body->frontend, origins.items);
    r_context_free(body->frontend, replaced.items);
    r_context_free(body->frontend, designation.items);
    return success;
}

static bool r_body_place_to_value_impl(RBodyContext *body,
                                       RExpressionResult *result,
                                       bool allow_owner_identity) {
    RHirNodeId children_storage[1];
    RHirVector children;
    RHirNodeId load_node;
    const RSemanticSymbol *symbol;
    bool borrow_origin_expired;
    bool reads_owner_identity;
    RTypeId load_type;

    if (!result->valid || !result->is_place) {
        return true;
    }
    const bool temporary_indirection = r_body_place_is_temporary_indirection(body, result->node);
    const size_t diagnostics = body->frontend->diagnostic_count;
    if (!temporary_indirection &&
        !r_body_require_initialized_symbol(
            body, result->symbol, r_body_hir_node(body, result->node)->span)) {
        result->valid = false;
        return true;
    }
    if (body->frontend->diagnostic_count != diagnostics) {
        /* The read has no value; later checks of the same read would only cascade. */
        result->valid = false;
        return true;
    }
    if (!r_body_borrow_origin_is_expired(body,
                                         result->borrow_origin,
                                         result->borrow_origin_set,
                                         result->borrow_origin_multiple,
                                         &borrow_origin_expired)) {
        return false;
    }
    if (borrow_origin_expired) {
        result->valid = false;
        return r_body_diagnostic(body,
                                 "R-DIAG-BORROW-002",
                                 "R-BORROW-0007",
                                 "borrowed value outlives its source object",
                                 r_body_hir_node(body, result->node)->span);
    }
    if (!temporary_indirection) {
        /* A read reached through a borrow or slice passes on what that view designates. */
        const RSemanticSymbol *read_root = r_body_symbol(body, result->symbol);
        const RSemanticTypeKind read_root_kind =
            read_root == NULL ? R_SEMANTIC_TYPE_INVALID
                              : r_semantic_value_kind(body->frontend, read_root->type);
        const bool read_through = !r_body_place_is_direct_storage_projection(body, result->node) ||
                                  (((read_root_kind == R_SEMANTIC_TYPE_BORROW) ||
                                    (read_root_kind == R_SEMANTIC_TYPE_SLICE)) &&
                                   (r_body_hir_node(body, result->node)->kind != R_HIR_PLACE));

        if (!r_body_record_loop_read(body,
                                     result->symbol,
                                     read_through ? R_LOOP_READ_THROUGH : R_LOOP_READ_VALUE,
                                     r_body_hir_node(body, result->node)->span)) {
            return false;
        }
    }
    bool scoped_conflict = false;
    if (!allow_owner_identity &&
        !r_scope_loans_conflict(body,
                                result->borrow_origin != 0U ? result->borrow_origin
                                                            : result->symbol,
                                result->borrow_origin_set,
                                result->borrow_origin_multiple,
                                result->borrow_referent,
                                true,
                                false,
                                r_body_hir_node(body, result->node)->span,
                                "R-BORROW-0002",
                                "read conflicts with a scoped child's exclusive borrow",
                                &scoped_conflict))
        return false;
    if (scoped_conflict) {
        result->valid = false;
        return true;
    }
    if (!allow_owner_identity &&
        (r_body_place_holds_views_in_storage(body, result) ||
         r_body_place_is_view_variable(body, result) ||
         (!result->borrow_origin_multiple && ((result->borrow_origin == R_SYMBOL_ID_INVALID) ||
                                              (result->borrow_origin == result->symbol))))) {
        /* R-BORROW-0002: an active exclusive borrow excludes every other overlapping access of
           its storage, reads included. A read through a borrow is that borrow's own access;
           the rules for forming the borrow already exclude its conflicts. */
        const RSymbolId read_origin = result->symbol;
        bool read_conflict = false;

        if (!r_body_diagnose_active_exclusive_derived_borrow_at(
                body,
                read_origin,
                result->symbol,
                r_body_place_target_path(body, result->node, read_origin),
                r_body_hir_node(body, result->node)->span,
                "R-BORROW-0002",
                "read conflicts with an active exclusive borrow",
                &read_conflict)) {
            return false;
        }
        if (read_conflict) {
            result->valid = false;
            return true;
        }
    }
    symbol = r_body_symbol(body, result->symbol);
    reads_owner_identity =
        allow_owner_identity &&
        (r_semantic_value_kind(body->frontend, result->type) == R_SEMANTIC_TYPE_OWN);
    load_type = r_semantic_value_type(body->frontend, result->type);
    if (reads_owner_identity &&
        !r_semantic_type_from_token(body->frontend, R_TOKEN_KW_USIZE, &load_type)) {
        return false;
    }
    if ((!temporary_indirection &&
         ((symbol == NULL) || ((symbol->kind != R_SEMANTIC_SYMBOL_PARAMETER) &&
                               (symbol->kind != R_SEMANTIC_SYMBOL_LOCAL) &&
                               (symbol->kind != R_SEMANTIC_SYMBOL_MODULE_OBJECT)))) ||
        ((r_body_hir_node(body, result->node)->kind != R_HIR_PLACE) &&
         (r_body_hir_node(body, result->node)->kind != R_HIR_FIELD_PLACE) &&
         (r_body_hir_node(body, result->node)->kind != R_HIR_INDEX_PLACE) &&
         (r_body_hir_node(body, result->node)->kind != R_HIR_DEREF_PLACE))) {
        result->valid = false;
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-EXPR-0001",
                                 "expression does not designate a readable Copy place",
                                 r_body_hir_node(body, result->node)->span);
    }
    /* Every non-Copy value is a Move value, whether or not its ownership lowering exists. */
    if (!r_semantic_type_is_copy(body->frontend, result->type) &&
        (r_semantic_value_kind(body->frontend, result->type) != R_SEMANTIC_TYPE_BORROW) &&
        (r_semantic_value_kind(body->frontend, result->type) != R_SEMANTIC_TYPE_SLICE) &&
        !reads_owner_identity) {
        result->valid = false;
        return r_body_diagnostic(body,
                                 "R-DIAG-MOVE-001",
                                 "R-OWN-0003",
                                 "named Move value requires an explicit move",
                                 r_body_hir_node(body, result->node)->span);
    }
    if (!r_body_select_value_projections(body, result))
        return false;
    children_storage[0] = result->node;
    children.items = children_storage;
    children.count = 1U;
    children.capacity = 1U;
    if (!r_body_append_node(body,
                            R_HIR_LOAD,
                            r_body_hir_node(body, result->node)->span,
                            load_type,
                            temporary_indirection ? R_SYMBOL_ID_INVALID : result->symbol,
                            reads_owner_identity ? R_TOKEN_AMP : R_TOKEN_INVALID,
                            UINT64_C(0),
                            false,
                            &children,
                            &load_node)) {
        return false;
    }
    /* R-BORROW-0018: a value read through a borrow, including one a call returns such as
       `*pick(words)`, carries what the designated storage holds, not that storage. */
    if ((temporary_indirection || !r_body_place_is_direct_storage_projection(body, result->node) ||
         ((symbol != NULL) &&
          ((r_semantic_value_kind(body->frontend, symbol->type) == R_SEMANTIC_TYPE_BORROW) ||
           (r_semantic_value_kind(body->frontend, symbol->type) == R_SEMANTIC_TYPE_SLICE)) &&
          (r_body_hir_node(body, result->node)->kind != R_HIR_PLACE))) &&
        r_semantic_type_may_hold_views(body->frontend, load_type) &&
        !r_body_read_view_value_origins(body, result)) {
        return false;
    }
    r_body_hir_node(body, load_node)->borrow_origin = result->borrow_origin;
    r_body_hir_node(body, load_node)->borrow_referent = result->borrow_referent;
    r_body_hir_node(body, load_node)->borrow_origin_set = result->borrow_origin_set;
    r_body_hir_node(body, load_node)->projected_borrow_state = result->projected_borrow_state;
    r_body_hir_node(body, load_node)->borrow_origin_multiple = result->borrow_origin_multiple;
    result->node = load_node;
    result->type = load_type;
    result->is_place = false;
    result->is_integer_literal_form = false;
    result->is_unsuffixed_integer_literal = false;
    return true;
}

static bool r_body_place_to_value(RBodyContext *body, RExpressionResult *result) {
    return r_body_place_to_value_impl(body, result, false);
}

static bool r_body_place_to_pointer_identity(RBodyContext *body, RExpressionResult *result) {
    const RSemanticType *type =
        r_semantic_type(body->frontend, r_semantic_value_type(body->frontend, result->type));
    RHirNode *node = r_body_hir_node(body, result->node);

    if (result->valid && !result->is_place && (type != NULL) &&
        (type->kind == R_SEMANTIC_TYPE_OWN) && (node != NULL) && (node->kind == R_HIR_LITERAL) &&
        (node->operation == R_TOKEN_KW_NULL)) {
        RTypeId identity_type;

        if (!r_semantic_type_from_token(body->frontend, R_TOKEN_KW_USIZE, &identity_type)) {
            return false;
        }
        node->type = identity_type;
        result->type = identity_type;
        return true;
    }
    return r_body_place_to_value_impl(body, result, true);
}

static bool r_body_place_is_readonly_depth(RBodyContext *body,
                                           RHirNodeId node_id,
                                           uint32_t depth,
                                           bool *readonly) {
    const RHirNode *node = r_body_hir_node(body, node_id);

    if ((node == NULL) || (readonly == NULL) ||
        (depth > r_frontend_tree_depth_limit(body->frontend))) {
        if (node != NULL) {
            body->frontend->resource_status = R_FRONTEND_LIMIT_EXCEEDED;
        }
        return false;
    }
    if (node->operation == R_TOKEN_KW_CASE) {
        *readonly = true;
        return true;
    }
    if (node->kind == R_HIR_PLACE) {
        const RSemanticSymbol *symbol = r_body_symbol(body, node->symbol);
        if (symbol == NULL) {
            body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
            return false;
        }
        *readonly = r_semantic_type_is_const(body->frontend, symbol->type);
        return true;
    }
    if ((node->kind == R_HIR_FIELD_PLACE) || (node->kind == R_HIR_INDEX_PLACE)) {
        RHirNodeId child;
        bool base_readonly;

        if (!r_body_hir_child(body, node, UINT32_C(0), &child) ||
            !r_body_place_is_readonly_depth(body, child, depth + UINT32_C(1), &base_readonly)) {
            return false;
        }
        *readonly =
            base_readonly ||
            ((node->kind == R_HIR_INDEX_PLACE) && (node->aggregate_member != UINT32_C(0))) ||
            ((node->kind == R_HIR_FIELD_PLACE) &&
             r_semantic_type_is_const(body->frontend, node->type));
        return true;
    }
    if (node->kind == R_HIR_DEREF_PLACE) {
        *readonly = node->aggregate_member != UINT32_C(0);
        return true;
    }
    body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
    return false;
}

static bool r_body_place_is_readonly(RBodyContext *body, RHirNodeId node_id, bool *readonly) {
    return r_body_place_is_readonly_depth(body, node_id, UINT32_C(0), readonly);
}

/* R-BORROW-0002: a place available only through a shared or const path. The payload that a
   switch binding borrows keeps the access of the scrutinee the switch holds. */
static bool r_body_place_is_attenuated(RBodyContext *body, RHirNodeId node_id, bool *attenuated) {
    RHirNodeId current = node_id;

    *attenuated = false;
    for (uint32_t depth = 0U; depth <= body->frontend->options.limits.max_nesting; ++depth) {
        const RHirNode *node = r_body_hir_node(body, current);
        RHirNodeId child_id;
        const RHirNode *child;
        const RSemanticSymbol *binding;

        if ((node == NULL) || (node->operation == R_TOKEN_KW_CASE)) {
            return node != NULL;
        }
        if (node->kind == R_HIR_PLACE) {
            const RSemanticSymbol *symbol = r_body_symbol(body, node->symbol);
            *attenuated =
                (symbol != NULL) && r_semantic_type_is_const(body->frontend, symbol->type);
            return true;
        }
        if (!r_body_hir_child(body, node, UINT32_C(0), &child_id) ||
            ((child = r_body_hir_node(body, child_id)) == NULL)) {
            return false;
        }
        if (node->kind == R_HIR_DEREF_PLACE) {
            *attenuated = (node->aggregate_member != UINT32_C(0)) &&
                          !((child->kind == R_HIR_PLACE) &&
                            ((binding = r_body_symbol(body, child->symbol)) != NULL) &&
                            binding->is_switch_payload_binding);
            return true;
        }
        if ((node->kind != R_HIR_FIELD_PLACE) && (node->kind != R_HIR_INDEX_PLACE)) {
            return true;
        }
        if (((node->kind == R_HIR_INDEX_PLACE) && (node->aggregate_member != UINT32_C(0))) ||
            ((node->kind == R_HIR_FIELD_PLACE) &&
             r_semantic_type_is_const(body->frontend, node->type))) {
            *attenuated = true;
            return true;
        }
        current = child_id;
    }
    body->frontend->resource_status = R_FRONTEND_LIMIT_EXCEEDED;
    return false;
}

static bool r_body_indirection_access(RBodyContext *body,
                                      const RExpressionResult *operand,
                                      const RSemanticType *indirection,
                                      bool *supported,
                                      bool *shared) {
    const RSemanticSymbol *symbol;

    if ((body == NULL) || (operand == NULL) || (supported == NULL) || (shared == NULL)) {
        return false;
    }
    *supported = false;
    *shared = false;
    if (indirection == NULL)
        return true;
    if (!operand->is_place) {
        if (indirection->kind == R_SEMANTIC_TYPE_BORROW &&
            (indirection->flags & R_SEMANTIC_TYPE_FLAG_NULLABLE) == 0U) {
            *supported = true;
            *shared = (indirection->flags & R_SEMANTIC_TYPE_FLAG_SHARED) != 0U;
        }
        return true;
    }
    symbol = r_body_symbol(body, operand->symbol);
    if (indirection->kind == R_SEMANTIC_TYPE_BORROW) {
        if (((indirection->flags & R_SEMANTIC_TYPE_FLAG_NULLABLE) != 0U) &&
            ((symbol == NULL) || !symbol->proven_non_null)) {
            return true;
        }
        *supported = true;
        *shared = (indirection->flags & R_SEMANTIC_TYPE_FLAG_SHARED) != 0U;
        /* R-BORROW-0002: an exclusive borrow reached through a shared or const path grants
           shared access only. */
        return *shared || r_body_place_is_attenuated(body, operand->node, shared);
    }
    if (indirection->kind == R_SEMANTIC_TYPE_OWN) {
        if (((indirection->flags & R_SEMANTIC_TYPE_FLAG_NULLABLE) != 0U) &&
            ((symbol == NULL) || !symbol->proven_non_null)) {
            return true;
        }
        *supported = true;
        return r_body_place_is_readonly(body, operand->node, shared);
    }
    if ((indirection->kind == R_SEMANTIC_TYPE_ARC) || (indirection->kind == R_SEMANTIC_TYPE_RC)) {
        *supported = true;
        *shared = true;
        return true;
    }
    if ((indirection->kind == R_SEMANTIC_TYPE_RAW) && (body->unsafe_depth != UINT32_C(0))) {
        *supported = true;
        *shared = (indirection->flags & R_SEMANTIC_TYPE_FLAG_SHARED) != 0U;
    }
    return true;
}

static bool r_body_indirection_diagnostic(RBodyContext *body,
                                          const RSemanticType *indirection,
                                          const char *generic_message,
                                          RSourceSpan span) {
    if ((indirection != NULL) && (indirection->kind == R_SEMANTIC_TYPE_WEAK)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-TYPE-0025",
                                 "a weak managed owner is not dereferenceable; upgrade it first",
                                 span);
    }
    if ((indirection != NULL) &&
        ((indirection->kind == R_SEMANTIC_TYPE_BORROW) ||
         (indirection->kind == R_SEMANTIC_TYPE_OWN)) &&
        ((indirection->flags & R_SEMANTIC_TYPE_FLAG_NULLABLE) != 0U)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-BORROW-003",
                                 "R-BORROW-0005",
                                 "nullable safe dereference requires a prior non-null proof",
                                 span);
    }
    if ((indirection != NULL) && (indirection->kind == R_SEMANTIC_TYPE_RAW) &&
        (body->unsafe_depth == UINT32_C(0))) {
        return r_body_diagnostic(body,
                                 "R-DIAG-UNSAFE-001",
                                 "R-UNSAFE-0001",
                                 "raw pointer dereference requires an unsafe context",
                                 span);
    }
    return r_body_diagnostic(body, "R-DIAG-TYPE-001", "R-EXPR-0002", generic_message, span);
}

static bool r_body_qualified_module_matches(const RBodyContext *body,
                                            RAstRef qualified,
                                            uint32_t component_count,
                                            const char *module_name) {
    return r_semantic_type_module_matches(body->frontend, qualified, component_count, module_name);
}

static bool r_body_qualified_identifier_path_matches(const RFrontendContext *context,
                                                     RAstRef qualified,
                                                     const char *const *components,
                                                     uint32_t component_count) {
    RAstNodeView view;
    uint32_t child_index;
    uint32_t component_index = UINT32_C(0);

    if ((components == NULL) ||
        !r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return false;
    }
    for (child_index = UINT32_C(0); child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;

        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token) ||
            (token.kind != R_TOKEN_IDENTIFIER && token.kind != R_TOKEN_KW_ARRAY &&
             token.kind != R_TOKEN_KW_LIST && token.kind != R_TOKEN_KW_DICT &&
             token.kind != R_TOKEN_KW_ARC && token.kind != R_TOKEN_KW_RC &&
             token.kind != R_TOKEN_KW_ASYNC)) {
            continue;
        }
        if ((component_index >= component_count) ||
            !r_semantic_token_text_equal_owned(context, &token, components[component_index])) {
            return false;
        }
        component_index += UINT32_C(1);
    }
    return component_index == component_count;
}

static const char *r_body_lookup_message(RBodyLookupIssue issue, bool called) {
    switch (issue) {
    case R_BODY_LOOKUP_AMBIGUOUS:
        return called ? "called function name is ambiguous" : "ordinary name is ambiguous";
    case R_BODY_LOOKUP_PROTECTED:
        return called ? "called function is protected in another module"
                      : "ordinary name is protected in another module";
    case R_BODY_LOOKUP_CAPTURE:
        return called ? "captured name is not callable here" : "captured name is not usable here";
    case R_BODY_LOOKUP_NOT_IMPORTED:
        return "the module of this qualified name is not imported; write import module.path; "
               "(a standard module written in R is imported as import std.name;)";
    case R_BODY_LOOKUP_UNRESOLVED:
    case R_BODY_LOOKUP_NONE:
    default:
        return called ? "called function name is unresolved at this source position"
                      : "unresolved ordinary name";
    }
}

static bool r_body_core_integer_suffix(const RFrontendContext *context,
                                       RSourceSpan span,
                                       const char *prefix,
                                       RTokenKind *token_kind);

static bool r_body_lower_core_integer_constant(RBodyContext *body,
                                               RSourceSpan span,
                                               const RAstTokenView *components,
                                               uint32_t component_count,
                                               RExpressionResult *result,
                                               bool *matched) {
    RTokenKind type_token = R_TOKEN_INVALID;
    const RSource *source;
    RTypeId integer_type;
    RSemanticTypeKind kind;
    bool is_minimum;
    bool is_signed;
    uint32_t width;
    uint64_t bits;
    uint64_t mask;
    RHirNodeId node_id;

    *matched = false;
    if ((component_count != UINT32_C(2)) ||
        !r_semantic_token_text_equal_owned(body->frontend, &components[0], "core")) {
        return true;
    }
    source = r_get_source_const(body->frontend, components[1].span.source);
    if ((source == NULL) || (components[1].span.end < components[1].span.start) ||
        ((size_t)components[1].span.end > source->length) ||
        ((size_t)(components[1].span.end - components[1].span.start) < strlen("min_i8"))) {
        return true;
    }
    is_minimum = memcmp(source->bytes + components[1].span.start, "min_", strlen("min_")) == 0;
    if ((!is_minimum &&
         (memcmp(source->bytes + components[1].span.start, "max_", strlen("max_")) != 0)) ||
        !r_body_core_integer_suffix(
            body->frontend, components[1].span, is_minimum ? "min_" : "max_", &type_token)) {
        return true;
    }
    *matched = true;
    if (!r_semantic_type_from_token(body->frontend, type_token, &integer_type)) {
        return false;
    }
    kind = r_semantic_value_kind(body->frontend, integer_type);
    if (!r_semantic_integer_properties(kind, &is_signed, &width) || (width == UINT32_C(0)) ||
        (width > UINT32_C(64))) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    mask = width == UINT32_C(64) ? UINT64_MAX : (UINT64_C(1) << width) - UINT64_C(1);
    if (is_minimum) {
        bits = is_signed ? UINT64_C(1) << (width - UINT32_C(1)) : UINT64_C(0);
    } else {
        bits = is_signed ? mask >> UINT32_C(1) : mask;
    }
    if (!r_body_append_node(body,
                            R_HIR_LITERAL,
                            span,
                            integer_type,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            bits,
                            false,
                            NULL,
                            &node_id)) {
        return false;
    }
    result->node = node_id;
    result->type = integer_type;
    result->valid = true;
    return true;
}

static bool r_body_append_module_constant(RBodyContext *body,
                                          const RSemanticSymbol *symbol,
                                          RSourceSpan span,
                                          RExpressionResult *result) {
    RHirNodeId node_id;
    const RTypeId value_type = r_semantic_value_type(body->frontend, symbol->type);

    if ((symbol->kind == R_SEMANTIC_SYMBOL_MODULE_CONSTANT) && symbol->consteval_pending) {
        /* R-EXPR-0032: a constant computed at translation time is evaluated on first use. */
        const RSymbolId symbol_id = (RSymbolId)(symbol - body->frontend->semantic_symbols) + 1U;
        bool known = false;

        if (!r_consteval_resolve_module_constant(body->frontend, symbol_id, span, true, &known)) {
            return false;
        }
        symbol = &body->frontend->semantic_symbols[(size_t)symbol_id - 1U];
        if (!known) {
            return r_body_cascade(body);
        }
    }
    if ((symbol->kind == R_SEMANTIC_SYMBOL_MODULE_CONSTANT) && symbol->poisoned &&
        (symbol->is_import || (symbol->consteval_state != 0U))) {
        return r_body_cascade(body);
    }
    if ((symbol->kind == R_SEMANTIC_SYMBOL_MODULE_CONSTANT) &&
        (symbol->constant_parameter != R_TYPE_ID_INVALID)) {
        /* R-STMT-0023 (L44): the constant of a translation-time loop an instantiation unrolls. */
        if (!r_body_append_node(body,
                                R_HIR_GENERIC_CONSTANT,
                                span,
                                value_type,
                                R_SYMBOL_ID_INVALID,
                                R_TOKEN_INVALID,
                                UINT64_C(0),
                                false,
                                NULL,
                                &node_id)) {
            return false;
        }
        r_body_hir_node(body, node_id)->auxiliary_type = symbol->constant_parameter;
        result->node = node_id;
        result->type = value_type;
        result->valid = true;
        return true;
    }
    if ((symbol->kind != R_SEMANTIC_SYMBOL_MODULE_CONSTANT) ||
        !r_body_append_node(body,
                            R_HIR_LITERAL,
                            span,
                            value_type,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            symbol->integer_value,
                            false,
                            NULL,
                            &node_id)) {
        return false;
    }
    result->node = node_id;
    result->type = value_type;
    result->valid = true;
    return true;
}

static bool r_body_symbol_place(RBodyContext *body,
                                RSymbolId symbol_id,
                                RSourceSpan span,
                                RExpressionResult *result);

/* R-OBJ-0009: the first static the object operand of an atomic operation names is its
   candidate root; every other static access keeps the unsafe requirement. */
static bool r_body_defer_atomic_static(RBodyContext *body, RSymbolId symbol_id, RSourceSpan span) {
    if (!body->atomic_object_pending || (body->atomic_object_symbol != R_SYMBOL_ID_INVALID)) {
        return false;
    }
    body->atomic_object_symbol = symbol_id;
    body->atomic_object_span = span;
    return true;
}

/* Whether a lowered atomic object operand borrows fields and fixed-array elements of the
   static root without reading static memory. */
static bool r_body_atomic_static_operand(const RBodyContext *body, RHirNodeId node_id) {
    const RHirNode *node = r_body_hir_node(body, node_id);
    size_t depth = 0U;

    if ((node == NULL) || (node->kind != R_HIR_BORROW) || (node->child_count != UINT32_C(1))) {
        return false;
    }
    node = r_body_hir_node(body, body->frontend->hir_children[node->first_child]);
    while ((node != NULL) && (depth <= body->frontend->options.limits.max_nesting)) {
        const RHirNode *base;
        if (node->kind == R_HIR_PLACE) {
            return node->symbol == body->atomic_object_symbol;
        }
        if (((node->kind != R_HIR_FIELD_PLACE) && (node->kind != R_HIR_INDEX_PLACE)) ||
            (node->child_count == UINT32_C(0))) {
            return false;
        }
        base = r_body_hir_node(body, body->frontend->hir_children[node->first_child]);
        if ((base == NULL) ||
            ((node->kind == R_HIR_INDEX_PLACE) &&
             (r_semantic_value_kind(body->frontend, base->type) != R_SEMANTIC_TYPE_FIXED_ARRAY))) {
            return false;
        }
        node = base;
        depth += 1U;
    }
    return false;
}

static bool r_body_append_module_object(RBodyContext *body,
                                        RSymbolId symbol_id,
                                        RSourceSpan span,
                                        RExpressionResult *result) {
    const RSemanticSymbol *symbol = r_body_symbol(body, symbol_id);

    if ((symbol == NULL) || (symbol->kind != R_SEMANTIC_SYMBOL_MODULE_OBJECT)) {
        return false;
    }
    if (symbol->is_import && symbol->poisoned) {
        return r_body_cascade(body);
    }
    if (symbol->is_import && (body->unsafe_depth == UINT32_C(0))) {
        /* R-FFI-0023: every access to an imported C object is unsafe. */
        return r_body_diagnostic(body,
                                 "R-DIAG-UNSAFE-001",
                                 "R-FFI-0023",
                                 "imported C object access requires an unsafe context",
                                 span);
    }
    if (!symbol->is_thread_local && (body->unsafe_depth == UINT32_C(0)) &&
        (!r_semantic_type_is_const(body->frontend, symbol->type) ||
         !r_semantic_type_is_sync(body->frontend, symbol->type)) &&
        !r_body_defer_atomic_static(body, symbol_id, span)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-MEM-001",
                                 "R-OBJ-0009",
                                 "direct mutable static access requires unsafe; immutable static "
                                 "access requires Sync",
                                 span);
    }
    /* A qualified module object is the same place as its unqualified name (R-MOD-0002). */
    return r_body_symbol_place(body, symbol_id, span, result);
}

static bool r_body_append_enum_constant(RBodyContext *body,
                                        RSourceSpan span,
                                        const RSemanticAggregate *aggregate,
                                        const RAstTokenView *variant_name,
                                        RExpressionResult *result,
                                        uint32_t *resolved) {
    uint32_t variant_index;

    for (variant_index = UINT32_C(0); variant_index < aggregate->variant_count; ++variant_index) {
        const uint32_t global_index = aggregate->first_variant + variant_index;
        const RSemanticVariant *variant = &body->frontend->semantic_variants[global_index];

        if (variant->name_intern_id == variant_name->intern_id) {
            RHirNodeId node_id;
            RHirNode *node;

            result->type = aggregate->type;
            if (resolved != NULL) {
                *resolved = global_index + UINT32_C(1);
                result->valid = true;
                return true;
            }
            if (aggregate->is_tagged && (variant->payload_type != R_TYPE_ID_INVALID)) {
                return r_body_diagnostic(body,
                                         "R-DIAG-TYPE-001",
                                         "R-AGG-0007",
                                         "variant requires its payload initializer",
                                         span);
            }
            if (!r_body_append_node(body,
                                    aggregate->is_tagged ? R_HIR_VARIANT : R_HIR_ENUM_CONSTANT,
                                    span,
                                    aggregate->type,
                                    R_SYMBOL_ID_INVALID,
                                    R_TOKEN_INVALID,
                                    variant->value,
                                    false,
                                    NULL,
                                    &node_id)) {
                return false;
            }
            node = r_body_hir_node(body, node_id);
            if (node == NULL) {
                body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
                return false;
            }
            node->aggregate_member = global_index + UINT32_C(1);
            result->node = node_id;
            result->type = aggregate->type;
            result->valid = true;
            return true;
        }
    }
    return r_body_diagnostic(
        body, "R-DIAG-NAME-001", "R-NAME-0003", "enum variant is unresolved", variant_name->span);
}

static bool r_body_lower_enum_constant(RBodyContext *body,
                                       RAstRef qualified,
                                       RExpressionResult *result,
                                       uint32_t *resolved) {
    RAstNodeView view;
    RAstTokenView enum_name = {0};
    RAstTokenView variant_name = {0};
    RAstTokenView identifiers[4] = {0};
    uint32_t identifier_count = UINT32_C(0);
    uint32_t child_index;
    const RSemanticAggregate *match = NULL;
    size_t aggregate_index;
    bool core_integer_constant = false;

    r_body_expression_invalid(result);
    if (!r_ast_view_kind(body->frontend, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    for (child_index = 0U; child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;
        if (r_ast_ref_child(body->frontend, qualified, child_index, &child) &&
            r_ast_ref_token(body->frontend, child, &token) &&
            (token.kind == R_TOKEN_IDENTIFIER || token.kind == R_TOKEN_KW_NULL ||
             token.kind == R_TOKEN_KW_ARRAY || token.kind == R_TOKEN_KW_ASYNC)) {
            if (token.kind != R_TOKEN_IDENTIFIER) {
                const RSource *source = r_get_source_const(body->frontend, token.span.source);
                if (!r_intern_bytes(body->frontend,
                                    source->bytes + token.span.start,
                                    token.span.end - token.span.start,
                                    &token.intern_id))
                    return false;
            }
            if (identifier_count < (uint32_t)(sizeof(identifiers) / sizeof(identifiers[0]))) {
                identifiers[identifier_count] = token;
            }
            enum_name = variant_name;
            variant_name = token;
            identifier_count += UINT32_C(1);
        }
    }
    {
        RAstRef applied;
        if (r_ast_find_direct_child(body->frontend, qualified, R_SYNTAX_TYPE, &applied)) {
            RTypeId type;
            const RSemanticAggregate *aggregate;
            if (!r_semantic_type_from_ast(body->frontend, applied, &type)) {
                return body->frontend->resource_status == R_FRONTEND_OK;
            }
            aggregate = r_semantic_aggregate_for_type(body->frontend, type);
            if (aggregate == NULL || aggregate->kind != R_SEMANTIC_AGGREGATE_ENUM) {
                return resolved != NULL
                           ? true
                           : r_body_diagnostic(body,
                                               "R-DIAG-TYPE-001",
                                               "R-AGG-0007",
                                               "variant head shall name an enum or variant error",
                                               view.span);
            }
            return r_body_append_enum_constant(
                body, view.span, aggregate, &variant_name, result, resolved);
        }
    }
    if ((resolved == NULL) &&
        !r_body_lower_core_integer_constant(
            body, view.span, identifiers, identifier_count, result, &core_integer_constant)) {
        return false;
    }
    if (core_integer_constant) {
        return true;
    }
    if (identifier_count < UINT32_C(2)) {
        if (resolved != NULL) {
            return true;
        }
        return r_body_diagnostic(
            body, "R-DIAG-NAME-001", "R-NAME-0003", "unresolved qualified name", view.span);
    }
    if ((identifier_count == UINT32_C(3)) &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "core") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "memory_order")) {
        const RSemanticAggregate *standard_enum;

        if (!r_semantic_prepare_core_memory_order_schema(body->frontend, &standard_enum)) {
            return false;
        }
        return r_body_append_enum_constant(
            body, view.span, standard_enum, &identifiers[2], result, resolved);
    }
    if (identifier_count == UINT32_C(4) &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std")) {
        static const struct {
            const char *module;
            const char *name;
            const char *canonical;
        } enums[] = {
            {"time", "error_code", "std.time::error_code"},
            {"time", "duration_error", "std.time::duration_error"},
            {"math", "error_code", "std.math::error_code"},
        };
        for (size_t index = 0U; index < sizeof(enums) / sizeof(enums[0]); ++index) {
            if (r_semantic_token_text_equal_owned(
                    body->frontend, &identifiers[1], enums[index].module) &&
                r_semantic_token_text_equal_owned(
                    body->frontend, &identifiers[2], enums[index].name)) {
                const RSemanticAggregate *aggregate;
                if (!r_semantic_prepare_numeric_enum(
                        body->frontend, enums[index].canonical, &aggregate)) {
                    return false;
                }
                return r_body_append_enum_constant(
                    body, view.span, aggregate, &identifiers[3], result, resolved);
            }
        }
    }
    if (identifier_count == 4U &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "signal") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "kind")) {
        const RSemanticAggregate *aggregate;
        /* R-SLIB-SIGNAL-0001: the signal kinds. */
        if (!r_semantic_prepare_standard_enum_named(body->frontend, "std.signal::kind", &aggregate))
            return false;
        return r_body_append_enum_constant(
            body, view.span, aggregate, &identifiers[3], result, resolved);
    }
    if (identifier_count == 4U &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "env") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "error_code")) {
        const RSemanticAggregate *aggregate;
        if (!r_semantic_prepare_host_enum(body->frontend, "std.env::error_code", &aggregate))
            return false;
        return r_body_append_enum_constant(
            body, view.span, aggregate, &identifiers[3], result, resolved);
    }
    if (identifier_count == 4U &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "process")) {
        static const char *const names[] = {"error_code", "pipe_mode", "termination_kind"};
        for (size_t index = 0U; index < 3U; ++index) {
            if (r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], names[index])) {
                const RSemanticAggregate *aggregate;
                char canonical[64];
                (void)snprintf(canonical, sizeof(canonical), "std.process::%s", names[index]);
                if (!r_semantic_prepare_host_enum(body->frontend, canonical, &aggregate))
                    return false;
                return r_body_append_enum_constant(
                    body, view.span, aggregate, &identifiers[3], result, resolved);
            }
        }
    }
    if (identifier_count == 4U &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "json")) {
        static const char *const names[] = {"error_code", "value_kind", "mode", "feed_state"};
        for (size_t i = 0U; i < 4U; ++i) {
            if (r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], names[i])) {
                char canonical[64];
                const RSemanticAggregate *standard_enum;
                (void)snprintf(canonical, sizeof(canonical), "std.json::%s", names[i]);
                if (!r_semantic_prepare_json_enum(body->frontend, canonical, &standard_enum))
                    return false;
                return r_body_append_enum_constant(
                    body, view.span, standard_enum, &identifiers[3], result, resolved);
            }
        }
    }
    if ((identifier_count == UINT32_C(4)) &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "bits") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "read_error_code")) {
        const RSemanticAggregate *standard_enum;

        if (!r_semantic_prepare_bits_read_error_code_schema(body->frontend, &standard_enum)) {
            return false;
        }
        return r_body_append_enum_constant(
            body, view.span, standard_enum, &identifiers[3], result, resolved);
    }
    if ((identifier_count == UINT32_C(4)) &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "convert") &&
        (r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "parse_error_code") ||
         r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "range_error"))) {
        const RSemanticAggregate *standard_enum;
        const bool is_parse =
            r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "parse_error_code");

        if (!(is_parse ? r_semantic_prepare_convert_parse_error_code_schema(body->frontend,
                                                                            &standard_enum)
                       : r_semantic_prepare_convert_range_error_schema(body->frontend,
                                                                       &standard_enum))) {
            return false;
        }
        return r_body_append_enum_constant(
            body, view.span, standard_enum, &identifiers[3], result, resolved);
    }
    if (identifier_count == 4U &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "net")) {
        static const char *const short_names[] = {"family", "shutdown_direction", "error_code"};
        static const char *const full_names[] = {
            "std.net::family", "std.net::shutdown_direction", "std.net::error_code"};
        uint32_t net_index;
        for (net_index = 0U; net_index < 3U; ++net_index) {
            if (r_semantic_token_text_equal_owned(
                    body->frontend, &identifiers[2], short_names[net_index])) {
                const RSemanticAggregate *standard_enum;
                if (!r_semantic_prepare_net_enum(
                        body->frontend, full_names[net_index], &standard_enum))
                    return false;
                return r_body_append_enum_constant(
                    body, view.span, standard_enum, &identifiers[3], result, resolved);
            }
        }
    }
    if ((identifier_count == UINT32_C(4)) &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "net") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "address_error_code")) {
        const RSemanticAggregate *standard_enum;

        if (!r_semantic_prepare_net_address_error_code_schema(body->frontend, &standard_enum)) {
            return false;
        }
        return r_body_append_enum_constant(
            body, view.span, standard_enum, &identifiers[3], result, resolved);
    }
    if ((identifier_count == UINT32_C(4)) &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "fs") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "error_code")) {
        const RSemanticAggregate *standard_enum;

        if (!r_semantic_prepare_fs_error_code_schema(body->frontend, &standard_enum)) {
            return false;
        }
        return r_body_append_enum_constant(
            body, view.span, standard_enum, &identifiers[3], result, resolved);
    }
    if (identifier_count == 4U &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "fs") &&
        (r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "seek_origin") ||
         r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "file_kind") ||
         r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "sync_level") ||
         r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "lock_kind"))) {
        const RSemanticAggregate *standard_enum;
        const char *fs_enum_name = "std.fs::file_kind";
        if (r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "seek_origin"))
            fs_enum_name = "std.fs::seek_origin";
        if (r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "sync_level"))
            fs_enum_name = "std.fs::sync_level";
        if (r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "lock_kind"))
            fs_enum_name = "std.fs::lock_kind";
        if (!r_semantic_prepare_fs_enum_schema(body->frontend, fs_enum_name, &standard_enum))
            return false;
        return r_body_append_enum_constant(
            body, view.span, standard_enum, &identifiers[3], result, resolved);
    }
    if ((identifier_count == UINT32_C(4)) &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "fs") &&
        (r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "access") ||
         r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "create_mode"))) {
        const RSemanticAggregate *standard_enum;
        const bool is_access =
            r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "access");

        if (!(is_access
                  ? r_semantic_prepare_fs_access_schema(body->frontend, &standard_enum)
                  : r_semantic_prepare_fs_create_mode_schema(body->frontend, &standard_enum))) {
            return false;
        }
        return r_body_append_enum_constant(
            body, view.span, standard_enum, &identifiers[3], result, resolved);
    }
    if ((identifier_count == UINT32_C(4)) &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "io") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "error_code")) {
        const RSemanticAggregate *standard_enum;

        if (!r_semantic_prepare_io_error_code_schema(body->frontend, &standard_enum)) {
            return false;
        }
        return r_body_append_enum_constant(
            body, view.span, standard_enum, &identifiers[3], result, resolved);
    }
    if ((identifier_count == UINT32_C(4)) &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[1], "error") &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[2], "domain")) {
        const RSemanticAggregate *standard_enum;

        if (!r_semantic_prepare_error_domain_schema(body->frontend, &standard_enum)) {
            return false;
        }
        return r_body_append_enum_constant(
            body, view.span, standard_enum, &identifiers[3], result, resolved);
    }
    /* R-STMT-0006: every other natively implemented fieldless enum of the library. */
    if ((identifier_count == UINT32_C(4)) &&
        r_semantic_token_text_equal_owned(body->frontend, &identifiers[0], "std") &&
        (identifiers[1].intern_id != UINT32_C(0)) && (identifiers[2].intern_id != UINT32_C(0)) &&
        ((size_t)identifiers[1].intern_id <= body->frontend->intern_count) &&
        ((size_t)identifiers[2].intern_id <= body->frontend->intern_count)) {
        const RInternEntry *module_entry =
            &body->frontend->intern_entries[(size_t)identifiers[1].intern_id - 1U];
        const RInternEntry *type_entry =
            &body->frontend->intern_entries[(size_t)identifiers[2].intern_id - 1U];
        const RSemanticAggregate *standard_enum = NULL;
        char canonical[96];
        const int written = snprintf(canonical,
                                     sizeof(canonical),
                                     "std.%.*s::%.*s",
                                     (int)module_entry->length,
                                     (const char *)module_entry->bytes,
                                     (int)type_entry->length,
                                     (const char *)type_entry->bytes);

        if ((written > 0) && ((size_t)written < sizeof(canonical)) &&
            !r_semantic_prepare_standard_enum_named(body->frontend, canonical, &standard_enum)) {
            return false;
        }
        if (standard_enum != NULL) {
            return r_body_append_enum_constant(
                body, view.span, standard_enum, &identifiers[3], result, resolved);
        }
    }
    for (aggregate_index = 0U; aggregate_index < body->frontend->semantic_aggregate_count;
         ++aggregate_index) {
        const RSemanticAggregate *aggregate = &body->frontend->semantic_aggregates[aggregate_index];
        const RSource *aggregate_source =
            r_get_source_const(body->frontend, aggregate->module_source);
        bool visible = false;
        size_t import_index;
        if (aggregate->generic_schema != 0U || (aggregate->kind != R_SEMANTIC_AGGREGATE_ENUM) ||
            (aggregate_source == NULL) || (aggregate_source->module_name == NULL) ||
            (aggregate->name_intern_id != enum_name.intern_id)) {
            continue;
        }
        if (identifier_count == UINT32_C(2)) {
            if (aggregate->module_source == body->source) {
                visible = true;
            } else {
                for (import_index = 0U; import_index < body->frontend->import_count;
                     ++import_index) {
                    const RImportEntry *import = &body->frontend->imports[import_index];
                    if ((import->source == body->source) && import->imports_name &&
                        (strcmp(import->module_name, aggregate_source->module_name) == 0) &&
                        r_semantic_token_text_equal_owned(
                            body->frontend, &enum_name, import->name)) {
                        visible = true;
                        break;
                    }
                }
            }
        } else if (r_body_qualified_module_matches(body,
                                                   qualified,
                                                   identifier_count - UINT32_C(2),
                                                   aggregate_source->module_name)) {
            if (aggregate->module_source == body->source) {
                visible = true;
            } else {
                for (import_index = 0U; import_index < body->frontend->import_count;
                     ++import_index) {
                    const RImportEntry *import = &body->frontend->imports[import_index];
                    if ((import->source == body->source) && !import->imports_name &&
                        (strcmp(import->module_name, aggregate_source->module_name) == 0)) {
                        visible = true;
                        break;
                    }
                }
            }
        }
        if (!visible) {
            continue;
        }
        if (aggregate->is_protected && (aggregate->module_source != body->source)) {
            return r_body_diagnostic(body,
                                     "R-DIAG-NAME-001",
                                     "R-NAME-0003",
                                     "protected enum type is not visible",
                                     enum_name.span);
        }
        if (match != NULL) {
            return r_body_diagnostic(body,
                                     "R-DIAG-NAME-001",
                                     "R-NAME-0003",
                                     "enum type name is ambiguous",
                                     enum_name.span);
        }
        match = aggregate;
    }
    if (match != NULL) {
        result->type = match->type;
        return r_body_append_enum_constant(body, view.span, match, &variant_name, result, resolved);
    }
    if (resolved != NULL) {
        return true;
    }
    return r_body_diagnostic(
        body, "R-DIAG-NAME-001", "R-NAME-0003", "enum type is unresolved", enum_name.span);
}

static bool r_body_user_variant_constructor(RBodyContext *body,
                                            RAstRef head,
                                            RAstRef initializer,
                                            bool braced,
                                            RExpressionResult *result,
                                            bool *handled) {
    uint32_t resolved = UINT32_C(0);
    RExpressionResult selected = {0};
    RExpressionResult payload = {0};
    RAstNodeView view;
    RSemanticVariant variant;
    RTypeId container;
    RHirVector children = {0};
    RHirNodeId child_storage[1];
    RHirNodeId node;
    *handled = false;
    if (!r_body_lower_enum_constant(body, head, &selected, &resolved)) {
        return false;
    }
    if (selected.type == R_TYPE_ID_INVALID) {
        return true;
    }
    *handled = true;
    if (!selected.valid || (resolved == UINT32_C(0))) {
        return true;
    }
    variant = body->frontend->semantic_variants[(size_t)resolved - 1U];
    container = selected.type;
    if (!r_ast_ref_view(body->frontend, initializer, &view)) {
        return false;
    }
    if ((variant.payload_type == R_TYPE_ID_INVALID) || (braced != variant.structured_payload)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-AGG-0007",
                                 "variant initializer must match its declared payload form",
                                 view.span);
    }
    if (braced) {
        if (!r_body_lower_aggregate_initializer(
                body, initializer, variant.payload_type, &payload)) {
            return false;
        }
    } else {
        RAstRef arguments;
        RAstRef argument;
        RAstNodeView arguments_view;
        if (!r_ast_find_direct_child(
                body->frontend, initializer, R_SYNTAX_ARGUMENT_LIST, &arguments) ||
            !r_ast_ref_view(body->frontend, arguments, &arguments_view)) {
            return false;
        }
        if (arguments_view.child_count != UINT32_C(1)) {
            return r_body_diagnostic(body,
                                     "R-DIAG-TYPE-001",
                                     "R-AGG-0007",
                                     "variant requires exactly one payload argument",
                                     view.span);
        }
        if (!r_ast_ref_child(body->frontend, arguments, UINT32_C(0), &argument) ||
            !r_body_lower_value(body, argument, variant.payload_type, &payload)) {
            return false;
        }
    }
    if (!payload.valid) {
        return true;
    }
    if (r_semantic_value_type(body->frontend, payload.type) !=
        r_semantic_value_type(body->frontend, variant.payload_type)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-AGG-0007",
                                 "variant payload type does not match its declaration",
                                 view.span);
    }
    child_storage[0] = payload.node;
    children.items = child_storage;
    children.count = 1U;
    children.capacity = 1U;
    if (!r_body_append_node(body,
                            R_HIR_VARIANT,
                            view.span,
                            container,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            (uint64_t)variant.declaration_index,
                            false,
                            &children,
                            &node)) {
        return false;
    }
    r_body_hir_node(body, node)->aggregate_member = resolved;
    r_body_hir_node(body, node)->borrow_origin = payload.borrow_origin;
    r_body_hir_node(body, node)->borrow_referent = payload.borrow_referent;
    r_body_hir_node(body, node)->borrow_origin_set = payload.borrow_origin_set;
    r_body_hir_node(body, node)->borrow_origin_multiple = payload.borrow_origin_multiple;
    result->node = node;
    result->type = container;
    result->borrow_origin = payload.borrow_origin;
    result->borrow_referent = payload.borrow_referent;
    result->borrow_origin_set = payload.borrow_origin_set;
    result->borrow_origin_multiple = payload.borrow_origin_multiple;
    result->valid = true;
    return true;
}

static bool r_body_builtin_variant_operation(const RFrontendContext *context,
                                             RAstRef qualified,
                                             RBuiltinVariantOperation *operation,
                                             RSourceSpan *operation_span) {
    RAstNodeView view;
    RAstTokenView family = {0};
    RAstTokenView name = {0};
    uint32_t child_index;
    uint32_t token_count = UINT32_C(0);

    if ((operation == NULL) ||
        !r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return false;
    }
    *operation = R_BUILTIN_VARIANT_INVALID;
    for (child_index = 0U; child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;
        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token)) {
            continue;
        }
        if (token_count == UINT32_C(0)) {
            family = token;
        } else if (token_count == UINT32_C(1)) {
            name = token;
        }
        token_count += UINT32_C(1);
    }
    if ((token_count != UINT32_C(2)) || (family.kind != R_TOKEN_KW_O) ||
        (name.kind != R_TOKEN_IDENTIFIER)) {
        return false;
    }
    if ((family.kind == R_TOKEN_KW_O) &&
        r_semantic_token_text_equal_owned(context, &name, "none")) {
        *operation = R_BUILTIN_VARIANT_OPTION_NONE;
    } else if ((family.kind == R_TOKEN_KW_O) &&
               r_semantic_token_text_equal_owned(context, &name, "some")) {
        *operation = R_BUILTIN_VARIANT_OPTION_SOME;
    } else {
        return false;
    }
    if (operation_span != NULL) {
        *operation_span = name.span;
    }
    return true;
}

static bool r_body_append_builtin_variant(RBodyContext *body,
                                          RSourceSpan span,
                                          RTypeId result_type,
                                          RBuiltinVariantOperation operation,
                                          const RExpressionResult *payload,
                                          RExpressionResult *result) {
    RHirNodeId child_storage[1];
    RHirVector children = {0};
    RHirNodeId node_id;
    RHirNode *node;
    uint64_t tag;

    if ((operation == R_BUILTIN_VARIANT_OPTION_NONE) ||
        (operation == R_BUILTIN_VARIANT_RESULT_OK)) {
        tag = UINT64_C(0);
    } else if ((operation == R_BUILTIN_VARIANT_OPTION_SOME) ||
               (operation == R_BUILTIN_VARIANT_RESULT_ERR)) {
        tag = UINT64_C(1);
    } else {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    if ((payload != NULL) && (payload->node != R_HIR_NODE_ID_INVALID)) {
        child_storage[0] = payload->node;
        children.items = child_storage;
        children.count = UINT32_C(1);
        children.capacity = UINT32_C(1);
    }
    if (!r_body_append_node(body,
                            R_HIR_VARIANT,
                            span,
                            result_type,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            tag,
                            false,
                            &children,
                            &node_id)) {
        return false;
    }
    node = r_body_hir_node(body, node_id);
    if (node == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    if (payload != NULL) {
        node->borrow_origin = payload->borrow_origin;
        node->borrow_referent = payload->borrow_referent;
        node->borrow_origin_set = payload->borrow_origin_set;
        node->borrow_origin_multiple = payload->borrow_origin_multiple;
    }
    r_body_expression_invalid(result);
    result->node = node_id;
    result->type = result_type;
    if (payload != NULL) {
        result->borrow_origin = payload->borrow_origin;
        result->borrow_referent = payload->borrow_referent;
        result->borrow_origin_set = payload->borrow_origin_set;
        result->borrow_origin_multiple = payload->borrow_origin_multiple;
    }
    result->valid = true;
    return true;
}

static bool r_body_variant_expected_type(RBodyContext *body,
                                         RTypeId contextual_type,
                                         RBuiltinVariantOperation operation,
                                         RTypeId *container_type,
                                         RTypeId *payload_type,
                                         bool *has_payload,
                                         RSourceSpan span) {
    const RTypeId value_type = r_semantic_value_type(body->frontend, contextual_type);
    const RSemanticType *type = r_semantic_type(body->frontend, value_type);

    if ((container_type == NULL) || (payload_type == NULL) || (has_payload == NULL)) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    *container_type = R_TYPE_ID_INVALID;
    *payload_type = R_TYPE_ID_INVALID;
    *has_payload = false;
    if (type == NULL) {
        return r_body_diagnostic(
            body,
            "R-DIAG-TYPE-001",
            "R-AGG-0009",
            "built-in variant constructor requires one expected option or closed outcome type",
            span);
    }
    *container_type = value_type;
    if ((operation == R_BUILTIN_VARIANT_OPTION_NONE) ||
        (operation == R_BUILTIN_VARIANT_OPTION_SOME)) {
        if (type->kind != R_SEMANTIC_TYPE_OPTION) {
            *container_type = R_TYPE_ID_INVALID;
            return r_body_diagnostic(body,
                                     "R-DIAG-TYPE-001",
                                     "R-AGG-0009",
                                     "option variant constructor requires one expected o<T> type",
                                     span);
        }
        if (operation == R_BUILTIN_VARIANT_OPTION_SOME) {
            *payload_type = r_semantic_value_type(body->frontend, type->base);
            *has_payload = true;
        }
        return true;
    }
    if (type->kind != R_SEMANTIC_TYPE_RESULT) {
        *container_type = R_TYPE_ID_INVALID;
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-AGG-0010",
                                 "outcome variant constructor requires one expected closed outcome "
                                 "type",
                                 span);
    }
    if (operation == R_BUILTIN_VARIANT_RESULT_OK) {
        *payload_type = r_semantic_value_type(body->frontend, type->base);
        *has_payload = r_semantic_value_kind(body->frontend, type->base) != R_SEMANTIC_TYPE_VOID;
    } else {
        *payload_type = r_semantic_value_type(body->frontend, type->second);
        *has_payload = true;
    }
    return true;
}

static bool r_body_lower_fieldless_variant(RBodyContext *body,
                                           RAstRef qualified,
                                           RTypeId contextual_type,
                                           RBuiltinVariantOperation operation,
                                           RExpressionResult *result) {
    RAstNodeView view;
    RTypeId container_type;
    RTypeId payload_type;
    bool has_payload;

    if (!r_ast_ref_view(body->frontend, qualified, &view) ||
        !r_body_variant_expected_type(body,
                                      contextual_type,
                                      operation,
                                      &container_type,
                                      &payload_type,
                                      &has_payload,
                                      view.span)) {
        return false;
    }
    if (container_type == R_TYPE_ID_INVALID) {
        return true;
    }
    (void)payload_type;
    if (has_payload) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-AGG-0009",
                                 "payload variant constructor requires an initializer",
                                 view.span);
    }
    return r_body_append_builtin_variant(body, view.span, container_type, operation, NULL, result);
}

static bool r_body_lower_option_some(RBodyContext *body,
                                     RAstRef postfix,
                                     RAstRef primary,
                                     RAstRef call_suffix,
                                     RTypeId contextual_type,
                                     RExpressionResult *result) {
    RAstNodeView postfix_view;
    RAstRef qualified;
    RAstNodeView qualified_view;
    RBuiltinVariantOperation operation;
    RAstRef argument_list;
    RAstNodeView arguments_view;
    RTypeId container_type;
    RTypeId payload_type;
    bool has_payload;
    RExpressionResult payload;
    RAstRef argument;

    r_body_expression_invalid(result);
    if (!r_ast_ref_view(body->frontend, postfix, &postfix_view) ||
        !r_ast_find_direct_child(body->frontend, primary, R_SYNTAX_QUALIFIED_NAME, &qualified) ||
        !r_ast_view_kind(body->frontend, qualified, R_SYNTAX_QUALIFIED_NAME, &qualified_view) ||
        !r_body_builtin_variant_operation(body->frontend, qualified, &operation, NULL) ||
        (operation != R_BUILTIN_VARIANT_OPTION_SOME) ||
        !r_ast_find_direct_child(
            body->frontend, call_suffix, R_SYNTAX_ARGUMENT_LIST, &argument_list) ||
        !r_ast_ref_view(body->frontend, argument_list, &arguments_view)) {
        return false;
    }
    (void)qualified_view;
    if (!r_body_variant_expected_type(body,
                                      contextual_type,
                                      operation,
                                      &container_type,
                                      &payload_type,
                                      &has_payload,
                                      postfix_view.span)) {
        return false;
    }
    if (container_type == R_TYPE_ID_INVALID) {
        return true;
    }
    if (!has_payload || (arguments_view.child_count != UINT32_C(1)) ||
        !r_ast_ref_child(body->frontend, argument_list, UINT32_C(0), &argument)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-AGG-0009",
                                 "o::some requires exactly one payload",
                                 postfix_view.span);
    }
    if (!r_body_lower_value(body, argument, payload_type, &payload)) {
        return false;
    }
    if (!payload.valid) {
        return true;
    }
    if (payload.type != payload_type) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-AGG-0009",
                                 "option constructor payload type does not match T",
                                 postfix_view.span);
    }
    return r_body_append_builtin_variant(
        body, postfix_view.span, container_type, operation, &payload, result);
}

static bool r_body_core_operation(const RFrontendContext *context,
                                  RAstRef qualified,
                                  RStandardCallOperation *operation,
                                  RSourceSpan *operation_span) {
    RAstNodeView view;
    RAstTokenView components[2];
    uint32_t child_index;
    uint32_t component_count = UINT32_C(0);

    if ((operation == NULL) ||
        !r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return false;
    }
    *operation = R_STANDARD_CALL_INVALID;
    (void)memset(components, 0, sizeof(components));
    for (child_index = UINT32_C(0); child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;

        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token)) {
            continue;
        }
        if (component_count >= UINT32_C(2)) {
            return false;
        }
        components[component_count] = token;
        component_count += UINT32_C(1);
    }
    if ((component_count != UINT32_C(2)) ||
        !r_semantic_token_text_equal_owned(context, &components[0], "core")) {
        return false;
    }
    if (r_semantic_token_text_equal_owned(context, &components[1], "hash")) {
        *operation = R_STANDARD_CALL_CORE_HASH;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "key_equal")) {
        *operation = R_STANDARD_CALL_CORE_KEY_EQUAL;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "assume")) {
        *operation = R_STANDARD_CALL_CORE_ASSUME;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "slice_from_raw_parts")) {
        *operation = R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS;
    } else if (r_semantic_token_text_equal_owned(
                   context, &components[1], "slice_from_raw_parts_mut")) {
        *operation = R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS_MUT;
    } else if (r_semantic_token_text_equal_owned(
                   context, &components[1], "slice_from_raw_parts_in")) {
        *operation = R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS_IN;
    } else if (r_semantic_token_text_equal_owned(
                   context, &components[1], "slice_from_raw_parts_in_mut")) {
        *operation = R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS_IN_MUT;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "volatile_load")) {
        *operation = R_STANDARD_CALL_CORE_VOLATILE_LOAD;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "volatile_store")) {
        *operation = R_STANDARD_CALL_CORE_VOLATILE_STORE;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "adopt")) {
        *operation = R_STANDARD_CALL_CORE_ADOPT;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "release")) {
        *operation = R_STANDARD_CALL_CORE_RELEASE;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "replace")) {
        *operation = R_STANDARD_CALL_CORE_REPLACE;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "take")) {
        *operation = R_STANDARD_CALL_CORE_TAKE;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "swap")) {
        *operation = R_STANDARD_CALL_CORE_SWAP;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "clone")) {
        *operation = R_STANDARD_CALL_CORE_CLONE;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "validate_utf8")) {
        *operation = R_STANDARD_CALL_UTF8_VALIDATE;
    } else if (r_semantic_token_text_starts_with_owned(context, &components[1], "checked_add_")) {
        *operation = R_STANDARD_CALL_CORE_CHECKED_ADD;
    } else if (r_semantic_token_text_starts_with_owned(context, &components[1], "checked_sub_")) {
        *operation = R_STANDARD_CALL_CORE_CHECKED_SUB;
    } else if (r_semantic_token_text_starts_with_owned(context, &components[1], "checked_mul_")) {
        *operation = R_STANDARD_CALL_CORE_CHECKED_MUL;
    } else if (r_semantic_token_text_starts_with_owned(context, &components[1], "wrapping_add_")) {
        *operation = R_STANDARD_CALL_CORE_WRAPPING_ADD;
    } else if (r_semantic_token_text_starts_with_owned(context, &components[1], "wrapping_sub_")) {
        *operation = R_STANDARD_CALL_CORE_WRAPPING_SUB;
    } else if (r_semantic_token_text_starts_with_owned(context, &components[1], "wrapping_mul_")) {
        *operation = R_STANDARD_CALL_CORE_WRAPPING_MUL;
    } else if (r_semantic_token_text_starts_with_owned(
                   context, &components[1], "saturating_add_")) {
        *operation = R_STANDARD_CALL_CORE_SATURATING_ADD;
    } else if (r_semantic_token_text_starts_with_owned(
                   context, &components[1], "saturating_sub_")) {
        *operation = R_STANDARD_CALL_CORE_SATURATING_SUB;
    } else if (r_semantic_token_text_starts_with_owned(
                   context, &components[1], "saturating_mul_")) {
        *operation = R_STANDARD_CALL_CORE_SATURATING_MUL;
    } else if (r_core_bits_named(context, &components[1], operation)) {
        /* Library R-LIB-0027 (L45): `core::count_ones_u64` and the other bit operations. */
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "atomic_load")) {
        *operation = R_STANDARD_CALL_CORE_ATOMIC_LOAD;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "atomic_store")) {
        *operation = R_STANDARD_CALL_CORE_ATOMIC_STORE;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "atomic_exchange")) {
        *operation = R_STANDARD_CALL_CORE_ATOMIC_EXCHANGE;
    } else if (r_semantic_token_text_equal_owned(
                   context, &components[1], "atomic_compare_exchange")) {
        *operation = R_STANDARD_CALL_CORE_ATOMIC_COMPARE_EXCHANGE;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "atomic_fetch_add")) {
        *operation = R_STANDARD_CALL_CORE_ATOMIC_FETCH_ADD;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "atomic_fetch_sub")) {
        *operation = R_STANDARD_CALL_CORE_ATOMIC_FETCH_SUB;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "atomic_fetch_and")) {
        *operation = R_STANDARD_CALL_CORE_ATOMIC_FETCH_AND;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "atomic_fetch_or")) {
        *operation = R_STANDARD_CALL_CORE_ATOMIC_FETCH_OR;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "atomic_fetch_xor")) {
        *operation = R_STANDARD_CALL_CORE_ATOMIC_FETCH_XOR;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "atomic_is_lock_free")) {
        *operation = R_STANDARD_CALL_CORE_ATOMIC_IS_LOCK_FREE;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "enum_name")) {
        *operation = R_STANDARD_CALL_CORE_ENUM_NAME;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "enum_ordinal")) {
        *operation = R_STANDARD_CALL_CORE_ENUM_ORDINAL;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "variant_name")) {
        *operation = R_STANDARD_CALL_CORE_VARIANT_NAME;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "target_name")) {
        *operation = R_STANDARD_CALL_CORE_TARGET_NAME;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "profile_name")) {
        *operation = R_STANDARD_CALL_CORE_PROFILE_NAME;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "location")) {
        *operation = R_STANDARD_CALL_CORE_LOCATION;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "field")) {
        *operation = R_STANDARD_CALL_CORE_FIELD;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "field_mut")) {
        *operation = R_STANDARD_CALL_CORE_FIELD_MUT;
    } else {
        return false;
    }
    if (operation_span != NULL) {
        *operation_span = components[1].span;
    }
    return true;
}

static bool r_body_core_integer_operation(RStandardCallOperation operation,
                                          bool *checked,
                                          RTokenKind *operator_kind,
                                          const char **prefix) {
    *checked = false;
    switch (operation) {
    case R_STANDARD_CALL_CORE_CHECKED_ADD:
        *checked = true;
        *operator_kind = R_TOKEN_PLUS;
        *prefix = "checked_add_";
        return true;
    case R_STANDARD_CALL_CORE_CHECKED_SUB:
        *checked = true;
        *operator_kind = R_TOKEN_MINUS;
        *prefix = "checked_sub_";
        return true;
    case R_STANDARD_CALL_CORE_CHECKED_MUL:
        *checked = true;
        *operator_kind = R_TOKEN_STAR;
        *prefix = "checked_mul_";
        return true;
    case R_STANDARD_CALL_CORE_WRAPPING_ADD:
        *operator_kind = R_TOKEN_PLUS;
        *prefix = "wrapping_add_";
        return true;
    case R_STANDARD_CALL_CORE_WRAPPING_SUB:
        *operator_kind = R_TOKEN_MINUS;
        *prefix = "wrapping_sub_";
        return true;
    case R_STANDARD_CALL_CORE_WRAPPING_MUL:
        *operator_kind = R_TOKEN_STAR;
        *prefix = "wrapping_mul_";
        return true;
    case R_STANDARD_CALL_CORE_SATURATING_ADD:
        *operator_kind = R_TOKEN_PLUS;
        *prefix = "saturating_add_";
        return true;
    case R_STANDARD_CALL_CORE_SATURATING_SUB:
        *operator_kind = R_TOKEN_MINUS;
        *prefix = "saturating_sub_";
        return true;
    case R_STANDARD_CALL_CORE_SATURATING_MUL:
        *operator_kind = R_TOKEN_STAR;
        *prefix = "saturating_mul_";
        return true;
    default:
        return false;
    }
}

static bool r_body_core_integer_suffix(const RFrontendContext *context,
                                       RSourceSpan span,
                                       const char *prefix,
                                       RTokenKind *token_kind) {
    static const struct {
        const char *name;
        RTokenKind token;
    } suffixes[] = {{"i8", R_TOKEN_KW_I8},
                    {"u8", R_TOKEN_KW_U8},
                    {"i16", R_TOKEN_KW_I16},
                    {"u16", R_TOKEN_KW_U16},
                    {"i32", R_TOKEN_KW_I32},
                    {"u32", R_TOKEN_KW_U32},
                    {"i64", R_TOKEN_KW_I64},
                    {"u64", R_TOKEN_KW_U64},
                    {"isize", R_TOKEN_KW_ISIZE},
                    {"usize", R_TOKEN_KW_USIZE}};
    const RSource *source = r_get_source_const(context, span.source);
    const size_t prefix_length = strlen(prefix);
    size_t index;

    if ((source == NULL) || (span.end < span.start) || ((size_t)span.end > source->length) ||
        ((size_t)(span.end - span.start) <= prefix_length)) {
        return false;
    }
    for (index = 0U; index < sizeof(suffixes) / sizeof(suffixes[0]); ++index) {
        const size_t suffix_length = strlen(suffixes[index].name);
        if (((size_t)(span.end - span.start) == prefix_length + suffix_length) &&
            (memcmp(source->bytes + span.start + prefix_length,
                    suffixes[index].name,
                    suffix_length) == 0)) {
            *token_kind = suffixes[index].token;
            return true;
        }
    }
    return false;
}

static bool r_body_lower_core_integer(RBodyContext *body,
                                      RAstRef argument_list,
                                      const RAstNodeView *arguments_view,
                                      RSourceSpan call_span,
                                      RSourceSpan operation_span,
                                      RStandardCallOperation operation,
                                      RTokenKind selected_type,
                                      RExpressionResult *result) {
    bool checked;
    RTokenKind operator_kind = R_TOKEN_INVALID;
    RTokenKind type_token = selected_type;
    const char *prefix = NULL;
    RTypeId integer_type;
    RTypeId result_type;
    RAstRef argument_ref;
    RExpressionResult arguments[2];
    RHirNodeId child_storage[2];
    RHirVector children;
    RHirNodeId node_id;
    RHirNode *node;
    uint32_t index;

    r_body_expression_invalid(result);
    (void)memset(arguments, 0, sizeof(arguments));
    if (!r_body_core_integer_operation(operation, &checked, &operator_kind, &prefix)) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    if (type_token == R_TOKEN_INVALID &&
        !r_body_core_integer_suffix(body->frontend, operation_span, prefix, &type_token)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-LIB-0001",
                                 "core integer operation has an unsupported type suffix",
                                 operation_span);
    }
    if (arguments_view->child_count != UINT32_C(2)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-LIB-0001",
                                 "core integer operation requires exactly two operands",
                                 call_span);
    }
    if (!r_semantic_type_from_token(body->frontend, type_token, &integer_type)) {
        return false;
    }
    for (index = 0U; index < UINT32_C(2); ++index) {
        if (!r_ast_ref_child(body->frontend, argument_list, index, &argument_ref) ||
            !r_body_lower_value(body, argument_ref, integer_type, &arguments[index])) {
            return false;
        }
        if (!arguments[index].valid) {
            return true;
        }
        if (r_semantic_value_type(body->frontend, arguments[index].type) != integer_type) {
            return r_body_diagnostic(body,
                                     "R-DIAG-TYPE-001",
                                     "R-LIB-0001",
                                     "core integer operand type shall match the function suffix",
                                     call_span);
        }
        child_storage[index] = arguments[index].node;
    }
    result_type = integer_type;
    if (checked && !r_semantic_intern_derived_type(body->frontend,
                                                   R_SEMANTIC_TYPE_OPTION,
                                                   integer_type,
                                                   R_TYPE_ID_INVALID,
                                                   UINT64_C(0),
                                                   R_SEMANTIC_TYPE_FLAG_NONE,
                                                   &result_type)) {
        return false;
    }
    children.items = child_storage;
    children.count = UINT32_C(2);
    children.capacity = UINT32_C(2);
    if (!r_body_append_node(body,
                            R_HIR_STANDARD_CALL,
                            call_span,
                            result_type,
                            R_SYMBOL_ID_INVALID,
                            operator_kind,
                            UINT64_C(0),
                            false,
                            &children,
                            &node_id)) {
        return false;
    }
    node = r_body_hir_node(body, node_id);
    if (node == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    node->standard_operation = operation;
    node->auxiliary_type = integer_type;
    result->node = node_id;
    result->type = result_type;
    result->valid = true;
    return true;
}

static bool r_body_lower_core_atomic(RBodyContext *body,
                                     RAstRef argument_list,
                                     const RAstNodeView *arguments_view,
                                     RSourceSpan call_span,
                                     RStandardCallOperation operation,
                                     RExpressionResult *result) {
    const bool is_load = operation == R_STANDARD_CALL_CORE_ATOMIC_LOAD;
    const bool is_store = operation == R_STANDARD_CALL_CORE_ATOMIC_STORE;
    const bool is_exchange = operation == R_STANDARD_CALL_CORE_ATOMIC_EXCHANGE;
    const bool is_compare = operation == R_STANDARD_CALL_CORE_ATOMIC_COMPARE_EXCHANGE;
    const bool is_lock_free = operation == R_STANDARD_CALL_CORE_ATOMIC_IS_LOCK_FREE;
    const bool is_fetch = (operation >= R_STANDARD_CALL_CORE_ATOMIC_FETCH_ADD) &&
                          (operation <= R_STANDARD_CALL_CORE_ATOMIC_FETCH_XOR);
    const uint32_t expected_count = is_lock_free ? UINT32_C(1)
                                    : is_load    ? UINT32_C(2)
                                    : is_compare ? UINT32_C(5)
                                                 : UINT32_C(3);
    RAstRef argument_ref;
    RExpressionResult arguments[5];
    RHirNodeId child_storage[5];
    RHirVector children;
    const RSemanticType *borrow_type;
    const RSemanticType *atomic_type;
    RTypeId value_type;
    RTypeId result_type;
    RTypeId void_type;
    RTypeId bool_type;
    const RSemanticAggregate *memory_order;
    RHirNodeId node_id;
    RHirNode *node;
    uint32_t index;

    r_body_expression_invalid(result);
    (void)memset(arguments, 0, sizeof(arguments));
    if ((!is_load && !is_store && !is_exchange && !is_compare && !is_lock_free && !is_fetch) ||
        (arguments_view->child_count != expected_count)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-LIB-0011",
                                 "core atomic operation has an invalid argument count",
                                 call_span);
    }
    {
        const bool saved_pending = body->atomic_object_pending;
        const RSymbolId saved_symbol = body->atomic_object_symbol;
        const RSourceSpan saved_span = body->atomic_object_span;
        bool lowered;
        RSymbolId root;
        RSourceSpan root_span;

        body->atomic_object_pending = true;
        body->atomic_object_symbol = R_SYMBOL_ID_INVALID;
        lowered = r_ast_ref_child(body->frontend, argument_list, UINT32_C(0), &argument_ref) &&
                  r_body_lower_sync_resource_argument(body, argument_ref, &arguments[0]);
        root = body->atomic_object_symbol;
        root_span = body->atomic_object_span;
        /* The exemption holds only for the operand that projects the root to its object. */
        if (lowered && arguments[0].valid && (root != R_SYMBOL_ID_INVALID) &&
            !r_body_atomic_static_operand(body, arguments[0].node)) {
            arguments[0].valid = false;
            lowered = r_body_diagnostic(body,
                                        "R-DIAG-MEM-001",
                                        "R-OBJ-0009",
                                        "direct mutable static access requires unsafe; immutable "
                                        "static access requires Sync",
                                        root_span);
        }
        body->atomic_object_pending = saved_pending;
        body->atomic_object_symbol = saved_symbol;
        body->atomic_object_span = saved_span;
        if (!lowered) {
            return false;
        }
    }
    if (!arguments[0].valid) {
        return true;
    }
    borrow_type =
        r_semantic_type(body->frontend, r_semantic_value_type(body->frontend, arguments[0].type));
    atomic_type = (borrow_type == NULL) || (borrow_type->kind != R_SEMANTIC_TYPE_BORROW)
                      ? NULL
                      : r_semantic_type(body->frontend, borrow_type->base);
    if ((borrow_type == NULL) || (borrow_type->kind != R_SEMANTIC_TYPE_BORROW) ||
        (borrow_type->flags != R_SEMANTIC_TYPE_FLAG_SHARED) || (atomic_type == NULL) ||
        (atomic_type->kind != R_SEMANTIC_TYPE_ATOMIC)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-LIB-0011",
                                 "core atomic object shall be a shared borrow of atomic T",
                                 call_span);
    }
    value_type = atomic_type->base;
    if (is_fetch && !r_semantic_type_is_integer(body->frontend, value_type)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-LIB-0011",
                                 "atomic fetch operations require an atomic integer",
                                 call_span);
    }
    child_storage[0] = arguments[0].node;
    for (index = UINT32_C(1); index < expected_count; ++index) {
        const bool order_argument =
            !is_lock_free && (index >= (is_compare ? UINT32_C(3) : expected_count - UINT32_C(1)));
        RTypeId contextual_type = value_type;
        if (order_argument) {
            if (!r_semantic_prepare_core_memory_order_schema(body->frontend, &memory_order)) {
                return false;
            }
            contextual_type = memory_order->type;
        }
        if (!r_ast_ref_child(body->frontend, argument_list, index, &argument_ref) ||
            !r_body_lower_value(body, argument_ref, contextual_type, &arguments[index])) {
            return false;
        }
        if (!arguments[index].valid) {
            return true;
        }
        if (r_semantic_value_type(body->frontend, arguments[index].type) != contextual_type) {
            return r_body_diagnostic(body,
                                     "R-DIAG-TYPE-001",
                                     "R-LIB-0011",
                                     order_argument
                                         ? "atomic memory order shall have type core::memory_order"
                                         : "atomic value operand type shall match T",
                                     call_span);
        }
        child_storage[index] = arguments[index].node;
    }
    if (!is_lock_free && !is_compare) {
        const uint32_t order_index = expected_count - UINT32_C(1);
        const RHirNode *order_node = r_body_hir_node(body, arguments[order_index].node);
        const bool allowed = (order_node == NULL) || (order_node->kind != R_HIR_ENUM_CONSTANT) ||
                             (is_load    ? ((order_node->integer_value == UINT64_C(0)) ||
                                            (order_node->integer_value == UINT64_C(1)) ||
                                            (order_node->integer_value == UINT64_C(4)))
                              : is_store ? ((order_node->integer_value == UINT64_C(0)) ||
                                            (order_node->integer_value == UINT64_C(2)) ||
                                            (order_node->integer_value == UINT64_C(4)))
                                         : (order_node->integer_value <= UINT64_C(4)));
        if (!allowed) {
            return r_body_diagnostic(body,
                                     "R-DIAG-ATOMIC-001",
                                     "R-MEM-0007",
                                     "memory order is invalid for this atomic operation",
                                     order_node->span);
        }
    }
    if (is_compare) {
        const RHirNode *success_node = r_body_hir_node(body, arguments[3].node);
        const RHirNode *failure_node = r_body_hir_node(body, arguments[4].node);
        const bool success_constant =
            (success_node != NULL) && (success_node->kind == R_HIR_ENUM_CONSTANT);
        const bool failure_constant =
            (failure_node != NULL) && (failure_node->kind == R_HIR_ENUM_CONSTANT);
        bool allowed = true;

        if (failure_constant && ((failure_node->integer_value == UINT64_C(2)) ||
                                 (failure_node->integer_value == UINT64_C(3)) ||
                                 (failure_node->integer_value > UINT64_C(4)))) {
            allowed = false;
        }
        if (allowed && success_constant && failure_constant) {
            const uint64_t success = success_node->integer_value;
            const uint64_t failure = failure_node->integer_value;

            allowed =
                success <= UINT64_C(4) && (failure == UINT64_C(0) ||
                                           (((success == UINT64_C(1)) || (success == UINT64_C(3)) ||
                                             (success == UINT64_C(4))) &&
                                            (failure == UINT64_C(1))) ||
                                           ((success == UINT64_C(4)) && (failure == UINT64_C(4))));
        }
        if (!allowed) {
            return r_body_diagnostic(body,
                                     "R-DIAG-ATOMIC-001",
                                     "R-MEM-0007",
                                     "compare-exchange memory orders are incompatible",
                                     failure_node == NULL ? call_span : failure_node->span);
        }
    }
    if (!r_semantic_type_from_token(body->frontend, R_TOKEN_KW_VOID, &void_type) ||
        !r_semantic_type_from_token(body->frontend, R_TOKEN_KW_BOOL, &bool_type)) {
        return false;
    }
    if (is_compare) {
        if (!r_semantic_intern_parametric_standard_type(body->frontend,
                                                        "core::atomic_compare_exchange_result",
                                                        value_type,
                                                        R_TYPE_ID_INVALID,
                                                        &result_type)) {
            return false;
        }
    } else {
        result_type = is_store ? void_type : is_lock_free ? bool_type : value_type;
    }
    children.items = child_storage;
    children.count = expected_count;
    children.capacity = UINT32_C(5);
    if (!r_body_append_node(body,
                            R_HIR_STANDARD_CALL,
                            call_span,
                            result_type,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            UINT64_C(0),
                            false,
                            &children,
                            &node_id)) {
        return false;
    }
    node = r_body_hir_node(body, node_id);
    if (node == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    node->standard_operation = operation;
    node->auxiliary_type = value_type;
    result->node = node_id;
    result->type = result_type;
    result->valid = true;
    return true;
}

static bool r_semantic_type_is_slice_parts_element(const RFrontendContext *context,
                                                   RTypeId type_id) {
    const RSemanticType *type = r_semantic_type(context, type_id);
    const RSemanticAggregate *aggregate;

    if (type == NULL) {
        return false;
    }
    if ((type->kind == R_SEMANTIC_TYPE_VOID) || (type->kind == R_SEMANTIC_TYPE_NEVER) ||
        (type->kind == R_SEMANTIC_TYPE_CONST) || (type->kind == R_SEMANTIC_TYPE_INVALID)) {
        return false;
    }
    if ((type->kind == R_SEMANTIC_TYPE_STRUCT) || (type->kind == R_SEMANTIC_TYPE_ENUM)) {
        aggregate = r_semantic_aggregate_for_type(context, type_id);
        return (aggregate != NULL) && aggregate->complete && !aggregate->poisoned &&
               ((aggregate->kind != R_SEMANTIC_AGGREGATE_ENUM) ||
                (aggregate->variant_count != UINT32_C(0)));
    }
    if (type->kind == R_SEMANTIC_TYPE_FIXED_ARRAY) {
        return (type->length != UINT64_C(0)) &&
               r_semantic_type_is_slice_parts_element(context, type->base);
    }
    return true;
}

static bool r_body_lower_core_adopt_release(RBodyContext *body,
                                            RAstRef argument_list,
                                            const RAstNodeView *arguments_view,
                                            RSourceSpan call_span,
                                            RSourceSpan operation_span,
                                            RStandardCallOperation operation,
                                            RExpressionResult *result) {
    const bool is_adopt = operation == R_STANDARD_CALL_CORE_ADOPT;
    RAstRef argument_ref;
    RExpressionResult argument;
    const RSemanticType *argument_type;
    RTypeId element_type;
    RTypeId result_type;
    RHirNodeId child_storage[1];
    RHirVector children;
    RHirNodeId node_id;
    RHirNode *node;

    r_body_expression_invalid(result);
    r_body_expression_invalid(&argument);
    if ((operation != R_STANDARD_CALL_CORE_ADOPT) && (operation != R_STANDARD_CALL_CORE_RELEASE)) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    if (arguments_view->child_count != UINT32_C(1)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-UNSAFE-0008",
                                 is_adopt ? "core::adopt requires exactly one raw T* pointer"
                                          : "core::release requires exactly one own T* owner",
                                 call_span);
    }
    /* R-CONF-0005: adopting an object needs the allocator that later releases it. */
    if (is_adopt && !r_semantic_profile_at_least(body->frontend, R_FRONTEND_PROFILE_ALLOCATION)) {
        return r_body_diagnostic(body,
                                 R_SEMANTIC_PROFILE_CODE,
                                 R_SEMANTIC_PROFILE_RULE,
                                 "core::adopt requires at least the allocation profile",
                                 operation_span);
    }
    if ((body->unsafe_depth == UINT32_C(0)) &&
        !r_body_diagnostic(body,
                           "R-DIAG-UNSAFE-001",
                           "R-UNSAFE-0001",
                           is_adopt ? "core::adopt is outside an unsafe context"
                                    : "core::release is outside an unsafe context",
                           operation_span)) {
        return false;
    }
    if (!r_ast_ref_child(body->frontend, argument_list, UINT32_C(0), &argument_ref) ||
        !r_body_lower_value(body, argument_ref, R_TYPE_ID_INVALID, &argument)) {
        return false;
    }
    if (!argument.valid) {
        return true;
    }
    argument_type =
        r_semantic_type(body->frontend, r_semantic_value_type(body->frontend, argument.type));
    if ((argument_type == NULL) ||
        (argument_type->kind != (is_adopt ? R_SEMANTIC_TYPE_RAW : R_SEMANTIC_TYPE_OWN)) ||
        ((argument_type->flags & (R_SEMANTIC_TYPE_FLAG_SHARED | R_SEMANTIC_TYPE_FLAG_NULLABLE)) !=
         0U) ||
        !r_semantic_type_is_slice_parts_element(body->frontend, argument_type->base)) {
        return r_body_diagnostic(
            body,
            "R-DIAG-TYPE-001",
            "R-UNSAFE-0008",
            is_adopt ? "core::adopt requires non-null mutable raw T* with a complete, sized, "
                       "inhabited unqualified T"
                     : "core::release requires non-null own T* with a complete, sized, inhabited "
                       "unqualified T",
            call_span);
    }
    element_type = argument_type->base;
    if (is_adopt && r_semantic_owner_payload_holds_region(body->frontend, element_type, 0U)) {
        return r_body_diagnostic(
            body, "R-DIAG-TYPE-001", "R-BORROW-0018", r_semantic_owner_payload_message, call_span);
    }
    if (!r_semantic_intern_derived_type(body->frontend,
                                        is_adopt ? R_SEMANTIC_TYPE_OWN : R_SEMANTIC_TYPE_RAW,
                                        element_type,
                                        R_TYPE_ID_INVALID,
                                        UINT64_C(0),
                                        R_SEMANTIC_TYPE_FLAG_NONE,
                                        &result_type)) {
        return false;
    }
    child_storage[0] = argument.node;
    children.items = child_storage;
    children.count = UINT32_C(1);
    children.capacity = UINT32_C(1);
    if (!r_body_append_node(body,
                            R_HIR_STANDARD_CALL,
                            call_span,
                            result_type,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            UINT64_C(0),
                            false,
                            &children,
                            &node_id)) {
        return false;
    }
    node = r_body_hir_node(body, node_id);
    if (node == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    node->standard_operation = operation;
    node->auxiliary_type = element_type;
    result->node = node_id;
    result->type = result_type;
    result->valid = true;
    return true;
}

static bool r_body_lower_resource_argument(
    RBodyContext *, RAstRef, bool, const char *, const char *, RExpressionResult *);

/* L38: the anchor of a raw-parts slice supplies only its region and is never evaluated, so it is
   a place or a borrow of one: names, fields, dereferences and implicit conversions, with no
   call, index or other computation whose effects would be lost. */
static bool r_body_slice_anchor_is_place(RBodyContext *body, RHirNodeId node_id, uint32_t depth) {
    const RHirNode *node = r_body_hir_node(body, node_id);
    uint32_t child_index;

    if ((node == NULL) || (depth > UINT32_C(64))) {
        return false;
    }
    switch (node->kind) {
    case R_HIR_PLACE:
    case R_HIR_FIELD_PLACE:
    case R_HIR_DEREF_PLACE:
    case R_HIR_BORROW:
    case R_HIR_LOAD:
        break;
    case R_HIR_CAST:
        if (node->operation != R_TOKEN_INVALID) {
            return false;
        }
        break;
    default:
        return false;
    }
    for (child_index = UINT32_C(0); child_index < node->child_count; ++child_index) {
        RHirNodeId child;

        if (!r_body_hir_child(body, node, child_index, &child) ||
            !r_body_slice_anchor_is_place(body, child, depth + UINT32_C(1))) {
            return false;
        }
    }
    return true;
}

/* R-UNSAFE-0008: core::slice_from_raw_parts(_mut) make a slice with a fresh region of its
   destination; the anchored forms (L38) take the region of their first argument instead, a
   borrow, slice or str value, so the slice may live, be stored and be returned as long as that
   anchor could, and the borrow rules keep the anchor's storage alive and, for the mutable form,
   otherwise unused while the slice is live. */
static bool r_body_lower_core_slice_from_raw_parts(RBodyContext *body,
                                                   RAstRef argument_list,
                                                   const RAstNodeView *arguments_view,
                                                   RSourceSpan call_span,
                                                   RSourceSpan operation_span,
                                                   RStandardCallOperation operation,
                                                   RExpressionResult *result) {
    const bool anchored = (operation == R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS_IN) ||
                          (operation == R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS_IN_MUT);
    const bool shared = (operation == R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS) ||
                        (operation == R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS_IN);
    /* Diagnostics keep their message pointers, so every message is a literal; the forms are
       indexed shared, mutable, anchored shared, anchored mutable. */
    const size_t form = (anchored ? 2U : 0U) + (shared ? 0U : 1U);
    static const char *const arity_messages[] = {
        "core::slice_from_raw_parts requires a raw const pointer and usize length",
        "core::slice_from_raw_parts_mut requires a raw pointer and usize length",
        "core::slice_from_raw_parts_in requires an anchor, a raw const pointer and usize length",
        ("core::slice_from_raw_parts_in_mut requires an exclusive anchor, a raw pointer and "
         "usize length")};
    static const char *const unsafe_messages[] = {
        "core::slice_from_raw_parts is outside an unsafe context",
        "core::slice_from_raw_parts_mut is outside an unsafe context",
        "core::slice_from_raw_parts_in is outside an unsafe context",
        "core::slice_from_raw_parts_in_mut is outside an unsafe context"};
    static const char *const pointer_messages[] = {
        ("core::slice_from_raw_parts requires raw const T*? with a complete, sized, inhabited "
         "unqualified T"),
        ("core::slice_from_raw_parts_mut requires raw T*? with a complete, sized, inhabited "
         "unqualified T"),
        ("core::slice_from_raw_parts_in requires raw const T*? with a complete, sized, "
         "inhabited unqualified T"),
        ("core::slice_from_raw_parts_in_mut requires raw T*? with a complete, sized, inhabited "
         "unqualified T")};
    const uint32_t first = anchored ? UINT32_C(1) : UINT32_C(0);
    RAstRef anchor_ref;
    RAstRef pointer_ref;
    RAstRef length_ref;
    RExpressionResult anchor;
    RExpressionResult pointer;
    RExpressionResult length;
    const RSemanticType *pointer_type;
    RTypeId element_type;
    RTypeId usize_type;
    RTypeId result_type;
    RHirNodeId child_storage[2];
    RHirVector children;
    RHirNodeId node_id;
    RHirNode *node;

    r_body_expression_invalid(result);
    r_body_expression_invalid(&anchor);
    r_body_expression_invalid(&pointer);
    r_body_expression_invalid(&length);
    if ((operation != R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS) &&
        (operation != R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS_MUT) && !anchored) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    if (arguments_view->child_count != first + UINT32_C(2)) {
        return r_body_diagnostic(
            body, "R-DIAG-TYPE-001", "R-UNSAFE-0008", arity_messages[form], call_span);
    }
    if ((body->unsafe_depth == UINT32_C(0)) &&
        !r_body_diagnostic(
            body, "R-DIAG-UNSAFE-001", "R-UNSAFE-0001", unsafe_messages[form], operation_span)) {
        return false;
    }
    if (anchored) {
        const RSemanticType *anchor_type;
        RSemanticTypeKind anchor_kind;

        /* `&place` borrows the place with the permission of the form. */
        if (!r_ast_ref_child(body->frontend, argument_list, UINT32_C(0), &anchor_ref) ||
            !r_body_lower_resource_argument(body,
                                            anchor_ref,
                                            shared,
                                            "R-UNSAFE-0008",
                                            "the anchor of a raw-parts slice shall borrow a place",
                                            &anchor)) {
            return false;
        }
        if (!anchor.valid) {
            return true;
        }
        anchor_type =
            r_semantic_type(body->frontend, r_semantic_value_type(body->frontend, anchor.type));
        anchor_kind = anchor_type != NULL ? anchor_type->kind : R_SEMANTIC_TYPE_INVALID;
        if (((anchor_kind != R_SEMANTIC_TYPE_BORROW) && (anchor_kind != R_SEMANTIC_TYPE_SLICE) &&
             (anchor_kind != R_SEMANTIC_TYPE_STR)) ||
            (!shared && ((anchor_kind == R_SEMANTIC_TYPE_STR) ||
                         ((anchor_type->flags & R_SEMANTIC_TYPE_FLAG_SHARED) != 0U)))) {
            return r_body_diagnostic(
                body,
                "R-DIAG-TYPE-001",
                "R-UNSAFE-0008",
                shared ? "core::slice_from_raw_parts_in requires a borrow, slice or str anchor"
                       : "core::slice_from_raw_parts_in_mut requires an exclusive borrow or "
                         "mutable slice anchor",
                call_span);
        }
        if (!r_body_slice_anchor_is_place(body, anchor.node, UINT32_C(0))) {
            return r_body_diagnostic(body,
                                     "R-DIAG-TYPE-001",
                                     "R-UNSAFE-0008",
                                     "the anchor of a raw-parts slice is not evaluated, so it "
                                     "shall be a place or a borrow of one",
                                     call_span);
        }
    }
    if (!r_ast_ref_child(body->frontend, argument_list, first, &pointer_ref) ||
        !r_body_lower_value(body, pointer_ref, R_TYPE_ID_INVALID, &pointer)) {
        return false;
    }
    if (!pointer.valid) {
        return true;
    }
    pointer_type =
        r_semantic_type(body->frontend, r_semantic_value_type(body->frontend, pointer.type));
    if ((pointer_type == NULL) || (pointer_type->kind != R_SEMANTIC_TYPE_RAW) ||
        (((pointer_type->flags & R_SEMANTIC_TYPE_FLAG_SHARED) != 0U) != shared) ||
        !r_semantic_type_is_slice_parts_element(body->frontend, pointer_type->base)) {
        return r_body_diagnostic(
            body, "R-DIAG-TYPE-001", "R-UNSAFE-0008", pointer_messages[form], call_span);
    }
    element_type = pointer_type->base;
    if (!r_semantic_type_from_token(body->frontend, R_TOKEN_KW_USIZE, &usize_type) ||
        !r_ast_ref_child(body->frontend, argument_list, first + UINT32_C(1), &length_ref) ||
        !r_body_lower_value(body, length_ref, usize_type, &length)) {
        return false;
    }
    if (!length.valid) {
        return true;
    }
    if (r_semantic_value_type(body->frontend, length.type) != usize_type) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-UNSAFE-0008",
                                 "core slice raw-parts length shall have type usize",
                                 call_span);
    }
    if (!r_semantic_intern_derived_type(body->frontend,
                                        R_SEMANTIC_TYPE_SLICE,
                                        element_type,
                                        R_TYPE_ID_INVALID,
                                        UINT64_C(0),
                                        shared ? R_SEMANTIC_TYPE_FLAG_SHARED
                                               : R_SEMANTIC_TYPE_FLAG_NONE,
                                        &result_type)) {
        return false;
    }
    child_storage[0] = pointer.node;
    child_storage[1] = length.node;
    children.items = child_storage;
    children.count = UINT32_C(2);
    children.capacity = UINT32_C(2);
    if (!r_body_append_node(body,
                            R_HIR_STANDARD_CALL,
                            call_span,
                            result_type,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            anchored ? UINT64_C(1) : UINT64_C(0),
                            false,
                            &children,
                            &node_id)) {
        return false;
    }
    node = r_body_hir_node(body, node_id);
    if (node == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    node->standard_operation = shared ? R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS
                                      : R_STANDARD_CALL_CORE_SLICE_FROM_RAW_PARTS_MUT;
    node->auxiliary_type = element_type;
    node->borrow_origin = R_SYMBOL_ID_INVALID;
    result->borrow_origin = R_SYMBOL_ID_INVALID;
    if (anchored) {
        node->borrow_origin = anchor.borrow_origin;
        node->borrow_referent = anchor.borrow_referent;
        node->borrow_origin_set = anchor.borrow_origin_set;
        node->borrow_origin_multiple = anchor.borrow_origin_multiple;
        result->borrow_origin = anchor.borrow_origin;
        result->borrow_referent = anchor.borrow_referent;
        result->borrow_origin_set = anchor.borrow_origin_set;
        result->borrow_origin_multiple = anchor.borrow_origin_multiple;
    }
    result->node = node_id;
    result->type = result_type;
    result->valid = true;
    return true;
}

static bool r_body_lower_core_assume(RBodyContext *body,
                                     RAstRef argument_list,
                                     const RAstNodeView *arguments_view,
                                     RSourceSpan call_span,
                                     RSourceSpan operation_span,
                                     RExpressionResult *result) {
    RAstRef argument;
    RExpressionResult condition;
    RTypeId bool_type;
    RTypeId void_type;
    RHirNodeId child_storage[1];
    RHirVector children;
    RHirNodeId node_id;
    RHirNode *node;

    r_body_expression_invalid(result);
    if (arguments_view->child_count != UINT32_C(1)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-UNSAFE-0008",
                                 "core::assume requires exactly one bool argument",
                                 call_span);
    }
    if ((body->unsafe_depth == UINT32_C(0)) &&
        !r_body_diagnostic(body,
                           "R-DIAG-UNSAFE-001",
                           "R-UNSAFE-0001",
                           "core::assume is outside an unsafe context",
                           operation_span)) {
        return false;
    }
    if (!r_semantic_type_from_token(body->frontend, R_TOKEN_KW_BOOL, &bool_type) ||
        !r_semantic_type_from_token(body->frontend, R_TOKEN_KW_VOID, &void_type) ||
        !r_ast_ref_child(body->frontend, argument_list, UINT32_C(0), &argument) ||
        !r_body_lower_value(body, argument, bool_type, &condition)) {
        return false;
    }
    if (!condition.valid) {
        return true;
    }
    if (condition.type != bool_type) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-UNSAFE-0008",
                                 "core::assume argument shall have type bool",
                                 call_span);
    }
    child_storage[0] = condition.node;
    children.items = child_storage;
    children.count = UINT32_C(1);
    children.capacity = UINT32_C(1);
    if (!r_body_append_node(body,
                            R_HIR_STANDARD_CALL,
                            call_span,
                            void_type,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            UINT64_C(0),
                            false,
                            &children,
                            &node_id)) {
        return false;
    }
    node = r_body_hir_node(body, node_id);
    if (node == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    node->standard_operation = R_STANDARD_CALL_CORE_ASSUME;
    node->auxiliary_type = bool_type;
    result->node = node_id;
    result->type = void_type;
    result->valid = true;
    return true;
}

static bool r_body_lower_core_volatile(RBodyContext *body,
                                       RAstRef argument_list,
                                       const RAstNodeView *arguments_view,
                                       RSourceSpan call_span,
                                       RSourceSpan operation_span,
                                       RStandardCallOperation operation,
                                       RExpressionResult *result) {
    const bool is_load = operation == R_STANDARD_CALL_CORE_VOLATILE_LOAD;
    const uint32_t expected_count = is_load ? UINT32_C(1) : UINT32_C(2);
    RAstRef address_ref;
    RAstRef value_ref;
    RExpressionResult address;
    RExpressionResult value;
    const RSemanticType *pointer_type;
    RTypeId void_type;
    RTypeId result_type;
    RHirNodeId child_storage[2];
    RHirVector children;
    RHirNodeId node_id;
    RHirNode *node;

    r_body_expression_invalid(result);
    r_body_expression_invalid(&address);
    r_body_expression_invalid(&value);
    if ((operation != R_STANDARD_CALL_CORE_VOLATILE_LOAD) &&
        (operation != R_STANDARD_CALL_CORE_VOLATILE_STORE)) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    if (arguments_view->child_count != expected_count) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-UNSAFE-0008",
                                 is_load ? "core::volatile_load requires one raw pointer argument"
                                         : "core::volatile_store requires a raw pointer and value",
                                 call_span);
    }
    if ((body->unsafe_depth == UINT32_C(0)) &&
        !r_body_diagnostic(body,
                           "R-DIAG-UNSAFE-001",
                           "R-UNSAFE-0001",
                           is_load ? "core::volatile_load is outside an unsafe context"
                                   : "core::volatile_store is outside an unsafe context",
                           operation_span)) {
        return false;
    }
    if (!r_ast_ref_child(body->frontend, argument_list, UINT32_C(0), &address_ref) ||
        !r_body_lower_value(body, address_ref, R_TYPE_ID_INVALID, &address)) {
        return false;
    }
    if (!address.valid) {
        return true;
    }
    pointer_type =
        r_semantic_type(body->frontend, r_semantic_value_type(body->frontend, address.type));
    if ((pointer_type == NULL) || (pointer_type->kind != R_SEMANTIC_TYPE_RAW) ||
        ((pointer_type->flags & R_SEMANTIC_TYPE_FLAG_NULLABLE) != 0U) ||
        (((pointer_type->flags & R_SEMANTIC_TYPE_FLAG_SHARED) != 0U) != is_load) ||
        !r_semantic_type_is_volatile_value(body->frontend, pointer_type->base)) {
        return r_body_diagnostic(
            body,
            "R-DIAG-TYPE-001",
            "R-UNSAFE-0008",
            is_load ? "core::volatile_load requires raw const T* with a permitted Copy pointee"
                    : "core::volatile_store requires raw T* with a permitted Copy pointee",
            call_span);
    }
    child_storage[0] = address.node;
    if (!is_load) {
        if (!r_ast_ref_child(body->frontend, argument_list, UINT32_C(1), &value_ref) ||
            !r_body_lower_value(body, value_ref, pointer_type->base, &value)) {
            return false;
        }
        if (!value.valid) {
            return true;
        }
        if (r_semantic_value_type(body->frontend, value.type) != pointer_type->base) {
            return r_body_diagnostic(body,
                                     "R-DIAG-TYPE-001",
                                     "R-UNSAFE-0008",
                                     "core::volatile_store value type shall match the pointee",
                                     call_span);
        }
        child_storage[1] = value.node;
    }
    if (!r_semantic_type_from_token(body->frontend, R_TOKEN_KW_VOID, &void_type)) {
        return false;
    }
    result_type = is_load ? pointer_type->base : void_type;
    children.items = child_storage;
    children.count = expected_count;
    children.capacity = UINT32_C(2);
    if (!r_body_append_node(body,
                            R_HIR_STANDARD_CALL,
                            call_span,
                            result_type,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            UINT64_C(0),
                            false,
                            &children,
                            &node_id)) {
        return false;
    }
    node = r_body_hir_node(body, node_id);
    if (node == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    node->standard_operation = operation;
    node->auxiliary_type = pointer_type->base;
    result->node = node_id;
    result->type = result_type;
    result->valid = true;
    return true;
}

static bool r_body_standard_array_operation(const RFrontendContext *context,
                                            RAstRef qualified,
                                            RStandardArrayOperation *operation,
                                            RSourceSpan *operation_span) {
    static const char *const prefix[] = {"std", "array"};
    RAstNodeView view;
    RAstTokenView components[3];
    uint32_t child_index;
    uint32_t component_count = UINT32_C(0);

    if ((operation == NULL) ||
        !r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return false;
    }
    *operation = R_STANDARD_ARRAY_OPERATION_INVALID;
    (void)memset(components, 0, sizeof(components));
    for (child_index = 0U; child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;
        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token)) {
            continue;
        }
        if (component_count >= UINT32_C(3)) {
            return false;
        }
        components[component_count] = token;
        component_count += UINT32_C(1);
    }
    if ((component_count != UINT32_C(3)) ||
        !r_semantic_token_text_equal_owned(context, &components[0], prefix[0]) ||
        !r_semantic_token_text_equal_owned(context, &components[1], prefix[1])) {
        return false;
    }
    if (r_semantic_token_text_equal_owned(context, &components[2], "as_slice")) {
        *operation = R_STANDARD_ARRAY_OPERATION_AS_SLICE;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "as_slice_mut")) {
        *operation = R_STANDARD_ARRAY_OPERATION_AS_SLICE_MUT;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "create")) {
        *operation = R_STANDARD_ARRAY_OPERATION_CREATE;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "capacity")) {
        *operation = R_STANDARD_ARRAY_OPERATION_CAPACITY;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "reserve")) {
        *operation = R_STANDARD_ARRAY_OPERATION_RESERVE;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "push")) {
        *operation = R_STANDARD_ARRAY_OPERATION_PUSH;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "pop")) {
        *operation = R_STANDARD_ARRAY_OPERATION_POP;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "remove")) {
        *operation = R_STANDARD_ARRAY_OPERATION_REMOVE;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "get")) {
        *operation = R_STANDARD_ARRAY_OPERATION_GET;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "get_mut")) {
        *operation = R_STANDARD_ARRAY_OPERATION_GET_MUT;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "clear")) {
        *operation = R_STANDARD_ARRAY_OPERATION_CLEAR;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "with_capacity")) {
        *operation = R_STANDARD_ARRAY_OPERATION_WITH_CAPACITY;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "filled")) {
        *operation = R_STANDARD_ARRAY_OPERATION_FILLED;
    } else {
        return false;
    }
    if (operation_span != NULL) {
        *operation_span = components[2].span;
    }
    return true;
}

typedef struct RStandardOperationName {
    const char *name;
    RStandardCallOperation operation;
} RStandardOperationName;

static bool r_body_standard_module_operation(const RFrontendContext *context,
                                             RAstRef qualified,
                                             const char *module,
                                             const RStandardOperationName *operations,
                                             size_t operation_count,
                                             RStandardCallOperation *operation,
                                             RSourceSpan *operation_span) {
    RAstNodeView view;
    RAstTokenView components[3];
    uint32_t child_index;
    uint32_t component_count = UINT32_C(0);
    size_t operation_index;

    if ((operation == NULL) || (module == NULL) || (operations == NULL) ||
        !r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return false;
    }
    *operation = R_STANDARD_CALL_INVALID;
    (void)memset(components, 0, sizeof(components));
    for (child_index = UINT32_C(0); child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;

        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token)) {
            continue;
        }
        if (component_count >= UINT32_C(3)) {
            return false;
        }
        components[component_count++] = token;
    }
    if ((component_count != UINT32_C(3)) ||
        !r_semantic_token_text_equal_owned(context, &components[0], "std") ||
        !r_semantic_token_text_equal_owned(context, &components[1], module)) {
        return false;
    }
    for (operation_index = 0U; operation_index < operation_count; ++operation_index) {
        if (r_semantic_token_text_equal_owned(
                context, &components[2], operations[operation_index].name)) {
            *operation = operations[operation_index].operation;
            if (operation_span != NULL) {
                *operation_span = components[2].span;
            }
            return true;
        }
    }
    return false;
}

/* A std.module::operation call spelling carries exactly three identifier components. */
static bool r_semantic_qualified_call_permitted(const RFrontendContext *context,
                                                RAstRef qualified,
                                                const char **message) {
    RAstNodeView view;
    RAstTokenView components[3];
    uint32_t component_count = UINT32_C(0);
    uint32_t child_index;
    const char *scope_bytes;
    size_t scope_length;
    const char *module_bytes;
    size_t module_length;
    const char *item_bytes;
    size_t item_length;

    if (!r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return true;
    }
    (void)memset(components, 0, sizeof(components));
    for (child_index = UINT32_C(0); child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;

        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token) || (token.kind != R_TOKEN_IDENTIFIER)) {
            continue;
        }
        if (component_count >= UINT32_C(3)) {
            return true;
        }
        components[component_count++] = token;
    }
    if ((component_count != UINT32_C(3)) ||
        !r_semantic_intern_text(context, components[0].intern_id, &scope_bytes, &scope_length) ||
        !r_semantic_bytes_equal_text(scope_bytes, scope_length, "std") ||
        !r_semantic_intern_text(context, components[1].intern_id, &module_bytes, &module_length) ||
        !r_semantic_intern_text(context, components[2].intern_id, &item_bytes, &item_length)) {
        return true;
    }
    return r_semantic_standard_item_permitted(
        context, module_bytes, module_length, item_bytes, item_length, message);
}

static const RStandardOperationRegistryEntry *
r_body_public_standard_operation_entry(const RFrontendContext *context, RAstRef qualified) {
    RAstNodeView view;
    RAstTokenView components[3];
    uint32_t child_index;
    uint32_t component_count = UINT32_C(0);
    size_t operation_index;

    if (!r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return NULL;
    }
    (void)memset(components, 0, sizeof(components));
    for (child_index = UINT32_C(0); child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;

        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token)) {
            continue;
        }
        if (component_count >= UINT32_C(3)) {
            return NULL;
        }
        components[component_count++] = token;
    }
    for (operation_index = 0U; operation_index < (sizeof(r_standard_operation_registry) /
                                                  sizeof(r_standard_operation_registry[0]));
         ++operation_index) {
        const RStandardOperationRegistryEntry *entry =
            &r_standard_operation_registry[operation_index];

        if ((component_count == UINT32_C(2)) && (entry->module[0] == '\0') &&
            r_semantic_token_text_equal_owned(context, &components[0], entry->scope) &&
            r_semantic_token_text_equal_owned(context, &components[1], entry->operation)) {
            return entry;
        }
        if ((component_count == UINT32_C(3)) && (entry->module[0] != '\0') &&
            r_semantic_token_text_equal_owned(context, &components[0], entry->scope) &&
            r_semantic_token_text_equal_owned(context, &components[1], entry->module) &&
            r_semantic_token_text_equal_owned(context, &components[2], entry->operation)) {
            return entry;
        }
    }
    return NULL;
}

static bool r_body_public_standard_operation(const RFrontendContext *context, RAstRef qualified) {
    return r_body_public_standard_operation_entry(context, qualified) != NULL;
}

static bool r_body_standard_alloc_operation(const RFrontendContext *context,
                                            RAstRef qualified,
                                            RStandardCallOperation *operation,
                                            RSourceSpan *operation_span) {
    static const RStandardOperationName operations[] = {
        {"try_new", R_STANDARD_CALL_ALLOC_TRY_NEW},
        {"into_value", R_STANDARD_CALL_ALLOC_INTO_VALUE},
        {"bytes", R_STANDARD_CALL_ALLOC_BYTES},
    };
    return r_body_standard_module_operation(context,
                                            qualified,
                                            "alloc",
                                            operations,
                                            sizeof(operations) / sizeof(operations[0]),
                                            operation,
                                            operation_span);
}

