static bool r_body_standard_bytes_operation(const RFrontendContext *context,
                                            RAstRef qualified,
                                            RStandardCallOperation *operation,
                                            RSourceSpan *operation_span) {
    RAstNodeView view;
    RAstTokenView components[3];
    uint32_t child_index;
    uint32_t component_count = UINT32_C(0);

    if ((operation == NULL) ||
        !r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return false;
    }
    *operation = R_STANDARD_CALL_INVALID;
    (void)memset(components, 0, sizeof(components));
    for (child_index = UINT32_C(0); child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;

        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token)) {
            continue;
        }
        if (component_count >= UINT32_C(3)) {
            return false;
        }
        components[component_count] = token;
        component_count += UINT32_C(1);
    }
    if ((component_count != UINT32_C(3)) ||
        !r_semantic_token_text_equal_owned(context, &components[0], "std") ||
        !r_semantic_token_text_equal_owned(context, &components[1], "bytes")) {
        return false;
    }
    if (r_semantic_token_text_equal_owned(context, &components[2], "with_capacity")) {
        *operation = R_STANDARD_CALL_BYTES_WITH_CAPACITY;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "append")) {
        *operation = R_STANDARD_CALL_BYTES_APPEND;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "append_u8")) {
        *operation = R_STANDARD_CALL_BYTES_APPEND_U8;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "append_u16_le")) {
        *operation = R_STANDARD_CALL_BYTES_APPEND_U16_LE;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "append_u32_le")) {
        *operation = R_STANDARD_CALL_BYTES_APPEND_U32_LE;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "append_u64_le")) {
        *operation = R_STANDARD_CALL_BYTES_APPEND_U64_LE;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "equal")) {
        *operation = R_STANDARD_CALL_BYTES_EQUAL;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "compare")) {
        *operation = R_STANDARD_CALL_BYTES_COMPARE;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "copy")) {
        *operation = R_STANDARD_CALL_BYTES_COPY;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "copy_within")) {
        *operation = R_STANDARD_CALL_BYTES_COPY_WITHIN;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "fill")) {
        *operation = R_STANDARD_CALL_BYTES_FILL;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "find")) {
        *operation = R_STANDARD_CALL_BYTES_FIND;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "find_slice")) {
        *operation = R_STANDARD_CALL_BYTES_FIND_SLICE;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "starts_with")) {
        *operation = R_STANDARD_CALL_BYTES_STARTS_WITH;
    } else if (r_semantic_token_text_equal_owned(context, &components[2], "ends_with")) {
        *operation = R_STANDARD_CALL_BYTES_ENDS_WITH;
    } else {
        return false;
    }
    if (operation_span != NULL) {
        *operation_span = components[2].span;
    }
    return true;
}

