static bool r_body_standard_module_operation_name(const RFrontendContext *context,
                                                  RAstRef qualified,
                                                  const char *module,
                                                  RAstTokenView *operation_name) {
    RAstNodeView view;
    RAstTokenView components[3];
    uint32_t child_index;
    uint32_t component_count = UINT32_C(0);

    if ((module == NULL) || (operation_name == NULL) ||
        !r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return false;
    }
    (void)memset(components, 0, sizeof(components));
    for (child_index = UINT32_C(0); child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;

        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token)) {
            continue;
        }
        if (component_count >= UINT32_C(3)) {
            return false;
        }
        components[component_count] = token;
        component_count += UINT32_C(1);
    }
    if ((component_count != UINT32_C(3)) ||
        !r_semantic_token_text_equal_owned(context, &components[0], "std") ||
        !r_semantic_token_text_equal_owned(context, &components[1], module)) {
        return false;
    }
    *operation_name = components[2];
    return true;
}

static bool r_body_standard_hash_operation(const RFrontendContext *context,
                                           RAstRef qualified,
                                           RStandardCallOperation *operation,
                                           RSourceSpan *operation_span) {
    RAstTokenView name;

    if ((operation == NULL) ||
        !r_body_standard_module_operation_name(context, qualified, "hash", &name)) {
        return false;
    }
    if (r_semantic_token_text_equal_owned(context, &name, "crc32")) {
        *operation = R_STANDARD_CALL_HASH_CRC32;
    } else if (r_semantic_token_text_equal_owned(context, &name, "md5")) {
        *operation = R_STANDARD_CALL_HASH_MD5;
    } else if (r_semantic_token_text_equal_owned(context, &name, "sha1")) {
        *operation = R_STANDARD_CALL_HASH_SHA1;
    } else if (r_semantic_token_text_equal_owned(context, &name, "sha256")) {
        *operation = R_STANDARD_CALL_HASH_SHA256;
    } else if (r_semantic_token_text_equal_owned(context, &name, "sha512")) {
        *operation = R_STANDARD_CALL_HASH_SHA512;
    } else {
        return false;
    }
    if (operation_span != NULL) {
        *operation_span = name.span;
    }
    return true;
}

