static bool r_semantic_prepare_alloc_new_error_schema(RFrontendContext *context,
                                                      RTypeId type_id,
                                                      RTypeId *error_type) {
    const RSemanticType *type = r_semantic_type(context, r_semantic_value_type(context, type_id));
    RTypeId reason;
    RTypeId value_type;
    RTypeId arguments[1];
    RTypeVector argument_types;
    RStandardSchemaField fields[2];
    uint32_t base_name;
    uint32_t instance_name;
    const char *instance_bytes;

    if ((type == NULL) ||
        !r_semantic_standard_type_name_equal(context, type, "std.alloc::new_error") ||
        (type->base == R_TYPE_ID_INVALID) || (type->second != R_TYPE_ID_INVALID)) {
        return false;
    }
    value_type = type->base;
    if (!r_intern_bytes(context,
                        (const uint8_t *)"std.alloc::new_error",
                        strlen("std.alloc::new_error"),
                        &base_name) ||
        !r_semantic_intern_named_standard_type(context, "std.alloc::alloc_error", &reason)) {
        return false;
    }
    arguments[0] = value_type;
    argument_types = (RTypeVector){arguments, UINT32_C(1), UINT32_C(1)};
    if (!r_generic_instance_name(context, base_name, &argument_types, &instance_name)) {
        return false;
    }
    fields[0] = (RStandardSchemaField){"reason", reason};
    fields[1] = (RStandardSchemaField){"value", value_type};
    instance_bytes = context->intern_entries[instance_name - 1U].bytes;
    *error_type = r_semantic_value_type(context, type_id);
    return r_semantic_ensure_hidden_schema_struct(context,
                                                  instance_bytes,
                                                  *error_type,
                                                  fields,
                                                  UINT32_C(2),
                                                  r_semantic_type_is_copy(context, value_type),
                                                  error_type);
}

