/* The fieldless enums of std.fs, with their variants in the order of their C values. */
static bool
r_semantic_fs_enum_variants(const char *name, const char *const **variants, uint32_t *count) {
    static const char *const seek_variants[] = {"start", "current", "end"};
    static const char *const kind_variants[] = {"regular",
                                                "directory",
                                                "symlink",
                                                "character_device",
                                                "block_device",
                                                "fifo",
                                                "socket",
                                                "other"};
    static const char *const sync_variants[] = {"barrier", "device", "media"};
    static const char *const lock_variants[] = {"shared", "exclusive"};
    const char *const *found = NULL;
    uint32_t found_count = 0U;
    if (strcmp(name, "std.fs::seek_origin") == 0) {
        found = seek_variants;
        found_count = 3U;
    } else if (strcmp(name, "std.fs::file_kind") == 0) {
        found = kind_variants;
        found_count = 8U;
    } else if (strcmp(name, "std.fs::sync_level") == 0) {
        found = sync_variants;
        found_count = 3U;
    } else if (strcmp(name, "std.fs::lock_kind") == 0) {
        found = lock_variants;
        found_count = 2U;
    } else {
        return false;
    }
    if (variants != NULL)
        *variants = found;
    if (count != NULL)
        *count = found_count;
    return true;
}

static bool r_semantic_prepare_fs_enum_schema(RFrontendContext *context,
                                              const char *name,
                                              const RSemanticAggregate **aggregate) {
    const char *const *variants;
    uint32_t count;
    RTypeId type;
    return r_semantic_fs_enum_variants(name, &variants, &count) &&
           r_semantic_intern_named_standard_type(context, name, &type) &&
           r_semantic_ensure_hidden_schema_enum(context, name, type, variants, count, aggregate);
}

