static bool r_semantic_prepare_container_error_payload(RFrontendContext *context,
                                                       const char *payload_name,
                                                       RTypeId key,
                                                       RTypeId value,
                                                       RTypeId *result) {
    RTypeId reason;
    RStandardSchemaField fields[3];
    uint32_t base_name, name;
    const char *instance_bytes;
    RTypeId arguments[2] = {key, value};
    const uint32_t argument_count = value == R_TYPE_ID_INVALID ? UINT32_C(1) : UINT32_C(2);
    RTypeVector args = {arguments, argument_count, argument_count};
    if (!r_intern_bytes(context, (const uint8_t *)payload_name, strlen(payload_name), &base_name) ||
        !r_generic_instance_name(context, base_name, &args, &name) ||
        !r_semantic_intern_named_standard_type(context, "std.alloc::alloc_error", &reason)) {
        return false;
    }
    fields[0] = (RStandardSchemaField){"reason", reason};
    fields[1] = (RStandardSchemaField){value == R_TYPE_ID_INVALID ? "value" : "key", key};
    if (value != R_TYPE_ID_INVALID) {
        fields[2] = (RStandardSchemaField){"value", value};
    }
    instance_bytes = context->intern_entries[name - 1U].bytes;
    /* Interned names have a trailing NUL and stable separately allocated bytes. */
    if (!r_semantic_ensure_hidden_schema_struct(
            context,
            instance_bytes,
            0U,
            fields,
            value == R_TYPE_ID_INVALID ? UINT32_C(2) : UINT32_C(3),
            r_semantic_type_is_copy(context, key) &&
                ((value == R_TYPE_ID_INVALID) || r_semantic_type_is_copy(context, value)),
            result)) {
        return false;
    }
    context->semantic_aggregates[r_semantic_type(context, *result)->base - 1U]
        .standard_payload_element = key;
    return true;
}

