static bool r_semantic_prepare_host_enum(RFrontendContext *context,
                                         const char *name,
                                         const RSemanticAggregate **aggregate) {
    static const char *const errors[] = {"invalid_command",
                                         "invalid_argument",
                                         "not_found",
                                         "permission_denied",
                                         "resource_exhausted",
                                         "spawn_failed",
                                         "not_running",
                                         "cancelled",
                                         "timed_out",
                                         "unsupported",
                                         "other"};
    static const char *const pipes[] = {"inherit", "null_device", "piped"};
    static const char *const reasons[] = {"exited", "signalled", "other"};
    static const char *const env_errors[] = {"invalid_name",
                                             "invalid_value",
                                             "allocation_failed",
                                             "permission_denied",
                                             "resource_exhausted",
                                             "other"};
    const char *const *variants;
    uint32_t count;
    RTypeId type;
    if (strcmp(name, "std.process::error_code") == 0) {
        variants = errors;
        count = 11U;
    } else if (strcmp(name, "std.process::pipe_mode") == 0) {
        variants = pipes;
        count = 3U;
    } else if (strcmp(name, "std.process::termination_kind") == 0) {
        variants = reasons;
        count = 3U;
    } else if (strcmp(name, "std.env::error_code") == 0) {
        variants = env_errors;
        count = 6U;
    } else {
        return false;
    }
    return r_semantic_intern_named_standard_type(context, name, &type) &&
           r_semantic_ensure_hidden_schema_enum(context, name, type, variants, count, aggregate);
}

static bool r_semantic_prepare_numeric_enum(RFrontendContext *context,
                                            const char *name,
                                            const RSemanticAggregate **aggregate) {
    static const char *const time_codes[] = {
        "invalid_value", "overflow", "unavailable", "cancelled", "other"};
    static const char *const duration_codes[] = {"invalid_nanoseconds", "overflow"};
    static const char *const math_codes[] = {"domain", "pole", "overflow", "underflow"};
    const char *const *variants;
    uint32_t count;
    RTypeId type;
    if (strcmp(name, "std.time::error_code") == 0) {
        variants = time_codes;
        count = UINT32_C(5);
    } else if (strcmp(name, "std.time::duration_error") == 0) {
        variants = duration_codes;
        count = UINT32_C(2);
    } else if (strcmp(name, "std.math::error_code") == 0) {
        variants = math_codes;
        count = UINT32_C(4);
    } else {
        return false;
    }
    return r_semantic_intern_named_standard_type(context, name, &type) &&
           r_semantic_ensure_hidden_schema_enum(context, name, type, variants, count, aggregate);
}

/* R-REFL-0001, R-STMT-0006: the fieldless enums that the standard library implements natively.
   Each is described by a hidden schema whose variants follow declaration order from zero, as
   the C enumerations of the library headers do. A name of any other type leaves no schema. */
static bool r_semantic_prepare_standard_enum_named(RFrontendContext *context,
                                                   const char *name,
                                                   const RSemanticAggregate **aggregate) {
    static const char *const alloc_errors[] = {
        "out_of_memory", "size_overflow", "unsupported_alignment", "budget_exhausted"};
    static const char *const start_errors[] = {
        "allocation_failed", "runtime_stopping", "scope_full", "budget_exhausted"};
    static const char *const bytes_errors[] = {"out_of_bounds", "range_overflow"};
    static const char *const thread_errors[] = {
        "unavailable", "resource_exhausted", "permission_denied"};
    static const char *const barrier_errors[] = {"zero_participants"};
    static const char *const boundary_errors[] = {"out_of_bounds", "not_scalar_boundary"};
    static const char *const signal_kinds[] = {
        "terminate", "interrupt", "hangup", "user1", "user2"};
    static const struct {
        const char *name;
        const char *const *variants;
        uint32_t count;
    } error_enums[] = {
        {"std.alloc::alloc_error", alloc_errors, 4U},
        {"std.async::start_error", start_errors, 4U},
        {"std.bytes::bytes_error", bytes_errors, 2U},
        {"std.thread::thread_error", thread_errors, 3U},
        {"std.sync::barrier_error", barrier_errors, 1U},
        {"std.string::boundary_error", boundary_errors, 2U},
        {"std.signal::kind", signal_kinds, 5U},
    };
    static const char *const host_enums[] = {"std.process::error_code",
                                             "std.process::pipe_mode",
                                             "std.process::termination_kind",
                                             "std.env::error_code"};
    static const char *const numeric_enums[] = {
        "std.time::error_code", "std.time::duration_error", "std.math::error_code"};
    static const char *const json_enums[] = {
        "std.json::error_code", "std.json::value_kind", "std.json::mode", "std.json::feed_state"};
    static const char *const net_enums[] = {
        "std.net::family", "std.net::shutdown_direction", "std.net::error_code"};
    size_t index;
    RTypeId type;

    *aggregate = NULL;
    for (index = 0U; index < sizeof(error_enums) / sizeof(error_enums[0]); ++index) {
        if (strcmp(name, error_enums[index].name) == 0) {
            return r_semantic_intern_named_standard_type(context, name, &type) &&
                   r_semantic_ensure_hidden_schema_enum(context,
                                                        name,
                                                        type,
                                                        error_enums[index].variants,
                                                        error_enums[index].count,
                                                        aggregate);
        }
    }
    for (index = 0U; index < sizeof(host_enums) / sizeof(host_enums[0]); ++index) {
        if (strcmp(name, host_enums[index]) == 0) {
            return r_semantic_prepare_host_enum(context, name, aggregate);
        }
    }
    for (index = 0U; index < sizeof(numeric_enums) / sizeof(numeric_enums[0]); ++index) {
        if (strcmp(name, numeric_enums[index]) == 0) {
            return r_semantic_prepare_numeric_enum(context, name, aggregate);
        }
    }
    for (index = 0U; index < sizeof(json_enums) / sizeof(json_enums[0]); ++index) {
        if (strcmp(name, json_enums[index]) == 0) {
            return r_semantic_prepare_json_enum(context, name, aggregate);
        }
    }
    for (index = 0U; index < sizeof(net_enums) / sizeof(net_enums[0]); ++index) {
        if (strcmp(name, net_enums[index]) == 0) {
            return r_semantic_prepare_net_enum(context, name, aggregate);
        }
    }
    if (strcmp(name, "core::memory_order") == 0) {
        return r_semantic_prepare_core_memory_order_schema(context, aggregate);
    }
    if (strcmp(name, "std.bits::read_error_code") == 0) {
        return r_semantic_prepare_bits_read_error_code_schema(context, aggregate);
    }
    if (strcmp(name, "std.convert::parse_error_code") == 0) {
        return r_semantic_prepare_convert_parse_error_code_schema(context, aggregate);
    }
    if (strcmp(name, "std.convert::range_error") == 0) {
        return r_semantic_prepare_convert_range_error_schema(context, aggregate);
    }
    if (strcmp(name, "std.net::address_error_code") == 0) {
        return r_semantic_prepare_net_address_error_code_schema(context, aggregate);
    }
    if (strcmp(name, "std.io::error_code") == 0) {
        return r_semantic_prepare_io_error_code_schema(context, aggregate);
    }
    if (strcmp(name, "std.error::domain") == 0) {
        return r_semantic_prepare_error_domain_schema(context, aggregate);
    }
    if (strcmp(name, "std.fs::error_code") == 0) {
        return r_semantic_prepare_fs_error_code_schema(context, aggregate);
    }
    if (r_semantic_fs_enum_variants(name, NULL, NULL)) {
        return r_semantic_prepare_fs_enum_schema(context, name, aggregate);
    }
    if (strcmp(name, "std.fs::access") == 0) {
        return r_semantic_prepare_fs_access_schema(context, aggregate);
    }
    if (strcmp(name, "std.fs::create_mode") == 0) {
        return r_semantic_prepare_fs_create_mode_schema(context, aggregate);
    }
    return true;
}

/* The schema of a standard type that is a natively implemented fieldless enum, or none. */
static bool r_semantic_prepare_standard_enum(RFrontendContext *context,
                                             RTypeId type_id,
                                             const RSemanticAggregate **aggregate) {
    const RSemanticType *type = r_semantic_type(context, r_semantic_value_type(context, type_id));
    const RInternEntry *entry;
    char name[64];

    *aggregate = NULL;
    if ((type == NULL) || (type->kind != R_SEMANTIC_TYPE_STANDARD) ||
        (type->length == UINT64_C(0)) || (type->length > (uint64_t)context->intern_count)) {
        return true;
    }
    entry = &context->intern_entries[(size_t)type->length - 1U];
    if (entry->length >= sizeof(name)) {
        return true;
    }
    (void)memcpy(name, entry->bytes, entry->length);
    name[entry->length] = '\0';
    return r_semantic_prepare_standard_enum_named(context, name, aggregate);
}

static bool r_semantic_prepare_standard_outcome(RFrontendContext *context,
                                                RTypeId type_id,
                                                const RStandardOutcomeSchema **schema,
                                                RTypeId payload_types[4]) {
    const RSemanticType *type = r_semantic_type(context, type_id);
    size_t schema_index;
    RTypeId byte_type;
    RTypeId buffer_type;
    RTypeId shared_buffer_type = R_TYPE_ID_INVALID;
    RTypeId error_type = R_TYPE_ID_INVALID;
    RTypeId count_type;
    RStandardSchemaField fields[3];
    uint32_t field_count;

    if ((schema == NULL) || (payload_types == NULL)) {
        return false;
    }
    *schema = NULL;
    payload_types[0] = R_TYPE_ID_INVALID;
    payload_types[1] = R_TYPE_ID_INVALID;
    payload_types[2] = R_TYPE_ID_INVALID;
    payload_types[3] = R_TYPE_ID_INVALID;
    if (type != NULL && type->base != R_TYPE_ID_INVALID && type->second == R_TYPE_ID_INVALID &&
        r_semantic_standard_type_name_equal(context, type, "std.async::broadcast_result")) {
        RTypeId void_type;
        *schema = &r_async_broadcast_outcome_schema;
        payload_types[0] = type->base;
        if (!r_semantic_type_from_token(context, R_TOKEN_KW_U64, &payload_types[1]) ||
            !r_semantic_type_from_token(context, R_TOKEN_KW_VOID, &void_type)) {
            return false;
        }
        payload_types[2] = void_type;
        return true;
    }
    if (type != NULL && type->base != R_TYPE_ID_INVALID && type->second == R_TYPE_ID_INVALID &&
        r_semantic_standard_type_name_equal(context, type, "std.thread::join_result")) {
        const bool is_void = r_semantic_type(context, type->base)->kind == R_SEMANTIC_TYPE_VOID;
        *schema = &r_thread_join_outcome_schemas[is_void ? 1U : 0U];
        payload_types[0] = type->base;
        return r_semantic_intern_named_standard_type(
            context, "std.thread::panic_report", &payload_types[1]);
    }
    if (r_semantic_sync_outcome(context, type) != NULL) {
        const RStandardSyncOutcome *sync = r_semantic_sync_outcome(context, type);
        size_t index;
        RTypeId void_type;
        RTypeId payload = type->base;
        if (sync->guard != NULL && !r_semantic_intern_parametric_standard_type(
                                       context, sync->guard, payload, R_TYPE_ID_INVALID, &payload))
            return false;
        if (!r_semantic_type_from_token(context, R_TOKEN_KW_VOID, &void_type))
            return false;
        for (index = 0U; r_standard_sync_outcome_at(index) != sync; ++index) {
        }
        *schema = &r_standard_sync_outcome_schemas[index];
        for (index = 0U; index < sync->variant_count; ++index)
            payload_types[index] =
                (sync->payload_mask & (UINT32_C(1) << index)) != 0U ? payload : void_type;
        return true;
    }
    if ((type != NULL) && (type->base != R_TYPE_ID_INVALID) &&
        r_semantic_standard_type_name_equal(
            context, type, "core::atomic_compare_exchange_result")) {
        *schema = &r_standard_outcome_schemas[0];
        payload_types[0] = type->base;
        payload_types[1] = type->base;
        return type->second == R_TYPE_ID_INVALID;
    }
    if ((type != NULL) && (type->base != R_TYPE_ID_INVALID) &&
        (type->second == R_TYPE_ID_INVALID) &&
        (r_semantic_standard_type_name_equal(context, type, "std.arc::try_unwrap_result") ||
         r_semantic_standard_type_name_equal(context, type, "std.rc::try_unwrap_result"))) {
        const bool is_arc =
            r_semantic_standard_type_name_equal(context, type, "std.arc::try_unwrap_result");
        const size_t schema_count =
            sizeof(r_standard_outcome_schemas) / sizeof(r_standard_outcome_schemas[0]);

        *schema = &r_standard_outcome_schemas[schema_count - (is_arc ? 2U : 1U)];
        payload_types[0] = type->base;
        return r_semantic_intern_derived_type(context,
                                              is_arc ? R_SEMANTIC_TYPE_ARC : R_SEMANTIC_TYPE_RC,
                                              type->base,
                                              R_TYPE_ID_INVALID,
                                              UINT64_C(0),
                                              R_SEMANTIC_TYPE_FLAG_NONE,
                                              &payload_types[1]);
    }
    if ((type != NULL) && (type->base != R_TYPE_ID_INVALID) &&
        (r_semantic_standard_type_name_equal(context, type, "std.array::push_error") ||
         r_semantic_standard_type_name_equal(context, type, "std.list::push_error") ||
         r_semantic_standard_type_name_equal(context, type, "std.dict::insert_error"))) {
        const bool list =
            r_semantic_standard_type_name_equal(context, type, "std.list::push_error");
        const bool dict =
            r_semantic_standard_type_name_equal(context, type, "std.dict::insert_error");
        const size_t index = dict ? 3U : (list ? 2U : 1U);
        *schema = &r_standard_outcome_schemas[index];
        return r_semantic_prepare_container_error_payload(
            context,
            r_standard_outcome_schemas[index].payload_names[0],
            type->base,
            dict ? type->second : R_TYPE_ID_INVALID,
            &payload_types[0]);
    }
    if ((type == NULL) || (type->kind != R_SEMANTIC_TYPE_STANDARD) ||
        (type->base != R_TYPE_ID_INVALID) || (type->second != R_TYPE_ID_INVALID) ||
        (type->flags != R_SEMANTIC_TYPE_FLAG_NONE)) {
        return true;
    }
    for (schema_index = 0U; schema_index < (sizeof(r_standard_outcome_schemas) /
                                            sizeof(r_standard_outcome_schemas[0]));
         ++schema_index) {
        if (r_semantic_standard_type_name_equal(
                context, type, r_standard_outcome_schemas[schema_index].type_name)) {
            break;
        }
    }
    if (schema_index ==
        (sizeof(r_standard_outcome_schemas) / sizeof(r_standard_outcome_schemas[0]))) {
        return true;
    }
    if (!r_semantic_type_from_token(context, R_TOKEN_KW_U8, &byte_type) ||
        !r_semantic_intern_type(context, R_SEMANTIC_TYPE_ARRAY, byte_type, &buffer_type)) {
        return false;
    }
    if (r_standard_outcome_schemas[schema_index].kind == R_STANDARD_OUTCOME_STRING_FROM_BYTES) {
        const RStandardOutcomeSchema *string = &r_standard_outcome_schemas[schema_index];
        if (!r_semantic_intern_named_standard_type(
                context, "std.string::string", &payload_types[0]) ||
            !r_semantic_type_from_token(context, R_TOKEN_KW_USIZE, &count_type))
            return false;
        fields[0] = (RStandardSchemaField){"bytes", buffer_type};
        fields[1] = (RStandardSchemaField){"index", count_type};
        if (!r_semantic_ensure_hidden_schema_struct(context,
                                                    string->payload_names[1],
                                                    R_TYPE_ID_INVALID,
                                                    fields,
                                                    2U,
                                                    false,
                                                    &payload_types[1]))
            return false;
        *schema = string;
        return true;
    }
    if (r_standard_outcome_schemas[schema_index].kind == R_STANDARD_OUTCOME_PROCESS) {
        const RStandardOutcomeSchema *process = &r_standard_outcome_schemas[schema_index];
        const bool spawn = strcmp(process->type_name, "std.process::spawn_result") == 0;
        RTypeId owner;
        if (!r_semantic_intern_named_standard_type(
                context, "std.process::process_error", &error_type) ||
            !r_semantic_prepare_host_schema(context, error_type) ||
            !r_semantic_intern_named_standard_type(context,
                                                   spawn ? "std.process::child"
                                                         : "std.process::exit_status",
                                                   &payload_types[0]) ||
            !r_semantic_prepare_host_schema(context, payload_types[0]) ||
            !r_semantic_intern_named_standard_type(
                context, spawn ? "std.process::command" : "std.process::child", &owner))
            return false;
        fields[0] = (RStandardSchemaField){"error", error_type};
        fields[1] = (RStandardSchemaField){spawn ? "command" : "child", owner};
        if (!r_semantic_ensure_hidden_schema_struct(context,
                                                    process->payload_names[1],
                                                    R_TYPE_ID_INVALID,
                                                    fields,
                                                    2U,
                                                    false,
                                                    &payload_types[1]))
            return false;
        *schema = process;
        return true;
    }
    if (r_standard_outcome_schemas[schema_index].kind == R_STANDARD_OUTCOME_NET) {
        *schema = &r_standard_outcome_schemas[schema_index];
        return r_semantic_prepare_net_outcome(context, (*schema)->type_name, payload_types);
    }
    if (r_standard_outcome_schemas[schema_index].kind == R_STANDARD_OUTCOME_FS_DIRECTORY_NEXT) {
        RTypeId iterator, entry, path, kind;
        const RSemanticAggregate *kind_schema;
        if (!r_semantic_intern_named_standard_type(context, "std.fs::directory_iter", &iterator) ||
            !r_semantic_intern_named_standard_type(context, "std.fs::directory_entry", &entry) ||
            !r_semantic_intern_named_standard_type(context, "std.fs::path", &path) ||
            !r_semantic_prepare_fs_enum_schema(context, "std.fs::file_kind", &kind_schema))
            return false;
        /* The error schema may grow the aggregate table that kind_schema points into. */
        kind = kind_schema->type;
        if (!r_semantic_prepare_fs_error_schema(context, &error_type) ||
            !r_semantic_type_from_token(context, R_TOKEN_KW_VOID, &payload_types[1]))
            return false;
        fields[0] = (RStandardSchemaField){"name", path};
        fields[1] = (RStandardSchemaField){"kind", kind};
        if (!r_semantic_ensure_hidden_schema_struct(
                context, "std.fs::directory_entry", entry, fields, 2U, false, &entry))
            return false;
        fields[0] = (RStandardSchemaField){"iterator", iterator};
        fields[1] = (RStandardSchemaField){"entry", entry};
        if (!r_semantic_ensure_hidden_schema_struct(
                context,
                r_standard_outcome_schemas[schema_index].payload_names[0],
                R_TYPE_ID_INVALID,
                fields,
                2U,
                false,
                &payload_types[0]))
            return false;
        fields[0] = (RStandardSchemaField){"error", error_type};
        fields[1] = (RStandardSchemaField){"iterator", iterator};
        if (!r_semantic_ensure_hidden_schema_struct(
                context,
                r_standard_outcome_schemas[schema_index].payload_names[2],
                R_TYPE_ID_INVALID,
                fields,
                2U,
                false,
                &payload_types[2]))
            return false;
    } else if (r_standard_outcome_schemas[schema_index].kind == R_STANDARD_OUTCOME_IO_READ) {
        if (!r_semantic_prepare_io_error_schema(context, &error_type) ||
            !r_semantic_type_from_token(context, R_TOKEN_KW_USIZE, &count_type)) {
            return false;
        }
        fields[0] = (RStandardSchemaField){"buffer", buffer_type};
        fields[1] = (RStandardSchemaField){"count", count_type};
        if (!r_semantic_ensure_hidden_schema_struct(
                context,
                r_standard_outcome_schemas[schema_index].payload_names[0],
                R_TYPE_ID_INVALID,
                fields,
                UINT32_C(2),
                false,
                &payload_types[0])) {
            return false;
        }
        payload_types[1] = buffer_type;
        fields[0] = (RStandardSchemaField){"error", error_type};
        fields[1] = (RStandardSchemaField){"count", count_type};
        fields[2] = (RStandardSchemaField){"buffer", buffer_type};
        field_count = UINT32_C(3);
        if (!r_semantic_ensure_hidden_schema_struct(
                context,
                r_standard_outcome_schemas[schema_index].payload_names[2],
                R_TYPE_ID_INVALID,
                fields,
                field_count,
                false,
                &payload_types[2])) {
            return false;
        }
    } else if (r_standard_outcome_schemas[schema_index].kind == R_STANDARD_OUTCOME_IO_WRITE) {
        if (!r_semantic_prepare_io_error_schema(context, &error_type) ||
            !r_semantic_type_from_token(context, R_TOKEN_KW_USIZE, &count_type)) {
            return false;
        }
        fields[0] = (RStandardSchemaField){"buffer", buffer_type};
        fields[1] = (RStandardSchemaField){"count", count_type};
        if (!r_semantic_ensure_hidden_schema_struct(
                context,
                r_standard_outcome_schemas[schema_index].payload_names[0],
                R_TYPE_ID_INVALID,
                fields,
                UINT32_C(2),
                false,
                &payload_types[0])) {
            return false;
        }
        fields[0] = (RStandardSchemaField){"error", error_type};
        fields[1] = (RStandardSchemaField){"written", count_type};
        fields[2] = (RStandardSchemaField){"buffer", buffer_type};
        if (!r_semantic_ensure_hidden_schema_struct(
                context,
                r_standard_outcome_schemas[schema_index].payload_names[1],
                R_TYPE_ID_INVALID,
                fields,
                UINT32_C(3),
                false,
                &payload_types[1])) {
            return false;
        }
    } else if (r_standard_outcome_schemas[schema_index].kind == R_STANDARD_OUTCOME_IO_WRITE_ALL) {
        if (!r_semantic_prepare_io_error_schema(context, &error_type) ||
            !r_semantic_type_from_token(context, R_TOKEN_KW_USIZE, &count_type)) {
            return false;
        }
        payload_types[0] = buffer_type;
        fields[0] = (RStandardSchemaField){"error", error_type};
        fields[1] = (RStandardSchemaField){"written", count_type};
        fields[2] = (RStandardSchemaField){"buffer", buffer_type};
        field_count = UINT32_C(3);
        if (!r_semantic_ensure_hidden_schema_struct(
                context,
                r_standard_outcome_schemas[schema_index].payload_names[1],
                R_TYPE_ID_INVALID,
                fields,
                field_count,
                false,
                &payload_types[1])) {
            return false;
        }
    } else if (r_standard_outcome_schemas[schema_index].kind ==
               R_STANDARD_OUTCOME_IO_WRITE_SHARED) {
        if (!r_semantic_intern_derived_type(context,
                                            R_SEMANTIC_TYPE_ARC,
                                            buffer_type,
                                            R_TYPE_ID_INVALID,
                                            UINT64_C(0),
                                            R_SEMANTIC_TYPE_FLAG_NONE,
                                            &shared_buffer_type) ||
            !r_semantic_prepare_io_error_schema(context, &error_type) ||
            !r_semantic_type_from_token(context, R_TOKEN_KW_USIZE, &count_type)) {
            return false;
        }
        payload_types[0] = shared_buffer_type;
        fields[0] = (RStandardSchemaField){"error", error_type};
        fields[1] = (RStandardSchemaField){"written", count_type};
        fields[2] = (RStandardSchemaField){"buffer", shared_buffer_type};
        if (!r_semantic_ensure_hidden_schema_struct(
                context,
                r_standard_outcome_schemas[schema_index].payload_names[1],
                R_TYPE_ID_INVALID,
                fields,
                UINT32_C(3),
                false,
                &payload_types[1])) {
            return false;
        }
    } else {
        if (!r_semantic_prepare_fs_error_schema(context, &error_type)) {
            return false;
        }
        payload_types[0] = buffer_type;
        fields[0] = (RStandardSchemaField){"error", error_type};
        fields[1] = (RStandardSchemaField){"data", buffer_type};
        field_count = UINT32_C(2);
        if (!r_semantic_ensure_hidden_schema_struct(
                context,
                r_standard_outcome_schemas[schema_index].payload_names[1],
                R_TYPE_ID_INVALID,
                fields,
                field_count,
                false,
                &payload_types[1])) {
            return false;
        }
    }
    *schema = &r_standard_outcome_schemas[schema_index];
    return true;
}

static bool r_semantic_checked_async_types(RFrontendContext *context,
                                           RTypeId logical_return_type,
                                           RTypeId completion_effects,
                                           RTypeId *task_type,
                                           RTypeId *start_type) {
    RTypeId start_error;
    RTypeId start_effects;
    RTypeVector errors = {0};
    bool duplicate;
    bool success = false;

    if ((logical_return_type == R_TYPE_ID_INVALID) || (task_type == NULL) || (start_type == NULL) ||
        !r_semantic_intern_derived_type(context,
                                        R_SEMANTIC_TYPE_TASK,
                                        logical_return_type,
                                        completion_effects,
                                        UINT64_C(0),
                                        R_SEMANTIC_TYPE_FLAG_NONE,
                                        task_type) ||
        !r_semantic_intern_named_standard_type(context, "std.async::start_error", &start_error) ||
        !r_type_vector_push(context, &errors, start_error) ||
        !r_semantic_intern_effect_set(context, &errors, &start_effects, &duplicate) || duplicate ||
        !r_semantic_intern_effect_carrier(context, *task_type, start_effects, start_type)) {
        goto cleanup;
    }
    success = true;

cleanup:
    r_context_free(context, errors.items);
    return success;
}

static bool r_body_standard_checked_operation(const RFrontendContext *context,
                                              RAstRef qualified,
                                              RStandardCallOperation *operation,
                                              RTokenKind *destination_token,
                                              uint64_t *destination_tag,
                                              RSourceSpan *operation_span,
                                              bool *valid_destination) {
    RAstNodeView view;
    RAstTokenView components[3];
    uint32_t component_count = UINT32_C(0);
    uint32_t child_index;
    size_t destination_index;

    if ((operation == NULL) || (destination_token == NULL) || (destination_tag == NULL) ||
        (valid_destination == NULL) ||
        !r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return false;
    }
    *operation = R_STANDARD_CALL_INVALID;
    *destination_token = R_TOKEN_INVALID;
    *destination_tag = UINT64_MAX;
    *valid_destination = false;
    (void)memset(components, 0, sizeof(components));
    for (child_index = 0U; child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;

        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token)) {
            continue;
        }
        if (component_count >= UINT32_C(3)) {
            return false;
        }
        components[component_count] = token;
        component_count += UINT32_C(1);
    }
    if ((component_count != UINT32_C(3)) ||
        !r_semantic_token_text_equal_owned(context, &components[0], "std") ||
        !r_semantic_token_text_starts_with_owned(context, &components[2], "checked_")) {
        return false;
    }
    if (r_semantic_token_text_equal_owned(context, &components[1], "convert")) {
        *operation = R_STANDARD_CALL_CONVERT_CHECKED;
    } else if (r_semantic_token_text_equal_owned(context, &components[1], "c")) {
        *operation = R_STANDARD_CALL_C_CHECKED;
    } else {
        return false;
    }
    if (operation_span != NULL) {
        *operation_span = components[2].span;
    }
    for (destination_index = 0U; destination_index < (sizeof(r_checked_numeric_destinations) /
                                                      sizeof(r_checked_numeric_destinations[0]));
         ++destination_index) {
        if (!r_semantic_token_text_equal_owned(
                context,
                &components[2],
                r_checked_numeric_destinations[destination_index].operation_name)) {
            continue;
        }
        *destination_token = r_checked_numeric_destinations[destination_index].token_kind;
        *destination_tag = (uint64_t)destination_index;
        *valid_destination =
            (*operation == R_STANDARD_CALL_CONVERT_CHECKED) || (destination_index >= UINT32_C(12));
        return true;
    }
    return true;
}

static const char *r_body_standard_checked_rule(RStandardCallOperation operation) {
    return operation == R_STANDARD_CALL_C_CHECKED ? "R-SLIB-C-0001" : "R-SLIB-CONV-0004";
}

static bool r_body_standard_parse_operation(const RFrontendContext *context,
                                            RAstRef qualified,
                                            RTokenKind *destination_token,
                                            uint64_t *destination_tag,
                                            RSourceSpan *operation_span) {
    RAstNodeView view;
    RAstTokenView components[3];
    uint32_t component_count = UINT32_C(0);
    uint32_t child_index;
    size_t destination_index;

    if ((destination_token == NULL) || (destination_tag == NULL) ||
        !r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return false;
    }
    *destination_token = R_TOKEN_INVALID;
    *destination_tag = UINT64_MAX;
    (void)memset(components, 0, sizeof(components));
    for (child_index = UINT32_C(0); child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;

        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token)) {
            continue;
        }
        if (component_count >= UINT32_C(3)) {
            return false;
        }
        components[component_count++] = token;
    }
    if ((component_count != UINT32_C(3)) ||
        !r_semantic_token_text_equal_owned(context, &components[0], "std") ||
        !r_semantic_token_text_equal_owned(context, &components[1], "convert") ||
        !r_semantic_token_text_starts_with_owned(context, &components[2], "parse_")) {
        return false;
    }
    if (operation_span != NULL) {
        *operation_span = components[2].span;
    }
    for (destination_index = UINT32_C(0);
         destination_index <
         (sizeof(r_checked_numeric_destinations) / sizeof(r_checked_numeric_destinations[0]));
         ++destination_index) {
        char operation_name[48];
        int length = snprintf(operation_name,
                              sizeof(operation_name),
                              "parse_%s",
                              r_checked_numeric_destinations[destination_index].operation_name +
                                  (sizeof("checked_") - 1U));

        if ((length < 0) || ((size_t)length >= sizeof(operation_name))) {
            return false;
        }
        if (r_semantic_token_text_equal_owned(context, &components[2], operation_name)) {
            *destination_token = r_checked_numeric_destinations[destination_index].token_kind;
            *destination_tag = (uint64_t)destination_index;
            return true;
        }
    }
    return true;
}

static bool r_body_standard_format_integer_operation(const RFrontendContext *context,
                                                     RAstRef qualified,
                                                     RTokenKind *value_token,
                                                     uint64_t *value_tag,
                                                     RSourceSpan *operation_span) {
    RAstNodeView view;
    RAstTokenView components[3];
    uint32_t component_count = UINT32_C(0);
    uint32_t child_index;
    size_t value_index;

    if ((value_token == NULL) || (value_tag == NULL) ||
        !r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return false;
    }
    *value_token = R_TOKEN_INVALID;
    *value_tag = UINT64_MAX;
    (void)memset(components, 0, sizeof(components));
    for (child_index = UINT32_C(0); child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;

        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token)) {
            continue;
        }
        if (component_count >= UINT32_C(3)) {
            return false;
        }
        components[component_count++] = token;
    }
    if ((component_count != UINT32_C(3)) ||
        !r_semantic_token_text_equal_owned(context, &components[0], "std") ||
        !r_semantic_token_text_equal_owned(context, &components[1], "format") ||
        !r_semantic_token_text_starts_with_owned(context, &components[2], "append_")) {
        return false;
    }
    if (operation_span != NULL) {
        *operation_span = components[2].span;
    }
    for (value_index = UINT32_C(0); value_index < (sizeof(r_checked_numeric_destinations) /
                                                   sizeof(r_checked_numeric_destinations[0]));
         ++value_index) {
        char operation_name[48];
        int length;

        if ((value_index == UINT32_C(10)) || (value_index == UINT32_C(11)) ||
            (value_index == UINT32_C(38)) || (value_index == UINT32_C(39)) ||
            (value_index == UINT32_C(40))) {
            continue;
        }
        length = snprintf(operation_name,
                          sizeof(operation_name),
                          "append_%s",
                          r_checked_numeric_destinations[value_index].operation_name +
                              (sizeof("checked_") - 1U));
        if ((length < 0) || ((size_t)length >= sizeof(operation_name))) {
            return false;
        }
        if (r_semantic_token_text_equal_owned(context, &components[2], operation_name)) {
            *value_token = r_checked_numeric_destinations[value_index].token_kind;
            *value_tag = (uint64_t)value_index;
            return true;
        }
    }
    return true;
}

static bool r_body_lower_standard_format_integer_call(RBodyContext *body,
                                                      RAstRef argument_list,
                                                      const RAstNodeView *arguments_view,
                                                      RSourceSpan call_span,
                                                      RSourceSpan operation_span,
                                                      RTypeId contextual_type,
                                                      RTokenKind value_token,
                                                      uint64_t value_tag,
                                                      RExpressionResult *result) {
    RTypeId builder_type;
    RTypeId mutable_builder_type;
    RTypeId value_type;
    RTypeId radix_type;
    RTypeId void_type;
    RTypeId error_type;
    RTypeId effect_set;
    RTypeId effect_carrier;
    RExpressionResult arguments[3];
    RHirNodeId child_storage[3];
    RHirVector children = {child_storage, UINT32_C(3), UINT32_C(3)};
    uint32_t argument_index;

    r_body_expression_invalid(result);
    (void)memset(arguments, 0, sizeof(arguments));
    if (value_token == R_TOKEN_INVALID) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-SLIB-FMT-0002",
                                 "std.format integer append suffix is not available",
                                 operation_span);
    }
    if (arguments_view->child_count != UINT32_C(3)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-SLIB-FMT-0002",
                                 "integer append requires a builder, value, and radix",
                                 call_span);
    }
    if (!r_semantic_intern_named_standard_type(
            body->frontend, "std.format::builder", &builder_type) ||
        !r_semantic_intern_derived_type(body->frontend,
                                        R_SEMANTIC_TYPE_BORROW,
                                        builder_type,
                                        R_TYPE_ID_INVALID,
                                        UINT64_C(0),
                                        R_SEMANTIC_TYPE_FLAG_NONE,
                                        &mutable_builder_type) ||
        !r_semantic_type_from_token(body->frontend, value_token, &value_type) ||
        !r_semantic_type_from_token(body->frontend, R_TOKEN_KW_U32, &radix_type) ||
        !r_semantic_type_from_token(body->frontend, R_TOKEN_KW_VOID, &void_type) ||
        !r_semantic_intern_named_standard_type(
            body->frontend, "std.format::format_error", &error_type) ||
        !r_semantic_single_effect_set(body->frontend, error_type, &effect_set) ||
        !r_semantic_intern_effect_carrier(body->frontend, void_type, effect_set, &effect_carrier)) {
        return false;
    }
    if ((contextual_type != R_TYPE_ID_INVALID) &&
        (r_semantic_value_type(body->frontend, contextual_type) != void_type)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-SLIB-FMT-0002",
                                 "integer append result does not match its exact context",
                                 operation_span);
    }
    for (argument_index = UINT32_C(0); argument_index < UINT32_C(3); ++argument_index) {
        const RTypeId expected = argument_index == UINT32_C(0)   ? mutable_builder_type
                                 : argument_index == UINT32_C(1) ? value_type
                                                                 : radix_type;
        RAstRef argument;

        if (!r_ast_ref_child(body->frontend, argument_list, argument_index, &argument) ||
            !r_body_lower_value(body, argument, expected, &arguments[argument_index])) {
            return false;
        }
        if (!arguments[argument_index].valid) {
            return true;
        }
        if (arguments[argument_index].type != expected) {
            return r_body_diagnostic(body,
                                     "R-DIAG-TYPE-001",
                                     "R-SLIB-FMT-0002",
                                     "integer append argument has the wrong type",
                                     operation_span);
        }
        child_storage[argument_index] = arguments[argument_index].node;
    }
    if (!r_body_validate_effect_set(body, effect_set, operation_span) ||
        !r_body_append_standard_call(body,
                                     call_span,
                                     void_type,
                                     effect_carrier,
                                     R_STANDARD_CALL_FORMAT_APPEND_INTEGER,
                                     &children,
                                     NULL,
                                     result)) {
        return false;
    }
    r_body_hir_node(body, result->node)->integer_value = value_tag;
    return r_body_attach_effect_exits(body, result->node, effect_set, operation_span);
}

static bool r_body_lower_standard_parse_call(RBodyContext *body,
                                             RAstRef argument_list,
                                             const RAstNodeView *arguments_view,
                                             RSourceSpan call_span,
                                             RSourceSpan operation_span,
                                             RTypeId contextual_type,
                                             RTokenKind destination_token,
                                             uint64_t destination_tag,
                                             RExpressionResult *result) {
    const bool floating = (destination_tag == UINT64_C(10)) || (destination_tag == UINT64_C(11)) ||
                          (destination_tag == UINT64_C(38)) || (destination_tag == UINT64_C(39)) ||
                          (destination_tag == UINT64_C(40));
    const uint32_t expected_count = floating ? UINT32_C(1) : UINT32_C(2);
    RTypeId destination_type;
    RTypeId str_type;
    RTypeId radix_type;
    RTypeId error_type;
    RTypeId effect_set;
    RTypeId effect_carrier;
    RTypeId effect_items[1];
    RTypeVector effects = {effect_items, UINT32_C(1), UINT32_C(1)};
    bool duplicate_effect = false;
    RAstRef argument;
    RExpressionResult lowered[2];
    RHirNodeId child_storage[2];
    RHirVector children;
    RHirNodeId node_id;
    RHirNode *node;
    uint32_t index;

    r_body_expression_invalid(result);
    if (destination_token == R_TOKEN_INVALID) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 floating ? "R-SLIB-CONV-0003" : "R-SLIB-CONV-0002",
                                 "std.convert parse destination suffix is not available",
                                 operation_span);
    }
    if (arguments_view->child_count != expected_count) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 floating ? "R-SLIB-CONV-0003" : "R-SLIB-CONV-0002",
                                 floating ? "floating parse requires exactly one string argument"
                                          : "integer parse requires a string and radix",
                                 call_span);
    }
    if (!r_semantic_type_from_token(body->frontend, destination_token, &destination_type) ||
        !r_semantic_type_from_token(body->frontend, R_TOKEN_KW_STR, &str_type) ||
        !r_semantic_type_from_token(body->frontend, R_TOKEN_KW_U32, &radix_type) ||
        !r_semantic_intern_named_standard_type(
            body->frontend, "std.convert::parse_error", &error_type)) {
        return false;
    }
    effect_items[0] = error_type;
    if (!r_semantic_intern_effect_set(body->frontend, &effects, &effect_set, &duplicate_effect) ||
        duplicate_effect ||
        !r_semantic_intern_effect_carrier(
            body->frontend, destination_type, effect_set, &effect_carrier)) {
        return false;
    }
    if ((contextual_type != R_TYPE_ID_INVALID) &&
        (r_semantic_value_type(body->frontend, contextual_type) != destination_type)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 floating ? "R-SLIB-CONV-0003" : "R-SLIB-CONV-0002",
                                 "parse result does not match its exact context",
                                 operation_span);
    }
    for (index = UINT32_C(0); index < expected_count; ++index) {
        const RTypeId expected = index == UINT32_C(0) ? str_type : radix_type;

        r_body_expression_invalid(&lowered[index]);
        if (!r_ast_ref_child(body->frontend, argument_list, index, &argument) ||
            !r_body_lower_value(body, argument, expected, &lowered[index])) {
            return false;
        }
        if (!lowered[index].valid) {
            return true;
        }
        if (lowered[index].type != expected) {
            return r_body_diagnostic(body,
                                     "R-DIAG-TYPE-001",
                                     floating ? "R-SLIB-CONV-0003" : "R-SLIB-CONV-0002",
                                     index == UINT32_C(0)
                                         ? "parse source shall have type str"
                                         : "integer parse radix shall have type u32",
                                     operation_span);
        }
        child_storage[index] = lowered[index].node;
    }
    if (!r_body_validate_effect_set(body, effect_set, operation_span)) {
        return true;
    }
    children.items = child_storage;
    children.count = expected_count;
    children.capacity = expected_count;
    if (!r_body_append_node(body,
                            R_HIR_STANDARD_CALL,
                            call_span,
                            destination_type,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            destination_tag,
                            false,
                            &children,
                            &node_id)) {
        return false;
    }
    node = r_body_hir_node(body, node_id);
    if (node == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    node->auxiliary_type = effect_carrier;
    node->standard_operation = R_STANDARD_CALL_CONVERT_PARSE;
    if (!r_body_attach_effect_exits(body, node_id, effect_set, operation_span)) {
        return false;
    }
    result->node = node_id;
    result->type = destination_type;
    result->valid = true;
    return true;
}

static bool r_body_lower_standard_checked_call(RBodyContext *body,
                                               RAstRef argument_list,
                                               const RAstNodeView *arguments_view,
                                               RSourceSpan call_span,
                                               RSourceSpan operation_span,
                                               RTypeId contextual_type,
                                               RStandardCallOperation operation,
                                               RTokenKind destination_token,
                                               uint64_t destination_tag,
                                               RExpressionResult *result) {
    const char *const rule_id = r_body_standard_checked_rule(operation);
    RTypeId destination_type;
    RTypeId error_type;
    RTypeId effect_set;
    RTypeId effect_carrier;
    RTypeId effect_items[1];
    RTypeVector effects = {effect_items, UINT32_C(1), UINT32_C(1)};
    bool duplicate_effect = false;
    RTypeId contextual_value_type;
    uint64_t verified_destination_tag;
    RAstRef argument;
    RExpressionResult source;
    RHirNodeId child_storage[1];
    RHirVector children;
    RHirNodeId node_id;
    RHirNode *node;

    r_body_expression_invalid(result);
    if (arguments_view->child_count != UINT32_C(1)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 rule_id,
                                 "checked conversion requires exactly one numeric argument",
                                 call_span);
    }
    if (!r_semantic_type_from_token(body->frontend, destination_token, &destination_type) ||
        !r_semantic_checked_numeric_type_tag(
            body->frontend, destination_type, &verified_destination_tag) ||
        !r_semantic_intern_named_standard_type(
            body->frontend, "std.convert::range_error", &error_type)) {
        return false;
    }
    effect_items[0] = error_type;
    if (!r_semantic_intern_effect_set(body->frontend, &effects, &effect_set, &duplicate_effect) ||
        duplicate_effect ||
        !r_semantic_intern_effect_carrier(
            body->frontend, destination_type, effect_set, &effect_carrier)) {
        return false;
    }
    if (verified_destination_tag != destination_tag) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    contextual_value_type = r_semantic_value_type(body->frontend, contextual_type);
    if ((contextual_value_type != R_TYPE_ID_INVALID) &&
        (contextual_value_type != destination_type)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 rule_id,
                                 "checked conversion result does not match its exact context",
                                 operation_span);
    }
    if (!r_ast_ref_child(body->frontend, argument_list, UINT32_C(0), &argument) ||
        !r_body_lower_value(body, argument, R_TYPE_ID_INVALID, &source)) {
        return false;
    }
    if (!source.valid) {
        return true;
    }
    if (!r_semantic_checked_numeric_type_tag(body->frontend, source.type, NULL)) {
        if (body->frontend->resource_status != R_FRONTEND_OK) {
            return false;
        }
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 rule_id,
                                 "checked conversion source shall have a numeric type",
                                 call_span);
    }
    if (!r_body_validate_effect_set(body, effect_set, operation_span)) {
        return true;
    }
    child_storage[0] = source.node;
    children.items = child_storage;
    children.count = UINT32_C(1);
    children.capacity = UINT32_C(1);
    if (!r_body_append_node(body,
                            R_HIR_STANDARD_CALL,
                            call_span,
                            destination_type,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            destination_tag,
                            false,
                            &children,
                            &node_id)) {
        return false;
    }
    node = r_body_hir_node(body, node_id);
    if (node == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    node->auxiliary_type = effect_carrier;
    node->standard_operation = operation;
    if (!r_body_attach_effect_exits(body, node_id, effect_set, operation_span)) {
        return false;
    }
    result->node = node_id;
    result->type = destination_type;
    result->valid = true;
    return true;
}

static bool r_body_std_c_link_available_operation(const RFrontendContext *context,
                                                  RAstRef qualified,
                                                  RSourceSpan *operation_span) {
    RAstNodeView view;
    RAstTokenView components[3];
    uint32_t component_count = UINT32_C(0);
    uint32_t child_index;

    if (!r_ast_view_kind(context, qualified, R_SYNTAX_QUALIFIED_NAME, &view)) {
        return false;
    }
    (void)memset(components, 0, sizeof(components));
    for (child_index = UINT32_C(0); child_index < view.child_count; ++child_index) {
        RAstRef child;
        RAstTokenView token;

        if (!r_ast_ref_child(context, qualified, child_index, &child) ||
            !r_ast_ref_token(context, child, &token)) {
            continue;
        }
        if (component_count >= UINT32_C(3)) {
            return false;
        }
        components[component_count] = token;
        component_count += UINT32_C(1);
    }
    if ((component_count != UINT32_C(3)) ||
        !r_semantic_token_text_equal_owned(context, &components[0], "std") ||
        !r_semantic_token_text_equal_owned(context, &components[1], "c") ||
        !r_semantic_token_text_equal_owned(context, &components[2], "link_available")) {
        return false;
    }
    if (operation_span != NULL) {
        *operation_span = components[2].span;
    }
    return true;
}

static bool r_body_lower_std_c_link_available_call(RBodyContext *body,
                                                   RAstRef argument_list,
                                                   const RAstNodeView *arguments_view,
                                                   RSourceSpan call_span,
                                                   RSourceSpan operation_span,
                                                   RTypeId contextual_type,
                                                   RExpressionResult *result) {
    RTypeId bool_type;
    RTypeId constexpr_str_type;
    RAstRef argument;
    RExpressionResult logical_name;
    RHirNodeId child_storage[1];
    RHirVector children;
    RHirNodeId node_id;
    RHirNode *node;

    r_body_expression_invalid(result);
    if (arguments_view->child_count != UINT32_C(1)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-SLIB-C-0005",
                                 "std.c::link_available requires exactly one logical name",
                                 call_span);
    }
    if (!r_semantic_type_from_token(body->frontend, R_TOKEN_KW_BOOL, &bool_type) ||
        !r_semantic_intern_type(body->frontend,
                                R_SEMANTIC_TYPE_CONSTEXPR_STR,
                                R_TYPE_ID_INVALID,
                                &constexpr_str_type)) {
        return false;
    }
    if ((r_semantic_value_type(body->frontend, contextual_type) != R_TYPE_ID_INVALID) &&
        (r_semantic_value_type(body->frontend, contextual_type) != bool_type)) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-SLIB-C-0005",
                                 "std.c::link_available result shall have type bool",
                                 operation_span);
    }
    if (!r_ast_ref_child(body->frontend, argument_list, UINT32_C(0), &argument) ||
        !r_body_lower_value(body, argument, constexpr_str_type, &logical_name)) {
        return false;
    }
    if (!logical_name.valid) {
        return true;
    }
    if (logical_name.type != constexpr_str_type) {
        return r_body_diagnostic(body,
                                 "R-DIAG-TYPE-001",
                                 "R-SLIB-C-0005",
                                 "std.c::link_available logical name shall have type constexpr str",
                                 call_span);
    }
    child_storage[0] = logical_name.node;
    children.items = child_storage;
    children.count = UINT32_C(1);
    children.capacity = UINT32_C(1);
    if (!r_body_append_node(body,
                            R_HIR_STANDARD_CALL,
                            call_span,
                            bool_type,
                            R_SYMBOL_ID_INVALID,
                            R_TOKEN_INVALID,
                            UINT64_C(0),
                            false,
                            &children,
                            &node_id)) {
        return false;
    }
    node = r_body_hir_node(body, node_id);
    if (node == NULL) {
        body->frontend->resource_status = R_FRONTEND_INTERNAL_ERROR;
        return false;
    }
    node->auxiliary_type = constexpr_str_type;
    node->standard_operation = R_STANDARD_CALL_C_LINK_AVAILABLE;
    result->node = node_id;
    result->type = bool_type;
    result->valid = true;
    return true;
}

