/* R-FUNC-0023, R-EXPR-0032: translation-time evaluation over the checked HIR. */
#include "consteval.inc"

/*
 * R-FUNC-0004 static stack discipline. The program's R call graph, including drop hooks reached
 * through owned storage, call_once/get_or_init initializers and asynchronous starts, shall be
 * acyclic, and no aggregate may reach itself through owned storage. Every entry into R code
 * then has a worst-case stack bound that the generated C checks once at that entry instead of
 * before every call.
 */
typedef struct RStackEdge {
    RSymbolId caller;
    RSymbolId callee;
    RSourceSpan span;
} RStackEdge;

typedef struct RStackGraph {
    RFrontendContext *context;
    RStackEdge *edges;
    size_t edge_count;
    size_t edge_capacity;
    uint8_t *aggregate_seen;
    RSymbolId *callbacks;
    size_t callback_count;
    RSymbolId current;
    bool failed;
} RStackGraph;

typedef bool (*RStackAggregateVisitor)(void *user, uint32_t aggregate_id);

static bool r_stack_visit_owned_aggregates(const RFrontendContext *context,
                                           RTypeId type_id,
                                           uint32_t depth,
                                           RStackAggregateVisitor visitor,
                                           void *user) {
    const RSemanticType *type = r_semantic_type(context, type_id);

    if ((type == NULL) || (depth > context->options.limits.max_nesting) ||
        r_generic_type_is_dependent(context, type_id, 0U)) {
        return true;
    }
    switch (type->kind) {
    case R_SEMANTIC_TYPE_STRUCT:
    case R_SEMANTIC_TYPE_ENUM:
        return visitor(user, (uint32_t)type->base);
    case R_SEMANTIC_TYPE_OWN:
    case R_SEMANTIC_TYPE_ARC:
    case R_SEMANTIC_TYPE_RC:
    case R_SEMANTIC_TYPE_OPTION:
    case R_SEMANTIC_TYPE_ARRAY:
    case R_SEMANTIC_TYPE_LIST:
    case R_SEMANTIC_TYPE_FIXED_ARRAY:
    case R_SEMANTIC_TYPE_TASK:
    case R_SEMANTIC_TYPE_CONST:
    case R_SEMANTIC_TYPE_ATOMIC:
        return r_stack_visit_owned_aggregates(context, type->base, depth + 1U, visitor, user);
    case R_SEMANTIC_TYPE_DICT:
    case R_SEMANTIC_TYPE_RESULT:
    /* Standard nominal types own their type arguments (once_lock(T), decoder(T), ...). */
    case R_SEMANTIC_TYPE_STANDARD:
        return r_stack_visit_owned_aggregates(context, type->base, depth + 1U, visitor, user) &&
               r_stack_visit_owned_aggregates(context, type->second, depth + 1U, visitor, user);
    default:
        return true;
    }
}

/*
 * Place expressions, borrows, loads and address queries name storage that is owned elsewhere
 * (or by a declaration counted separately), so their types never add drop-hook callees.
 */
static bool r_stack_node_owns_value(RHirKind kind) {
    switch (kind) {
    case R_HIR_PLACE:
    case R_HIR_FIELD_PLACE:
    case R_HIR_INDEX_PLACE:
    case R_HIR_DEREF_PLACE:
    case R_HIR_BORROW:
    case R_HIR_SLICE:
    case R_HIR_LENGTH:
    case R_HIR_LOAD:
    case R_HIR_VARIANT_TAG:
    case R_HIR_FUNCTION_ADDRESS:
    case R_HIR_GENERIC_CONSTANT:
    case R_HIR_TYPE_QUERY:
    /* A switch only inspects its scrutinee; a moved scrutinee is a separate move node. */
    case R_HIR_SWITCH:
        return false;
    default:
        return true;
    }
}

static const RSemanticAggregate *r_stack_aggregate(const RFrontendContext *context,
                                                   uint32_t aggregate_id) {
    if ((aggregate_id == UINT32_C(0)) ||
        ((size_t)aggregate_id > context->semantic_aggregate_count)) {
        return NULL;
    }
    return &context->semantic_aggregates[(size_t)aggregate_id - 1U];
}

/* Visits the owned member types of one aggregate: struct fields and tagged variant payloads. */
static bool r_stack_visit_aggregate_members(const RFrontendContext *context,
                                            const RSemanticAggregate *aggregate,
                                            RStackAggregateVisitor visitor,
                                            void *user) {
    uint32_t index;

    for (index = UINT32_C(0); index < aggregate->field_count; ++index) {
        const size_t field_index = (size_t)aggregate->first_field + (size_t)index;

        if ((field_index < context->semantic_field_count) &&
            !r_stack_visit_owned_aggregates(
                context, context->semantic_fields[field_index].type, 0U, visitor, user)) {
            return false;
        }
    }
    for (index = UINT32_C(0); index < aggregate->variant_count; ++index) {
        const size_t variant_index = (size_t)aggregate->first_variant + (size_t)index;

        if ((variant_index < context->semantic_variant_count) &&
            (context->semantic_variants[variant_index].payload_type != R_TYPE_ID_INVALID) &&
            !r_stack_visit_owned_aggregates(context,
                                            context->semantic_variants[variant_index].payload_type,
                                            0U,
                                            visitor,
                                            user)) {
            return false;
        }
    }
    return true;
}

/*
 * Owned-aggregate graph for the self-nesting check of R-FUNC-0004. An edge from aggregate A to
 * aggregate B records that a value of A owns a value of B. SUPPORTED edges run through
 * by-value struct or enum members, own/rc/arc owners, o(...) options, fixed arrays and the
 * elements of array, list and dict values: the runtime destroyer walks such storage
 * iteratively. OTHER edges run through a dict key, a standard type, a task or an atomic; a
 * strongly connected component that contains one has no static stack bound and is rejected.
 * Every other component is recorded as recursive_group.
 */
enum {
    R_STACK_TYPE_EDGE_SUPPORTED = 0,
    R_STACK_TYPE_EDGE_OTHER = 1
};

typedef struct RStackTypeEdge {
    uint32_t from;
    uint32_t to;
    uint32_t label;
} RStackTypeEdge;

typedef struct RStackTypeGraph {
    RFrontendContext *context;
    RStackTypeEdge *edges;
    size_t edge_count;
    size_t edge_capacity;
    uint32_t current;
} RStackTypeGraph;

static bool r_stack_type_graph_push(RStackTypeGraph *graph, uint32_t to, uint32_t label) {
    if (graph->edge_count == graph->edge_capacity) {
        const size_t capacity =
            graph->edge_capacity == 0U ? (size_t)64U : graph->edge_capacity * 2U;
        RStackTypeEdge *edges = r_context_allocate(graph->context, capacity * sizeof(*edges));

        if (edges == NULL) {
            return false;
        }
        if (graph->edge_count != 0U) {
            (void)memcpy(edges, graph->edges, graph->edge_count * sizeof(*edges));
        }
        r_context_free(graph->context, graph->edges);
        graph->edges = edges;
        graph->edge_capacity = capacity;
    }
    graph->edges[graph->edge_count].from = graph->current;
    graph->edges[graph->edge_count].to = to;
    graph->edges[graph->edge_count].label = label;
    graph->edge_count += 1U;
    return true;
}

static bool
r_stack_type_collect(RStackTypeGraph *graph, RTypeId type_id, uint32_t label, uint32_t depth) {
    const RFrontendContext *context = graph->context;
    const RSemanticType *type = r_semantic_type(context, type_id);

    if ((type == NULL) || (depth > context->options.limits.max_nesting) ||
        r_generic_type_is_dependent(context, type_id, 0U)) {
        return true;
    }
    switch (type->kind) {
    case R_SEMANTIC_TYPE_STRUCT:
    case R_SEMANTIC_TYPE_ENUM:
        return r_stack_type_graph_push(graph, (uint32_t)type->base, label);
    case R_SEMANTIC_TYPE_CONST:
    case R_SEMANTIC_TYPE_OPTION:
    case R_SEMANTIC_TYPE_FIXED_ARRAY:
    case R_SEMANTIC_TYPE_OWN:
    case R_SEMANTIC_TYPE_RC:
    case R_SEMANTIC_TYPE_ARC:
    case R_SEMANTIC_TYPE_ARRAY:
    case R_SEMANTIC_TYPE_LIST:
        return r_stack_type_collect(graph, type->base, label, depth + 1U);
    case R_SEMANTIC_TYPE_DICT:
        /* Keys are dropped synchronously by the runtime; only values are traversed. */
        return r_stack_type_collect(graph, type->base, R_STACK_TYPE_EDGE_OTHER, depth + 1U) &&
               r_stack_type_collect(graph, type->second, label, depth + 1U);
    case R_SEMANTIC_TYPE_TASK:
    case R_SEMANTIC_TYPE_ATOMIC:
        return r_stack_type_collect(graph, type->base, R_STACK_TYPE_EDGE_OTHER, depth + 1U);
    case R_SEMANTIC_TYPE_RESULT:
    case R_SEMANTIC_TYPE_STANDARD:
        return r_stack_type_collect(graph, type->base, R_STACK_TYPE_EDGE_OTHER, depth + 1U) &&
               r_stack_type_collect(graph, type->second, R_STACK_TYPE_EDGE_OTHER, depth + 1U);
    default:
        return true;
    }
}

static int r_stack_type_edge_compare(const void *left_pointer, const void *right_pointer) {
    const RStackTypeEdge *left = left_pointer;
    const RStackTypeEdge *right = right_pointer;

    if (left->from != right->from) {
        return left->from < right->from ? -1 : 1;
    }
    if (left->to != right->to) {
        return left->to < right->to ? -1 : 1;
    }
    return 0;
}

/*
 * Collects the owned-aggregate graph, computes its strongly connected components with an
 * iterative Tarjan walk and records recursive_group for every self-nesting aggregate.
 */
static bool r_stack_validate_type_graph(RFrontendContext *context) {
    const size_t count = context->semantic_aggregate_count;
    RStackTypeGraph graph;
    uint32_t *edge_start = NULL;
    uint32_t *cursor = NULL;
    uint32_t *index = NULL;
    uint32_t *lowlink = NULL;
    uint32_t *component = NULL;
    uint32_t *stack = NULL;
    uint32_t *work = NULL;
    uint8_t *on_stack = NULL;
    uint8_t *recursive = NULL;
    uint8_t *reported = NULL;
    uint32_t next_index = UINT32_C(1);
    uint32_t component_count = UINT32_C(0);
    size_t aggregate_index;
    size_t edge_index;
    bool success = false;

    (void)memset(&graph, 0, sizeof(graph));
    graph.context = context;
    if (count == 0U) {
        return true;
    }
    for (aggregate_index = 1U; aggregate_index <= count; ++aggregate_index) {
        const RSemanticAggregate *aggregate = r_stack_aggregate(context, (uint32_t)aggregate_index);
        uint32_t member;

        context->semantic_aggregates[aggregate_index - 1U].recursive_group = UINT32_C(0);
        if ((aggregate == NULL) || aggregate->poisoned || !aggregate->complete) {
            continue;
        }
        graph.current = (uint32_t)aggregate_index;
        for (member = UINT32_C(0); member < aggregate->field_count; ++member) {
            const size_t field_index = (size_t)aggregate->first_field + (size_t)member;

            if ((field_index < context->semantic_field_count) &&
                !r_stack_type_collect(&graph,
                                      context->semantic_fields[field_index].type,
                                      R_STACK_TYPE_EDGE_SUPPORTED,
                                      0U)) {
                goto cleanup;
            }
        }
        for (member = UINT32_C(0); member < aggregate->variant_count; ++member) {
            const size_t variant_index = (size_t)aggregate->first_variant + (size_t)member;

            if ((variant_index < context->semantic_variant_count) &&
                (context->semantic_variants[variant_index].payload_type != R_TYPE_ID_INVALID) &&
                !r_stack_type_collect(&graph,
                                      context->semantic_variants[variant_index].payload_type,
                                      R_STACK_TYPE_EDGE_SUPPORTED,
                                      0U)) {
                goto cleanup;
            }
        }
    }
    if (graph.edge_count != 0U) {
        qsort(graph.edges, graph.edge_count, sizeof(*graph.edges), r_stack_type_edge_compare);
    }
    edge_start = r_context_allocate(context, (count + 2U) * sizeof(*edge_start));
    cursor = r_context_allocate(context, (count + 1U) * sizeof(*cursor));
    index = r_context_allocate(context, (count + 1U) * sizeof(*index));
    lowlink = r_context_allocate(context, (count + 1U) * sizeof(*lowlink));
    component = r_context_allocate(context, (count + 1U) * sizeof(*component));
    stack = r_context_allocate(context, (count + 1U) * sizeof(*stack));
    work = r_context_allocate(context, (count + 1U) * sizeof(*work));
    on_stack = r_context_allocate(context, count + 1U);
    recursive = r_context_allocate(context, count + 1U);
    reported = r_context_allocate(context, count + 1U);
    if ((edge_start == NULL) || (cursor == NULL) || (index == NULL) || (lowlink == NULL) ||
        (component == NULL) || (stack == NULL) || (work == NULL) || (on_stack == NULL) ||
        (recursive == NULL) || (reported == NULL)) {
        goto cleanup;
    }
    (void)memset(index, 0, (count + 1U) * sizeof(*index));
    (void)memset(component, 0, (count + 1U) * sizeof(*component));
    (void)memset(on_stack, 0, count + 1U);
    (void)memset(recursive, 0, count + 1U);
    (void)memset(reported, 0, count + 1U);
    /* Compressed adjacency: edges of aggregate a live in [edge_start[a], edge_start[a + 1]). */
    edge_index = 0U;
    for (aggregate_index = 0U; aggregate_index <= count + 1U; ++aggregate_index) {
        while ((edge_index < graph.edge_count) &&
               ((size_t)graph.edges[edge_index].from < aggregate_index)) {
            edge_index += 1U;
        }
        edge_start[aggregate_index] = (uint32_t)edge_index;
    }
    for (aggregate_index = 1U; aggregate_index <= count; ++aggregate_index) {
        const uint32_t root = (uint32_t)aggregate_index;
        size_t work_top;
        size_t stack_top = 0U;

        if (index[root] != UINT32_C(0)) {
            continue;
        }
        index[root] = next_index;
        lowlink[root] = next_index;
        next_index += UINT32_C(1);
        cursor[root] = edge_start[root];
        stack[stack_top] = root;
        stack_top += 1U;
        on_stack[root] = UINT8_C(1);
        work[0] = root;
        work_top = 1U;
        while (work_top != 0U) {
            const uint32_t vertex = work[work_top - 1U];

            if (cursor[vertex] < edge_start[vertex + 1U]) {
                const uint32_t target = graph.edges[cursor[vertex]].to;

                cursor[vertex] += UINT32_C(1);
                if ((target == UINT32_C(0)) || ((size_t)target > count)) {
                    continue;
                }
                if (index[target] == UINT32_C(0)) {
                    index[target] = next_index;
                    lowlink[target] = next_index;
                    next_index += UINT32_C(1);
                    cursor[target] = edge_start[target];
                    stack[stack_top] = target;
                    stack_top += 1U;
                    on_stack[target] = UINT8_C(1);
                    work[work_top] = target;
                    work_top += 1U;
                } else if ((on_stack[target] != 0U) && (index[target] < lowlink[vertex])) {
                    lowlink[vertex] = index[target];
                }
                continue;
            }
            work_top -= 1U;
            if ((work_top != 0U) && (lowlink[vertex] < lowlink[work[work_top - 1U]])) {
                lowlink[work[work_top - 1U]] = lowlink[vertex];
            }
            if (lowlink[vertex] == index[vertex]) {
                component_count += UINT32_C(1);
                for (;;) {
                    const uint32_t popped = stack[stack_top - 1U];

                    stack_top -= 1U;
                    on_stack[popped] = UINT8_C(0);
                    component[popped] = component_count;
                    if (popped == vertex) {
                        break;
                    }
                }
            }
        }
    }
    for (edge_index = 0U; edge_index < graph.edge_count; ++edge_index) {
        const RStackTypeEdge *edge = &graph.edges[edge_index];

        if ((edge->to == UINT32_C(0)) || ((size_t)edge->to > count) ||
            (component[edge->from] != component[edge->to])) {
            continue;
        }
        if (edge->label == R_STACK_TYPE_EDGE_OTHER) {
            const RSemanticAggregate *aggregate = r_stack_aggregate(context, edge->from);

            if ((reported[edge->from] == 0U) && (aggregate != NULL)) {
                reported[edge->from] = UINT8_C(1);
                if (!r_semantic_add_diagnostic(
                        context,
                        "R-DIAG-STACK-001",
                        "R-FUNC-0004",
                        "recursive ownership through a dict key, a standard type, a task or "
                        "an atomic has no static stack bound; self-nesting is supported "
                        "through own, rc, arc, o<...>, fixed arrays, array, list and dict "
                        "values, and by-value struct or enum members",
                        aggregate->name_span)) {
                    goto cleanup;
                }
            }
            continue;
        }
        recursive[edge->from] = UINT8_C(1);
        recursive[edge->to] = UINT8_C(1);
    }
    for (aggregate_index = 1U; aggregate_index <= count; ++aggregate_index) {
        if ((recursive[aggregate_index] != 0U) && (reported[aggregate_index] == 0U)) {
            RSemanticAggregate *aggregate = &context->semantic_aggregates[aggregate_index - 1U];

            aggregate->recursive_group = component[aggregate_index];
            /* Derived JSON glue recurses through the members it encodes or decodes. */
            if (aggregate->json_derived &&
                !r_semantic_add_diagnostic(context,
                                           "R-DIAG-STACK-001",
                                           "R-FUNC-0004",
                                           "derived JSON encoding or decoding of a self-nesting "
                                           "type recurses with the data and has no static stack "
                                           "bound",
                                           aggregate->name_span)) {
                goto cleanup;
            }
        }
    }
    success = true;
cleanup:
    r_context_free(context, graph.edges);
    r_context_free(context, edge_start);
    r_context_free(context, cursor);
    r_context_free(context, index);
    r_context_free(context, lowlink);
    r_context_free(context, component);
    r_context_free(context, stack);
    r_context_free(context, work);
    r_context_free(context, on_stack);
    r_context_free(context, recursive);
    r_context_free(context, reported);
    return success;
}

static bool
r_stack_graph_push_edge(RStackGraph *graph, RSymbolId caller, RSymbolId callee, RSourceSpan span) {
    if (graph->edge_count == graph->edge_capacity) {
        const size_t capacity =
            graph->edge_capacity == 0U ? (size_t)64U : graph->edge_capacity * 2U;
        RStackEdge *edges = r_context_allocate(graph->context, capacity * sizeof(*edges));

        if (edges == NULL) {
            return false;
        }
        if (graph->edge_count != 0U) {
            (void)memcpy(edges, graph->edges, graph->edge_count * sizeof(*edges));
        }
        r_context_free(graph->context, graph->edges);
        graph->edges = edges;
        graph->edge_capacity = capacity;
    }
    graph->edges[graph->edge_count].caller = caller;
    graph->edges[graph->edge_count].callee = callee;
    graph->edges[graph->edge_count].span = span;
    graph->edge_count += 1U;
    return true;
}

static bool r_stack_graph_is_r_function(const RFrontendContext *context, RSymbolId symbol_id) {
    const RSemanticSymbol *symbol;

    if ((symbol_id == R_SYMBOL_ID_INVALID) ||
        ((size_t)symbol_id > context->semantic_symbol_count)) {
        return false;
    }
    symbol = &context->semantic_symbols[(size_t)symbol_id - 1U];
    return (symbol->kind == R_SEMANTIC_SYMBOL_FUNCTION) && !symbol->is_import;
}

bool r_semantic_callback_may_be_target(const RFrontendContext *context,
                                       RSymbolId function_id,
                                       RTypeId raw_function_type) {
    const RSemanticSymbol *function;
    const RSemanticType *type;
    RTypeId parameter;
    uint32_t index;

    if ((function_id == R_SYMBOL_ID_INVALID) ||
        ((size_t)function_id > context->semantic_symbol_count)) {
        return false;
    }
    function = &context->semantic_symbols[(size_t)function_id - 1U];
    if ((function->kind != R_SEMANTIC_SYMBOL_FUNCTION) || !function->is_callback ||
        function->is_import) {
        return false;
    }
    type = r_semantic_type(context, r_semantic_value_type(context, raw_function_type));
    if ((type == NULL) || (type->kind != R_SEMANTIC_TYPE_RAW_FUNCTION)) {
        return true;
    }
    if ((function->return_type != type->base) ||
        ((uint64_t)function->parameter_count != type->length)) {
        return false;
    }
    parameter = type->second;
    for (index = UINT32_C(0); index < function->parameter_count; ++index) {
        const RSemanticType *item = r_semantic_type(context, parameter);
        const size_t parameter_index = (size_t)function->first_parameter_type + (size_t)index;

        if ((item == NULL) || (item->kind != R_SEMANTIC_TYPE_FUNCTION_PARAMETER) ||
            (parameter_index >= context->semantic_parameter_type_count) ||
            (item->base !=
             r_semantic_value_type(context, context->semantic_parameter_types[parameter_index]))) {
            return false;
        }
        parameter = item->second;
    }
    return true;
}

typedef struct RStackHookState {
    RStackGraph *graph;
    RSourceSpan span;
} RStackHookState;

/* Every aggregate with a drop hook reached through owned storage is a callee of the function. */
static bool r_stack_hook_visit(void *user, uint32_t aggregate_id) {
    RStackHookState *state = user;
    RStackGraph *graph = state->graph;
    const RSemanticAggregate *aggregate = r_stack_aggregate(graph->context, aggregate_id);

    if ((aggregate == NULL) || graph->failed || (graph->aggregate_seen[aggregate_id] != 0U)) {
        return true;
    }
    graph->aggregate_seen[aggregate_id] = UINT8_C(1);
    if (r_stack_graph_is_r_function(graph->context, aggregate->drop_function) &&
        !r_stack_graph_push_edge(graph, graph->current, aggregate->drop_function, state->span)) {
        graph->failed = true;
        return true;
    }
    if (!r_stack_visit_aggregate_members(graph->context, aggregate, r_stack_hook_visit, state)) {
        graph->failed = true;
    }
    return true;
}

/* R-OWN-0020: a clone hook entered by the clone glue of a core::clone call. */
static bool r_stack_clone_hook_visit(void *user, RSymbolId hook) {
    RStackHookState *state = user;
    RStackGraph *graph = state->graph;

    if (r_stack_graph_is_r_function(graph->context, hook) &&
        !r_stack_graph_push_edge(graph, graph->current, hook, state->span)) {
        graph->failed = true;
    }
    return true;
}

static bool r_stack_graph_collect_node(RStackGraph *graph, RHirNodeId node_id, uint32_t depth) {
    RFrontendContext *context = graph->context;
    const RHirNode *node;
    RStackHookState hooks;
    uint32_t index;

    if ((node_id == R_HIR_NODE_ID_INVALID) || ((size_t)node_id > context->hir_node_count) ||
        (depth > UINT32_C(4096))) {
        return true;
    }
    node = &context->hir_nodes[(size_t)node_id - 1U];
    hooks.graph = graph;
    hooks.span = node->span;
    if (r_stack_node_owns_value(node->kind) &&
        (!r_stack_visit_owned_aggregates(context, node->type, 0U, r_stack_hook_visit, &hooks) ||
         !r_stack_visit_owned_aggregates(
             context, node->auxiliary_type, 0U, r_stack_hook_visit, &hooks) ||
         graph->failed)) {
        return !graph->failed;
    }
    switch (node->kind) {
    case R_HIR_ASSIGN:
        /* Replacing an initialized destination drops its previous value in this function. */
        if ((node->child_count == UINT32_C(2)) &&
            ((size_t)node->first_child < context->hir_child_count)) {
            const RHirNodeId destination_id = context->hir_children[node->first_child];

            if ((destination_id != R_HIR_NODE_ID_INVALID) &&
                ((size_t)destination_id <= context->hir_node_count) &&
                (!r_stack_visit_owned_aggregates(
                     context,
                     context->hir_nodes[(size_t)destination_id - 1U].type,
                     0U,
                     r_stack_hook_visit,
                     &hooks) ||
                 graph->failed)) {
                return !graph->failed;
            }
        }
        break;
    case R_HIR_CALL:
    case R_HIR_ASYNC_START:
        if (r_stack_graph_is_r_function(context, node->symbol) &&
            !r_stack_graph_push_edge(graph, graph->current, node->symbol, node->span)) {
            return false;
        }
        break;
    case R_HIR_STANDARD_CALL:
        if (((node->standard_operation == R_STANDARD_CALL_SYNC_CALL_ONCE) ||
             (node->standard_operation == R_STANDARD_CALL_SYNC_CALL_ONCE_FORCE) ||
             (node->standard_operation == R_STANDARD_CALL_SYNC_GET_OR_INIT)) &&
            r_stack_graph_is_r_function(context, node->symbol) &&
            !r_stack_graph_push_edge(graph, graph->current, node->symbol, node->span)) {
            return false;
        }
        /* R-OWN-0020: the clone glue calls every clone hook of the copied structure. */
        if ((node->standard_operation == R_STANDARD_CALL_CORE_CLONE) &&
            (!r_clone_visit_hooks(context, node->type, 0U, r_stack_clone_hook_visit, &hooks) ||
             graph->failed)) {
            return !graph->failed;
        }
        /* R-TYPE-0046 (L32): the format glue calls every implementation the value reaches. */
        if (((node->standard_operation == R_STANDARD_CALL_CORE_FORMAT_RENDER) ||
             (node->standard_operation == R_STANDARD_CALL_CORE_FORMAT_APPEND)) &&
            (!r_format_visit_hooks(
                 context, node->runtime_type, 0U, r_stack_clone_hook_visit, &hooks) ||
             graph->failed)) {
            return !graph->failed;
        }
        break;
    case R_HIR_INDIRECT_CALL: {
        /* R-FUNC-0007: a raw fn call may reach every callback whose signature matches. A direct
           call of a C import enters that C function: C code that calls back into R does so
           through an entry from C, which checks its own stack bound (R-FUNC-0004). */
        RTypeId signature = R_TYPE_ID_INVALID;
        bool direct_import = false;

        if ((node->child_count != UINT32_C(0)) &&
            ((size_t)node->first_child < context->hir_child_count)) {
            const RHirNodeId callee_id = context->hir_children[node->first_child];

            if ((callee_id != R_HIR_NODE_ID_INVALID) &&
                ((size_t)callee_id <= context->hir_node_count)) {
                const RHirNode *callee = &context->hir_nodes[(size_t)callee_id - 1U];

                signature = callee->type;
                direct_import = (callee->kind == R_HIR_FUNCTION_ADDRESS) &&
                                (callee->symbol != R_SYMBOL_ID_INVALID) &&
                                ((size_t)callee->symbol <= context->semantic_symbol_count) &&
                                context->semantic_symbols[(size_t)callee->symbol - 1U].is_import;
            }
        }
        for (index = UINT32_C(0); !direct_import && (index < graph->callback_count); ++index) {
            if (r_semantic_callback_may_be_target(context, graph->callbacks[index], signature) &&
                !r_stack_graph_push_edge(
                    graph, graph->current, graph->callbacks[index], node->span)) {
                return false;
            }
        }
        break;
    }
    default:
        break;
    }
    for (index = UINT32_C(0); index < node->child_count; ++index) {
        const size_t child_index = (size_t)node->first_child + (size_t)index;

        if ((child_index < context->hir_child_count) &&
            !r_stack_graph_collect_node(graph, context->hir_children[child_index], depth + 1U)) {
            return false;
        }
    }
    for (index = UINT32_C(0); index < node->effect_exit_count; ++index) {
        const size_t exit_index = (size_t)node->first_effect_exit + (size_t)index;

        if ((exit_index < context->hir_effect_exit_count) &&
            !r_stack_graph_collect_node(
                graph, context->hir_effect_exits[exit_index].cleanup_block, depth + 1U)) {
            return false;
        }
    }
    return true;
}

static int r_stack_edge_compare(const void *left_pointer, const void *right_pointer) {
    const RStackEdge *left = left_pointer;
    const RStackEdge *right = right_pointer;

    if (left->caller != right->caller) {
        return left->caller < right->caller ? -1 : 1;
    }
    if (left->span.start != right->span.start) {
        return left->span.start < right->span.start ? -1 : 1;
    }
    if (left->callee != right->callee) {
        return left->callee < right->callee ? -1 : 1;
    }
    return 0;
}

/* R-TYPE-0054 (L28): the spelling of a function type in a diagnostic, `fn(i32) -> i32`. */
static bool r_function_value_display(RGenericText *text, RTypeId type_id) {
    RFrontendContext *context = text->context;
    const RSemanticType *type = r_semantic_type(context, r_semantic_value_type(context, type_id));
    if ((type == NULL) || (type->kind != R_SEMANTIC_TYPE_FUNCTION)) {
        return false;
    }
    const RSemanticType function = *type;
    const RSemanticType *result = r_semantic_type(context, function.base);
    const bool carrier = (result != NULL) && (result->kind == R_SEMANTIC_TYPE_EFFECT_CARRIER);
    const RTypeId returned = carrier ? result->base : function.base;
    const RTypeId effects = carrier ? result->second : R_TYPE_ID_INVALID;
    const char *prefix =
        (function.flags & R_SEMANTIC_TYPE_FLAG_CALL_ASYNC) != 0U ? "async fn" : "fn";
    if (!r_generic_text(text, prefix, strlen(prefix)) ||
        (((function.flags & R_SEMANTIC_TYPE_FLAG_NOALLOC) != 0U) &&
         !r_generic_text(text, " @noalloc", 9U)) ||
        (((function.flags & R_SEMANTIC_TYPE_FLAG_NONBLOCKING) != 0U) &&
         !r_generic_text(text, " @nonblocking", 13U)) ||
        !r_generic_text(text, "(", 1U)) {
        return false;
    }
    for (RTypeId link = function.second; link != R_TYPE_ID_INVALID;) {
        const RSemanticType *parameter = r_semantic_type(context, link);
        if ((parameter == NULL) || ((link != function.second) && !r_generic_text(text, ", ", 2U)) ||
            !r_generic_type_name(text, parameter->base, 1U)) {
            return false;
        }
        link = parameter->second;
    }
    if (!r_generic_text(text, ") -> ", 5U) || !r_generic_type_name(text, returned, 1U)) {
        return false;
    }
    if (effects != R_TYPE_ID_INVALID) {
        if (!r_generic_text(text, " throws(", 8U)) {
            return false;
        }
        for (uint32_t effect = 0U; effect < r_semantic_effect_count(context, effects); ++effect) {
            if (((effect != 0U) && !r_generic_text(text, ", ", 2U)) ||
                !r_generic_type_name(text, r_semantic_effect_at(context, effects, effect), 1U)) {
                return false;
            }
        }
        if (!r_generic_text(text, ")", 1U)) {
            return false;
        }
    }
    return true;
}

static void r_stack_append_name(
    RFrontendContext *context, char *buffer, size_t capacity, size_t *length, RSymbolId symbol_id) {
    const RSemanticSymbol *symbol = &context->semantic_symbols[(size_t)symbol_id - 1U];
    const char *bytes = "?";
    size_t name_length = 1U;
    RGenericText text = {context, NULL, 0U, 0U, true};

    if (r_function_value_dispatcher(context, symbol_id) &&
        r_generic_text(&text, "call through `", 14U) &&
        r_function_value_display(&text,
                                 context->generic_arguments[symbol->first_generic_argument]) &&
        r_generic_text(&text, "`", 1U)) {
        /* R-TYPE-0054 (L28): a call through a function value is named by the value's type. */
        bytes = (const char *)text.bytes;
        name_length = text.length;
    } else {
        (void)r_semantic_intern_text(context, symbol->name_intern_id, &bytes, &name_length);
    }
    if (*length + name_length + 4U >= capacity) {
        if (*length + 4U < capacity) {
            (void)memcpy(buffer + *length, "...", 3U);
            *length += 3U;
        }
        r_context_free(context, text.bytes);
        return;
    }
    (void)memcpy(buffer + *length, bytes, name_length);
    *length += name_length;
    r_context_free(context, text.bytes);
}

static bool r_stack_report_cycle(RStackGraph *graph,
                                 const RSymbolId *stack,
                                 size_t stack_count,
                                 size_t cycle_start,
                                 RSymbolId callee,
                                 RSourceSpan span) {
    char message[320];
    size_t length = 0U;
    size_t index;
    uint32_t intern_id = UINT32_C(0);
    static const char prefix[] = "recursive call chain: ";

    (void)memcpy(message, prefix, sizeof(prefix) - 1U);
    length = sizeof(prefix) - 1U;
    for (index = cycle_start; index < stack_count; ++index) {
        r_stack_append_name(graph->context, message, sizeof(message) - 1U, &length, stack[index]);
        if (length + 4U < sizeof(message) - 1U) {
            (void)memcpy(message + length, " -> ", 4U);
            length += 4U;
        }
    }
    r_stack_append_name(graph->context, message, sizeof(message) - 1U, &length, callee);
    message[length] = '\0';
    /* Diagnostics borrow their text, so the chain is interned into context-owned storage. */
    if (!r_intern_bytes(graph->context, (const uint8_t *)message, length, &intern_id)) {
        return false;
    }
    return r_semantic_add_diagnostic(graph->context,
                                     "R-DIAG-STACK-001",
                                     "R-FUNC-0004",
                                     graph->context->intern_entries[(size_t)intern_id - 1U].bytes,
                                     span);
}

static bool r_stack_function_recursive(const RFrontendContext *context, RSymbolId symbol_id) {
    return r_stack_graph_is_r_function(context, symbol_id) &&
           (context->semantic_symbols[(size_t)symbol_id - 1U].recursion_depth != 0U);
}

/* R-FUNC-0026 (L35): the strongly connected sets of R functions (Tarjan, iteratively). A set with
 * a call cycle is permitted when every member has @recursion; component[s] is the set of symbol s
 * (zero for a symbol that is not an R function) and flags[c] has bit 1 for a set with a cycle
 * and bit 2 for a permitted one. */
static bool r_stack_graph_components(RStackGraph *graph,
                                     const size_t *first_edge,
                                     uint32_t *component,
                                     uint8_t *flags) {
    RFrontendContext *context = graph->context;
    const size_t symbol_count = context->semantic_symbol_count;
    uint32_t *index = r_context_allocate(context, (symbol_count + 1U) * sizeof(*index));
    uint32_t *lowlink = r_context_allocate(context, (symbol_count + 1U) * sizeof(*lowlink));
    size_t *cursor = r_context_allocate(context, (symbol_count + 1U) * sizeof(*cursor));
    RSymbolId *stack = r_context_allocate(context, (symbol_count + 1U) * sizeof(*stack));
    RSymbolId *work = r_context_allocate(context, (symbol_count + 1U) * sizeof(*work));
    uint8_t *on_stack = r_context_allocate(context, symbol_count + 1U);
    uint32_t next_index = 1U, count = 0U;
    bool success = false;

    if ((index == NULL) || (lowlink == NULL) || (cursor == NULL) || (stack == NULL) ||
        (work == NULL) || (on_stack == NULL))
        goto cleanup;
    (void)memset(index, 0, (symbol_count + 1U) * sizeof(*index));
    (void)memset(on_stack, 0, symbol_count + 1U);
    (void)memset(component, 0, (symbol_count + 1U) * sizeof(*component));
    (void)memset(flags, 0, symbol_count + 1U);
    for (size_t root = 1U; root <= symbol_count; ++root) {
        size_t stack_top = 0U, work_top = 1U;
        if ((index[root] != 0U) || !r_stack_graph_is_r_function(context, (RSymbolId)root))
            continue;
        index[root] = lowlink[root] = next_index++;
        cursor[root] = first_edge[root];
        stack[stack_top++] = (RSymbolId)root;
        on_stack[root] = 1U;
        work[0] = (RSymbolId)root;
        while (work_top != 0U) {
            const RSymbolId vertex = work[work_top - 1U];
            if (cursor[vertex] < first_edge[(size_t)vertex + 1U]) {
                const RSymbolId target = graph->edges[cursor[vertex]++].callee;
                if (!r_stack_graph_is_r_function(context, target))
                    continue;
                if (index[target] == 0U) {
                    index[target] = lowlink[target] = next_index++;
                    cursor[target] = first_edge[target];
                    stack[stack_top++] = target;
                    on_stack[target] = 1U;
                    work[work_top++] = target;
                } else if ((on_stack[target] != 0U) && (index[target] < lowlink[vertex])) {
                    lowlink[vertex] = index[target];
                }
                continue;
            }
            work_top -= 1U;
            if ((work_top != 0U) && (lowlink[vertex] < lowlink[work[work_top - 1U]]))
                lowlink[work[work_top - 1U]] = lowlink[vertex];
            if (lowlink[vertex] == index[vertex]) {
                RSymbolId member;
                count += 1U;
                do {
                    member = stack[--stack_top];
                    on_stack[member] = 0U;
                    component[member] = count;
                } while (member != vertex);
            }
        }
    }
    for (size_t edge = 0U; edge < graph->edge_count; ++edge) {
        const RSymbolId caller = graph->edges[edge].caller, callee = graph->edges[edge].callee;
        if (r_stack_graph_is_r_function(context, caller) &&
            r_stack_graph_is_r_function(context, callee) &&
            (component[caller] == component[callee]))
            flags[component[caller]] = UINT8_C(3);
    }
    for (size_t symbol = 1U; symbol <= symbol_count; ++symbol) {
        if ((component[symbol] != 0U) && !r_stack_function_recursive(context, (RSymbolId)symbol))
            flags[component[symbol]] &= (uint8_t)~UINT8_C(2);
    }
    success = true;
cleanup:
    r_context_free(context, index);
    r_context_free(context, lowlink);
    r_context_free(context, cursor);
    r_context_free(context, stack);
    r_context_free(context, work);
    r_context_free(context, on_stack);
    return success;
}

/* A cycle of a forbidden set that the walk below did not name: the shortest one through a
 * member without @recursion, reported at the call that closes it. */
static bool r_stack_report_unnamed_cycle(RStackGraph *graph,
                                         const size_t *first_edge,
                                         const uint32_t *component,
                                         RSymbolId start) {
    RFrontendContext *context = graph->context;
    const size_t symbol_count = context->semantic_symbol_count;
    RSymbolId *queue = r_context_allocate(context, (symbol_count + 1U) * sizeof(*queue));
    RSymbolId *previous = r_context_allocate(context, (symbol_count + 1U) * sizeof(*previous));
    RSymbolId *path = r_context_allocate(context, (symbol_count + 1U) * sizeof(*path));
    size_t head = 0U, tail = 0U;
    bool success = false;

    if ((queue == NULL) || (previous == NULL) || (path == NULL))
        goto cleanup;
    (void)memset(previous, 0, (symbol_count + 1U) * sizeof(*previous));
    queue[tail++] = start;
    while (head < tail) {
        const RSymbolId vertex = queue[head++];
        for (size_t edge = first_edge[vertex]; edge < first_edge[(size_t)vertex + 1U]; ++edge) {
            const RSymbolId callee = graph->edges[edge].callee;
            if (!r_stack_graph_is_r_function(context, callee) ||
                (component[callee] != component[start]))
                continue;
            if (callee == start) {
                size_t count = 0U;
                for (RSymbolId step = vertex; step != start; step = previous[step])
                    path[count++] = step;
                path[count++] = start;
                for (size_t low = 0U, high = count - 1U; low < high; ++low, --high) {
                    const RSymbolId swap = path[low];
                    path[low] = path[high];
                    path[high] = swap;
                }
                success =
                    r_stack_report_cycle(graph, path, count, 0U, start, graph->edges[edge].span);
                goto cleanup;
            }
            if ((previous[callee] == 0U) && (callee != start)) {
                previous[callee] = vertex;
                queue[tail++] = callee;
            }
        }
    }
    /* Every member of a set with a cycle lies on a cycle through itself. */
    context->resource_status = R_FRONTEND_INTERNAL_ERROR;
cleanup:
    r_context_free(context, queue);
    r_context_free(context, previous);
    r_context_free(context, path);
    return success;
}

static bool r_stack_graph_detect_cycles(RStackGraph *graph) {
    RFrontendContext *context = graph->context;
    const size_t symbol_count = context->semantic_symbol_count;
    uint8_t *color = NULL;
    size_t *first_edge = NULL;
    size_t *cursor = NULL;
    RSymbolId *stack = NULL;
    uint32_t *component = NULL;
    uint8_t *flags = NULL;
    uint8_t *reported = NULL;
    size_t stack_count = 0U;
    size_t root_index;
    size_t edge_index;
    bool success = false;

    if (symbol_count == 0U) {
        return true;
    }
    component = r_context_allocate(context, (symbol_count + 1U) * sizeof(*component));
    flags = r_context_allocate(context, symbol_count + 1U);
    reported = r_context_allocate(context, symbol_count + 1U);
    if ((component == NULL) || (flags == NULL) || (reported == NULL)) {
        goto cleanup;
    }
    (void)memset(reported, 0, symbol_count + 1U);
    color = r_context_allocate(context, symbol_count + 1U);
    first_edge = r_context_allocate(context, (symbol_count + 2U) * sizeof(*first_edge));
    cursor = r_context_allocate(context, (symbol_count + 1U) * sizeof(*cursor));
    stack = r_context_allocate(context, (symbol_count + 1U) * sizeof(*stack));
    if ((color == NULL) || (first_edge == NULL) || (cursor == NULL) || (stack == NULL)) {
        goto cleanup;
    }
    (void)memset(color, 0, symbol_count + 1U);
    if (graph->edge_count > 1U) {
        qsort(graph->edges, graph->edge_count, sizeof(*graph->edges), r_stack_edge_compare);
    }
    /* first_edge[s] .. first_edge[s + 1] are the outgoing edges of symbol s. */
    edge_index = 0U;
    for (root_index = 0U; root_index <= symbol_count; ++root_index) {
        while ((edge_index < graph->edge_count) &&
               ((size_t)graph->edges[edge_index].caller < root_index)) {
            edge_index += 1U;
        }
        first_edge[root_index] = edge_index;
    }
    first_edge[symbol_count + 1U] = graph->edge_count;
    if (!r_stack_graph_components(graph, first_edge, component, flags)) {
        goto cleanup;
    }
    for (root_index = 1U; root_index <= symbol_count; ++root_index) {
        if ((color[root_index] != UINT8_C(0)) ||
            !r_stack_graph_is_r_function(context, (RSymbolId)root_index)) {
            continue;
        }
        color[root_index] = UINT8_C(1);
        cursor[root_index] = first_edge[root_index];
        stack[0] = (RSymbolId)root_index;
        stack_count = 1U;
        while (stack_count != 0U) {
            const RSymbolId top = stack[stack_count - 1U];

            if (cursor[top] >= first_edge[(size_t)top + 1U]) {
                color[top] = UINT8_C(2);
                stack_count -= 1U;
                continue;
            }
            {
                const RStackEdge *edge = &graph->edges[cursor[top]];
                const RSymbolId callee = edge->callee;

                cursor[top] += 1U;
                if ((component[top] != 0U) && (component[top] == component[callee]) &&
                    ((flags[component[top]] & UINT8_C(2)) != 0U)) {
                    /* R-FUNC-0026: a call inside a set of functions with @recursion. */
                    continue;
                }
                if (color[callee] == UINT8_C(1)) {
                    size_t cycle_start = 0U;
                    bool all_recursive = r_stack_function_recursive(context, callee);

                    while ((cycle_start < stack_count) && (stack[cycle_start] != callee)) {
                        cycle_start += 1U;
                    }
                    for (size_t member = cycle_start; member < stack_count; ++member) {
                        all_recursive =
                            all_recursive && r_stack_function_recursive(context, stack[member]);
                    }
                    /* A cycle of functions that all have @recursion inside a forbidden set is
                       not the culprit; a cycle through a member without it is named below. */
                    if (!all_recursive) {
                        if (!r_stack_report_cycle(
                                graph, stack, stack_count, cycle_start, callee, edge->span)) {
                            goto cleanup;
                        }
                        if (component[callee] != 0U) {
                            reported[component[callee]] = UINT8_C(1);
                        }
                    }
                    /* One report per closing edge; the callee stays gray for its own frame. */
                } else if (color[callee] == UINT8_C(0)) {
                    color[callee] = UINT8_C(1);
                    cursor[callee] = first_edge[callee];
                    stack[stack_count] = callee;
                    stack_count += 1U;
                }
            }
        }
    }
    for (root_index = 1U; root_index <= symbol_count; ++root_index) {
        const uint32_t set = component[root_index];
        if ((set == 0U) || (flags[set] != UINT8_C(1)) || (reported[set] != 0U) ||
            r_stack_function_recursive(context, (RSymbolId)root_index)) {
            continue;
        }
        reported[set] = UINT8_C(1);
        if (!r_stack_report_unnamed_cycle(graph, first_edge, component, (RSymbolId)root_index)) {
            goto cleanup;
        }
    }
    success = true;
cleanup:
    r_context_free(context, color);
    r_context_free(context, first_edge);
    r_context_free(context, cursor);
    r_context_free(context, stack);
    r_context_free(context, component);
    r_context_free(context, flags);
    r_context_free(context, reported);
    return success;
}

static bool r_semantic_validate_stack_graph(RFrontendContext *context) {
    RStackGraph graph;
    size_t symbol_index;
    bool success = false;

    (void)memset(&graph, 0, sizeof(graph));
    graph.context = context;
    if (!r_stack_validate_type_graph(context)) {
        goto cleanup;
    }
    if (context->semantic_aggregate_count != 0U) {
        graph.aggregate_seen = r_context_allocate(context, context->semantic_aggregate_count + 1U);
        if (graph.aggregate_seen == NULL) {
            goto cleanup;
        }
    }
    if (context->semantic_symbol_count != 0U) {
        graph.callbacks =
            r_context_allocate(context, context->semantic_symbol_count * sizeof(RSymbolId));
        if (graph.callbacks == NULL) {
            goto cleanup;
        }
    }
    for (symbol_index = 1U; symbol_index <= context->semantic_symbol_count; ++symbol_index) {
        const RSemanticSymbol *symbol = &context->semantic_symbols[symbol_index - 1U];

        if ((symbol->kind == R_SEMANTIC_SYMBOL_FUNCTION) && symbol->is_callback &&
            !symbol->is_import) {
            graph.callbacks[graph.callback_count] = (RSymbolId)symbol_index;
            graph.callback_count += 1U;
        }
    }
    for (symbol_index = 1U; symbol_index <= context->semantic_symbol_count; ++symbol_index) {
        const RSemanticSymbol *symbol = &context->semantic_symbols[symbol_index - 1U];

        if ((symbol->kind != R_SEMANTIC_SYMBOL_FUNCTION) || symbol->is_import ||
            (symbol->hir_node == R_HIR_NODE_ID_INVALID)) {
            continue;
        }
        graph.current = (RSymbolId)symbol_index;
        if (graph.aggregate_seen != NULL) {
            (void)memset(graph.aggregate_seen, 0, context->semantic_aggregate_count + 1U);
        }
        if (!r_stack_graph_collect_node(&graph, symbol->hir_node, 0U) || graph.failed) {
            goto cleanup;
        }
    }
    /* R-FUNC-0004, R-TYPE-0051, R-TYPE-0054: a dispatching call reaches the implementation of
       every member and a call through a function value every target of its type; a function
       target is reported where it was converted. */
    for (symbol_index = 0U; symbol_index < context->dyn_target_count; ++symbol_index) {
        const RDynTarget target = context->dyn_targets[symbol_index];
        if (r_semantic_dyn_format_target(context, target.target)) {
            /* R-TYPE-0046 (L32): the format glue of a member with standard formatting calls
               the implementations its components reach. */
            RStackHookState hooks = {&graph,
                                     context->semantic_symbols[target.dispatcher - 1U].name_span};
            graph.current = target.dispatcher;
            if (!r_format_visit_hooks(
                    context, target.member, 0U, r_stack_clone_hook_visit, &hooks) ||
                graph.failed) {
                goto cleanup;
            }
            continue;
        }
        if (r_stack_graph_is_r_function(context, target.target) &&
            !r_stack_graph_push_edge(
                &graph,
                target.dispatcher,
                target.target,
                target.span.source != R_SOURCE_ID_INVALID
                    ? target.span
                    : context->semantic_symbols[target.dispatcher - 1U].name_span)) {
            goto cleanup;
        }
    }
    success = r_stack_graph_detect_cycles(&graph);
cleanup:
    r_context_free(context, graph.aggregate_seen);
    r_context_free(context, graph.callbacks);
    r_context_free(context, graph.edges);
    return success;
}

#include "conditional_positions.inc"
#include "local_reassignment.inc"
#include "must_use.inc"
#include "out_result_use.inc"
#include "resource_effects.inc"

/* R-NAME-0003: a statement that stays ambiguous after every type name is known declares an
 * object of a type that is not visible; each gets a diagnostic at its type name. */
static bool r_semantic_report_unresolved_declarations(RFrontendContext *context,
                                                      RSourceId source_id) {
    const RSource *source = r_get_source_const(context, source_id);
    if (source == NULL || !source->has_unresolved_ambiguity || source->has_lex_error ||
        source->has_syntax_error)
        return true;
    for (size_t index = 0U; index < source->cst_event_count; ++index) {
        const RCstEvent *event = &source->cst_events[index];
        if (event->kind != R_CST_EVENT_OPEN ||
            event->syntax_kind != R_SYNTAX_AMBIGUOUS_DECL_OR_EXPR)
            continue;
        for (size_t inner = index + 1U; inner < (size_t)event->matching_event; ++inner) {
            const RCstEvent *token_event = &source->cst_events[inner];
            if (token_event->kind != R_CST_EVENT_TOKEN ||
                token_event->token == R_TOKEN_ID_INVALID ||
                (size_t)token_event->token > source->token_count)
                continue;
            const RToken *token = &source->tokens[(size_t)token_event->token - 1U];
            if (token->kind != R_TOKEN_IDENTIFIER)
                continue;
            if (!r_semantic_add_diagnostic(context,
                                           "R-DIAG-NAME-001",
                                           "R-NAME-0003",
                                           "unresolved type name; an imported module's type is "
                                           "written module::Type or imported by name",
                                           token->span))
                return false;
            break;
        }
    }
    return true;
}

size_t r_frontend_entry_point_count(const RFrontendContext *context) {
    size_t count = 0U;

    if ((context == NULL) || !context->semantic_analyzed) {
        return 0U;
    }
    for (size_t index = 0U; index < context->semantic_symbol_count; ++index) {
        const RSemanticSymbol *symbol = &context->semantic_symbols[index];
        const RSource *source = r_get_source_const(context, symbol->module_source);
        if ((symbol->kind != R_SEMANTIC_SYMBOL_FUNCTION) || symbol->is_protected ||
            symbol->is_unsafe || symbol->is_extern_c || (symbol->generic_origin != 0U) ||
            symbol->is_synthetic || (source == NULL) ||
            !r_source_text_equal(source, symbol->name_span, "main") ||
            (r_semantic_value_kind(context, symbol->return_type) != R_SEMANTIC_TYPE_I32)) {
            continue;
        }
        if ((symbol->parameter_count == 0U) ||
            ((symbol->parameter_count == 1U) &&
             ((size_t)symbol->first_parameter_type < context->semantic_parameter_type_count) &&
             r_semantic_type_is_startup_arguments(
                 context, context->semantic_parameter_types[symbol->first_parameter_type]))) {
            count += 1U;
        }
    }
    return count;
}

RFrontendStatus r_analyze_program(RFrontendContext *context) {
    size_t source_index;
    bool source_invalid = false;
    bool discovered = false;

    if (context == NULL) {
        return R_FRONTEND_INVALID_ARGUMENT;
    }
    if (context->semantic_analyzed) {
        return context->semantic_status;
    }
    if (context->semantic_analyzing) {
        return R_FRONTEND_INTERNAL_ERROR;
    }
    context->semantic_analyzing = true;
    if (context->resource_status != R_FRONTEND_OK) {
        context->semantic_analyzing = false;
        return context->resource_status;
    }
    if (context->source_count == 0U) {
        context->semantic_analyzing = false;
        return R_FRONTEND_INVALID_ARGUMENT;
    }
    context->sources_sealed = true;
    for (source_index = 0U; source_index < context->source_count; ++source_index) {
        RAstNodeId root = R_AST_NODE_ID_INVALID;
        RFrontendStatus status =
            r_frontend_lower_ast(context, (RSourceId)(source_index + 1U), &root);
        if ((status != R_FRONTEND_OK) || (root == R_AST_NODE_ID_INVALID)) {
            if ((status != R_FRONTEND_NOT_LOWERABLE) && (status != R_FRONTEND_INVALID_SOURCE)) {
                context->semantic_analyzing = false;
                return status;
            }
            if (!r_semantic_report_unresolved_declarations(context,
                                                           (RSourceId)(source_index + 1U))) {
                context->semantic_analyzing = false;
                return context->resource_status;
            }
            source_invalid = true;
        }
    }
    if (!source_invalid) {
        bool rejected = false;
        if (!r_semantic_reject_library_profiles(context, &rejected)) {
            context->semantic_analyzing = false;
            return context->resource_status == R_FRONTEND_OK ? R_FRONTEND_INTERNAL_ERROR
                                                             : context->resource_status;
        }
        source_invalid = rejected;
    }
    /* R-META-0002: constant conditions of module `@if` select declarations before any is
       collected, so the discovery pass that computes them runs first. */
    if (!source_invalid && !context->consteval_discovery) {
        bool conditions = false;
        if (!r_static_module_conditions(context, &conditions) ||
            (conditions && !r_consteval_discover(context))) {
            context->semantic_analyzing = false;
            return (context->resource_status == R_FRONTEND_OK) ? R_FRONTEND_INTERNAL_ERROR
                                                               : context->resource_status;
        }
        discovered = conditions;
    }
    if (!source_invalid &&
        (!r_static_select_modules(context) || !r_resource_validate_attribute_positions(context) ||
         !r_must_use_validate_attribute_positions(context) ||
         !r_conditional_validate_positions(context) || context->resource_status != R_FRONTEND_OK)) {
        context->semantic_analyzing = false;
        return context->resource_status == R_FRONTEND_OK ? R_FRONTEND_INTERNAL_ERROR
                                                         : context->resource_status;
    }
    if (source_invalid || r_semantic_has_errors(context)) {
        context->semantic_analyzing = false;
        context->semantic_analyzed = true;
        context->semantic_status = R_FRONTEND_INVALID_SOURCE;
        return R_FRONTEND_INVALID_SOURCE;
    }
    /* R-EXPR-0032: module-scope declarations that need translation-time values are checked
       after a discovery pass has computed those values. */
    if (!context->consteval_discovery && !discovered) {
        bool discovery = false;
        if (!r_consteval_needs_discovery(context, &discovery) ||
            (discovery && !r_consteval_discover(context))) {
            context->semantic_analyzing = false;
            return (context->resource_status == R_FRONTEND_OK) ? R_FRONTEND_INTERNAL_ERROR
                                                               : context->resource_status;
        }
    }
    if (!r_semantic_initialize_types(context)) {
        context->semantic_analyzing = false;
        return context->resource_status;
    }
    if (!r_generic_register_headers(context) || !r_semantic_collect_aggregate_headers(context) ||
        !r_semantic_collect_traits(context) || !r_generic_resolve_trait_constraints(context) ||
        !r_generic_resolve_projection_constraints(context) ||
        !r_semantic_collect_module_bindings(context) ||
        !r_semantic_collect_aggregate_members(context) || !r_attributes_resolve(context) ||
        !r_derive_reject_families(context) || !r_generic_resolve_callable_constraints(context) ||
        !r_pack_finalize_parameters(context) || !r_semantic_collect_impls(context) ||
        context->resource_status != R_FRONTEND_OK) {
        context->semantic_analyzing = false;
        return (context->resource_status == R_FRONTEND_OK) ? R_FRONTEND_INTERNAL_ERROR
                                                           : context->resource_status;
    }
    for (source_index = 0U; source_index < context->source_count; ++source_index) {
        if (!r_semantic_collect_source(context, (RSourceId)(source_index + 1U)) ||
            context->resource_status != R_FRONTEND_OK) {
            context->semantic_analyzing = false;
            return (context->resource_status == R_FRONTEND_OK) ? R_FRONTEND_INTERNAL_ERROR
                                                               : context->resource_status;
        }
    }
    if (!r_out_validate_signatures(context) || !r_generic_finish_associated(context) ||
        !r_derive_validate(context) || !r_semantic_validate_impls(context) ||
        !r_semantic_validate_lending(context) || !r_semantic_validate_chain(context) ||
        !r_dyn_validate_contracts(context) || !r_generic_validate_definitions(context) ||
        !r_semantic_validate_trait_applications(context) || !r_semantic_validate_imports(context) ||
        !r_semantic_validate_import_shadowing(context) ||
        !r_semantic_validate_borrowed_outputs(context) ||
        !r_semantic_validate_exported_signatures(context) ||
        context->resource_status != R_FRONTEND_OK) {
        context->semantic_analyzing = false;
        return (context->resource_status == R_FRONTEND_OK) ? R_FRONTEND_INTERNAL_ERROR
                                                           : context->resource_status;
    }
    /* R-FUNC-0023: every function signature is known; bodies may now be lowered on demand. */
    context->consteval_ready = true;
    if (!r_consteval_check_impl_constants(context) || !r_consteval_check_computed_bounds(context) ||
        !r_json_validate_contracts(context) || !r_json_validate_defaults(context) ||
        !r_hir_build_program(context) || !r_json_validate_contracts(context) ||
        !r_generic_check_key_bodies(context) || !r_opaque_prepare_representations(context) ||
        !r_function_items_lower_calls(context) || !r_generic_order_aggregates(context) ||
        !r_semantic_validate_stack_graph(context) ||
        !r_semantic_validate_resource_effects(context) || !r_semantic_validate_must_use(context) ||
        (!r_semantic_has_errors(context) &&
         (!r_out_validate_uses(context) || !r_semantic_validate_local_reassignment(context))) ||
        !r_consteval_fold_program(context) || context->resource_status != R_FRONTEND_OK) {
        context->hir_root = R_HIR_NODE_ID_INVALID;
        context->semantic_analyzing = false;
        return (context->resource_status == R_FRONTEND_OK) ? R_FRONTEND_INTERNAL_ERROR
                                                           : context->resource_status;
    }
    for (source_index = 0U; source_index < context->source_count; ++source_index) {
        context->sources[source_index].semantically_analyzed = true;
    }
    context->semantic_analyzing = false;
    context->semantic_analyzed = true;
    context->semantic_status =
        r_semantic_has_errors(context) ? R_FRONTEND_INVALID_SOURCE : R_FRONTEND_OK;
    return context->semantic_status;
}

#include "generic_constants.inc"
